param(
    [Parameter(Mandatory = $true)]
    [string]$BaseUrl,

    [Parameter(Mandatory = $true)]
    [string]$Username,

    [string]$Client = "200",

    [string]$Language = "EN",

    [Parameter(Mandatory = $true)]
    [ValidateSet(
        "DiagnoseHelperApis",
        "InspectStructures",
        "InspectInterface",
        "InspectRepositoryApis",
        "InspectGuiApis",
        "InspectGuiObject",
        "InspectDdicApis",
        "DiagnoseDdicObject",
        "Install",
        "RepairInterface",
        "InstallRepositoryApi",
        "RepairRepositoryApi",
        "InstallDdicApi",
        "RepairDdicApi",
        "DiagnoseFunctionGroup",
        "DiagnoseRepositoryApi",
        "InspectAssignment",
        "AssignPackageTransport"
    )]
    [string]$Action,

    [ValidatePattern('^[ZY][A-Z0-9_]{0,29}$')]
    [string]$DdicObjectName = "ZCODEX_MCP_DE_0831",

    [ValidatePattern('^[A-Z/][A-Z0-9_/]{0,39}$')]
    [string]$GuiProgramName = "ZCODEX_MCP_DYNPRO",

    [ValidateSet("DOMA", "DTEL", "TABL", "TTYP")]
    [string]$DdicObjectType = "DTEL",

    [ValidatePattern('^[A-Z0-9]{10}$')]
    [string]$TransportNumber,

    [ValidatePattern('^[A-Z0-9]{10}$')]
    [string]$TransportTask,

    [ValidatePattern('^[A-Z/][A-Z0-9_/]{0,39}$')]
    [string]$PackageName = "ZABAP",

    [string]$ResultPath,

    [Security.SecureString]$SecurePassword,

    [switch]$AllowUnauthorized,

    [switch]$PassThru
)

$ErrorActionPreference = "Stop"

# Single source of truth for the CAPABILITIES self-description of the repository
# helper body ($repositoryFunctionSource). That body is shared by
# Z_ORVANTA_MCP_EXECUTE and Z_ORVANTA_MCP_DYNPRO_API, so both self-describe with
# the function module name they were generated for.
#
# Entry format: "<OPCODE>|<sinceVersion>|<R|W>". `sinceVersion` is the highest
# ev_version reported by that CASE branch, and PROTOCOL|MIN / PROTOCOL|MAX plus
# every OPERATION line are derived from this table -- never written a second time.
# Parsed offline by test/helper-capabilities-payload.test.ts.
# >>> ORVANTA-CAPABILITY-TABLE
$helperCapabilityOperations = @(
    "READ_ENHANCEMENT_IMPLEMENTATION|2.6|R",
    "MANAGE_ENHANCEMENT_STATE|2.6|W",
    "DELETE_ENHANCEMENT_IMPLEMENTATION|2.5|W",
    "MANAGE_CLASSIC_BADI_IMPLEMENTATION|2.5|W",
    "READ_CLASSIC_BADI_DEFINITION|2.4|R",
    "READ_BTE_CONFIGURATION|2.3|R",
    "READ_CUSTOMER_EXIT_DEFINITION|2.2|R",
    "READ_CUSTOMER_EXIT_PROJECT|2.2|R",
    "CREATE_FUNCTION_GROUP|1.3|W",
    "CREATE_FUNCTION_INCLUDE|1.7|W",
    "READ_FUNCTION_INTERFACE|2.1|R",
    "CREATE_FUNCTION_MODULE|2.0|W",
    "PATCH_FUNCTION_INTERFACE|2.0|W",
    "INSPECT_REPOSITORY_ASSIGNMENT|1.3|R",
    "READ_GUI_DEFINITION|1.5|R",
    "PATCH_GUI_DEFINITION|1.5|W",
    "READ_SCREEN|1.1|R",
    "PATCH_SCREEN|1.4|W",
    "UPSERT_SCREEN|1.1|W",
    "DELETE_TRANSACTION|1.6|W",
    "DELETE_MODULE_POOL|1.6|W",
    "CREATE_MODULE_POOL|1.1|W",
    "READ_TRANSPORT_DETAILS|1.7|R",
    "DELETE_MESSAGE_CLASS|1.9|W",
    "UPDATE_MESSAGE_CLASS|1.8|W",
    "READ_TRANSACTION|1.2|R",
    "CREATE_REPORT_TRANSACTION|1.2|W",
    "CREATE_TRANSACTION|1.1|W",
    # Operations the repository CASE serves through shared clauses: a multi-opcode WHEN
    # ('X' OR 'Y'.) or a WHEN continued on the next line. A single-opcode scan of the CASE
    # misses these, so they are listed here explicitly and kept adjacent for review.
    "UPDATE_HOOK_ENHANCEMENT|2.6|W",
    "UPDATE_BADI_ENHANCEMENT|2.6|W",
    "CREATE_HOOK_ENHANCEMENT|2.5|W",
    "CREATE_BADI_ENHANCEMENT|2.5|W",
    "READ_TEXT_ELEMENTS|1.7|R",
    "MERGE_TEXT_ELEMENTS|1.7|W",
    "READ_MESSAGE_CLASS|1.2|R",
    "CREATE_MESSAGE_CLASS|1.2|W"
)
# <<< ORVANTA-CAPABILITY-TABLE

# Separately approved scopes of the repository helper. Empty on purpose: the
# REPORT_PARAMETERS scope belongs to Z_ORVANTA_OPS_READ
# (scripts/report-parameters-source.mjs), not to this body. Add
# "<SCOPE>|<enabled|disabled>" entries here to publish a scope.
$helperCapabilityScopes = @()

# PROTOCOL|MIN is the oldest protocol revision this helper still implements
# (lowest sinceVersion); PROTOCOL|MAX is the highest revision it implements.
$helperCapabilityVersions = $helperCapabilityOperations | ForEach-Object {
    $capabilityTableParts = $_ -split "\|"
    [version]$capabilityTableParts[1]
}
$helperCapabilityMinVersion = (
    $helperCapabilityVersions | Sort-Object | Select-Object -First 1
).ToString()
$helperCapabilityMaxVersion = (
    $helperCapabilityVersions | Sort-Object -Descending | Select-Object -First 1
).ToString()

function New-InspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lv_name TYPE string.",
        "DO 2 TIMES.",
        "  IF sy-index = 1.",
        "    lv_name = 'RSIMP'.",
        "  ELSE.",
        "    lv_name = 'RSEXP'.",
        "  ENDIF.",
        "  lo_descr ?= cl_abap_typedescr=>describe_by_name( lv_name ).",
        "  lt_components = lo_descr->get_components( ).",
        "  WRITE: / 'STRUCT', lv_name.",
        "  LOOP AT lt_components INTO ls_component.",
        "    WRITE: / ls_component-name.",
        "  ENDLOOP.",
        "ENDDO."
    )
}

function New-InterfaceInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_change TYPE TABLE OF rscha.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_except TYPE TABLE OF rsexc.",
        "DATA lt_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA lv_remote TYPE rs38l-remote.",
        "DATA lv_line TYPE string.",
        "CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "  EXPORTING functionname = 'RFC_SYSTEM_INFO'",
        "  IMPORTING remote_call = lv_remote",
        "  TABLES import_parameter = lt_import",
        "    changing_parameter = lt_change",
        "    export_parameter = lt_export",
        "    tables_parameter = lt_tables",
        "    exception_list = lt_except",
        "    documentation = lt_docu",
        "    source = lt_source.",
        "WRITE: / 'REMOTE', lv_remote.",
        "LOOP AT lt_import INTO ls_import.",
        "  CONCATENATE 'I' ls_import-parameter ls_import-dbfield",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_import-types ls_import-optional",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_import-reference ls_import-typ",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDLOOP.",
        "LOOP AT lt_export INTO ls_export.",
        "  CONCATENATE 'E' ls_export-parameter ls_export-dbfield",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_export-types ls_export-reference",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_export-typ",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDLOOP."
    )
}

function New-RepositoryApiInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_change TYPE TABLE OF rscha.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_except TYPE TABLE OF rsexc.",
        "DATA lt_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA ls_change TYPE rscha.",
        "DATA ls_tables TYPE rstbl.",
        "DATA ls_seocompo TYPE seocompo.",
        "DATA ls_seometarel TYPE seometarel.",
        "DATA ls_dd03l TYPE dd03l.",
        "FIELD-SYMBOLS <lv_table_value> TYPE any.",
        "DATA lv_name TYPE rs38l-name.",
        "DATA lv_existing_name TYPE rs38l-name.",
        "DATA lv_line TYPE string.",
        "DATA lv_remote TYPE rs38l-remote.",
        "DATA lt_names TYPE TABLE OF string.",
        "DATA lo_intf TYPE REF TO cl_abap_intfdescr.",
        "DATA ls_method TYPE abap_methdescr.",
        "DATA ls_parameter TYPE abap_parmdescr.",
        "SELECT * FROM seocompo INTO ls_seocompo",
        "  WHERE clsname = 'IF_ENH_TOOL'",
        "     OR clsname = 'IF_ENH_OBJECT'",
        "     OR clsname = 'IF_ENH_OBJECT_DOCU'.",
        "  WRITE: / 'OO_METHOD', ls_seocompo-clsname,",
        "    ls_seocompo-cmpname, ls_seocompo-cmptype.",
        "ENDSELECT.",
        "SELECT * FROM seometarel INTO ls_seometarel",
        "  WHERE clsname = 'IF_ENH_TOOL'",
        "     OR clsname = 'IF_ENH_OBJECT'",
        "     OR clsname = 'IF_ENH_OBJECT_DOCU'.",
        "  WRITE: / 'OO_RELATION', ls_seometarel-clsname,",
        "    ls_seometarel-refclsname, ls_seometarel-reltype.",
        "ENDSELECT.",
        "SELECT * FROM dd03l INTO ls_dd03l",
        "  WHERE as4local = 'A'",
        "    AND ( tabname = 'TBE24' OR tabname = 'TBE34'",
        "       OR tabname = 'TPS24' OR tabname = 'TPS34' ).",
        "  WRITE: / 'DDIC_FIELD', ls_dd03l-tabname,",
        "    ls_dd03l-fieldname, ls_dd03l-position, ls_dd03l-rollname.",
        "ENDSELECT.",
        "lo_intf ?= cl_abap_typedescr=>describe_by_name(",
        "  'IF_ENH_OBJECT_DOCU' ).",
        "READ TABLE lo_intf->methods INTO ls_method",
        "  WITH KEY name = 'SET_SHORTTEXT'.",
        "IF sy-subrc = 0.",
        "  LOOP AT ls_method-parameters INTO ls_parameter.",
        "    WRITE: / 'OO_PARAMETER', ls_parameter-name,",
        "      ls_parameter-parm_kind, ls_parameter-type_kind,",
        "      ls_parameter-length, ls_parameter-decimals.",
        "  ENDLOOP.",
        "ENDIF.",
        "SELECT funcname FROM tfdir INTO lv_name",
        "  WHERE funcname LIKE 'RPY%MESS%'",
        "     OR funcname LIKE 'RS%TEXTPOOL%'.",
        "  CONCATENATE 'CANDIDATE' lv_name",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDSELECT.",
        "APPEND 'RSIMP' TO lt_names.",
        "APPEND 'RSEXP' TO lt_names.",
        "APPEND 'RSCHA' TO lt_names.",
        "APPEND 'RSTBL' TO lt_names.",
        "APPEND 'RSEXC' TO lt_names.",
        "APPEND 'RSFDO' TO lt_names.",
        "APPEND 'D020S' TO lt_names.",
        "APPEND 'D021S' TO lt_names.",
        "APPEND 'D022S' TO lt_names.",
        "APPEND 'D023S' TO lt_names.",
        "APPEND 'RPY_DYHEAD' TO lt_names.",
        "APPEND 'RPY_DYCATT' TO lt_names.",
        "APPEND 'RPY_DYFATC' TO lt_names.",
        "APPEND 'RPY_DYFLOW' TO lt_names.",
        "APPEND 'RPY_DYPARA' TO lt_names.",
        "APPEND 'TEXTPOOL' TO lt_names.",
        "APPEND 'T100' TO lt_names.",
        "APPEND 'T100A' TO lt_names.",
        "APPEND 'TSTC' TO lt_names.",
        "APPEND 'TSTCC' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  lo_descr ?= cl_abap_typedescr=>describe_by_name( lv_name ).",
        "  lt_components = lo_descr->get_components( ).",
        "  WRITE: / 'STRUCT', lv_name.",
        "  LOOP AT lt_components INTO ls_component.",
        "    WRITE / ls_component-name.",
        "  ENDLOOP.",
        "ENDLOOP.",
        "REFRESH lt_names.",
        "APPEND 'RPY_DYNPRO_READ' TO lt_names.",
        "APPEND 'RPY_DYNPRO_INSERT' TO lt_names.",
        "APPEND 'RPY_DYNPRO_READ_NATIVE' TO lt_names.",
        "APPEND 'RPY_DYNPRO_INSERT_NATIVE' TO lt_names.",
        "APPEND 'RPY_DYNPRO_DELETE' TO lt_names.",
        "APPEND 'RPY_PROGRAM_INSERT' TO lt_names.",
        "APPEND 'RPY_PROGRAM_UPDATE' TO lt_names.",
        "APPEND 'RPY_PROGRAM_DELETE' TO lt_names.",
        "APPEND 'RS_DELETE_PROGRAM' TO lt_names.",
        "APPEND 'RPY_TRANSACTION_READ' TO lt_names.",
        "APPEND 'RPY_TRANSACTION_INSERT' TO lt_names.",
        "APPEND 'RPY_TRANSACTION_DELETE' TO lt_names.",
        "APPEND 'RPY_MESSAGE_ID_READ' TO lt_names.",
        "APPEND 'RPY_MESSAGE_ID_INSERT' TO lt_names.",
        "APPEND 'RPY_MESSAGE_ID_SELECT' TO lt_names.",
        "APPEND 'RPY_MESSAGE_READ' TO lt_names.",
        "APPEND 'RPY_EXISTENCE_CHECK_MESS' TO lt_names.",
        "APPEND 'RS_TEXTPOOL_READ' TO lt_names.",
        "APPEND 'RS_TEXTPOOL_GET' TO lt_names.",
        "APPEND 'RS_TEXTPOOL_ADD' TO lt_names.",
        "APPEND 'MESSAGES_ACTIVE' TO lt_names.",
        "APPEND 'RS_CORR_INSERT' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  CLEAR lv_existing_name.",
        "  SELECT SINGLE funcname FROM tfdir INTO lv_existing_name",
        "    WHERE funcname = lv_name.",
        "  IF sy-subrc <> 0.",
        "    CONCATENATE 'FUNCTION_MISSING' lv_name",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  REFRESH: lt_import, lt_export, lt_change, lt_tables,",
        "    lt_except, lt_docu, lt_source.",
        "  CLEAR lv_remote.",
        "  CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "    EXPORTING functionname = lv_name",
        "    IMPORTING remote_call = lv_remote",
        "    TABLES import_parameter = lt_import",
        "      changing_parameter = lt_change",
        "      export_parameter = lt_export",
        "      tables_parameter = lt_tables",
        "      exception_list = lt_except",
        "      documentation = lt_docu",
        "      source = lt_source.",
        "  WRITE: / 'FUNCTION', lv_name, lv_remote.",
        "  LOOP AT lt_import INTO ls_import.",
        "    CONCATENATE 'I' ls_import-parameter",
        "      ls_import-dbfield INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_export INTO ls_export.",
        "    CONCATENATE 'E' ls_export-parameter",
        "      ls_export-dbfield INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_change INTO ls_change.",
        "    CONCATENATE 'C' ls_change-parameter",
        "      ls_change-dbfield INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_tables INTO ls_tables.",
        "    CLEAR lv_line.",
        "    ASSIGN COMPONENT 'PARAMETER' OF STRUCTURE ls_tables",
        "      TO <lv_table_value>.",
        "    IF sy-subrc = 0.",
        "      CONCATENATE 'T' <lv_table_value>",
        "        INTO lv_line SEPARATED BY '|'.",
        "    ENDIF.",
        "    ASSIGN COMPONENT 'DBSTRUCT' OF STRUCTURE ls_tables",
        "      TO <lv_table_value>.",
        "    IF sy-subrc = 0.",
        "      CONCATENATE lv_line <lv_table_value>",
        "        INTO lv_line SEPARATED BY '|'.",
        "    ENDIF.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "ENDLOOP."
    )
}

function New-GuiApiInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lt_dfies TYPE TABLE OF dfies.",
        "DATA ls_dfies TYPE dfies.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_change TYPE TABLE OF rscha.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_except TYPE TABLE OF rsexc.",
        "DATA lt_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA ls_change TYPE rscha.",
        "DATA ls_tables TYPE rstbl.",
        "DATA ls_except TYPE rsexc.",
        "DATA lv_name TYPE rs38l-name.",
        "DATA lv_existing_name TYPE rs38l-name.",
        "DATA lv_type_name TYPE string.",
        "DATA lv_existing_type TYPE ddobjname.",
        "DATA lv_line TYPE string.",
        "DATA lv_subrc_text TYPE c LENGTH 10.",
        "DATA lv_remote TYPE rs38l-remote.",
        "DATA lt_names TYPE TABLE OF string.",
        "DATA lt_type_names TYPE TABLE OF string.",
        "SELECT funcname FROM tfdir INTO lv_name",
        "  WHERE funcname LIKE 'RS%CUA%'",
        "     OR funcname LIKE 'RPY%MENU%'",
        "     OR funcname LIKE 'RPY%STATUS%'.",
        "  CONCATENATE 'CANDIDATE' lv_name",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDSELECT.",
        "APPEND 'RS_CUA_INTERNAL_FETCH' TO lt_names.",
        "APPEND 'RS_CUA_INTERNAL_WRITE' TO lt_names.",
        "APPEND 'RS_CUA_INSERT' TO lt_names.",
        "APPEND 'RS_CUA_DELETE' TO lt_names.",
        "APPEND 'RS_CUA_COPY' TO lt_names.",
        "APPEND 'RPY_PROGRAM_READ' TO lt_names.",
        "APPEND 'RPY_PROGRAM_UPDATE' TO lt_names.",
        "APPEND 'RPY_PROGRAM_INSERT' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  CLEAR lv_existing_name.",
        "  SELECT SINGLE funcname FROM tfdir INTO lv_existing_name",
        "    WHERE funcname = lv_name.",
        "  IF sy-subrc <> 0.",
        "    CONCATENATE 'FUNCTION_MISSING' lv_name",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  REFRESH: lt_import, lt_export, lt_change, lt_tables,",
        "    lt_except, lt_docu, lt_source.",
        "  CLEAR lv_remote.",
        "  CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "    EXPORTING functionname = lv_name",
        "    IMPORTING remote_call = lv_remote",
        "    TABLES import_parameter = lt_import",
        "      changing_parameter = lt_change",
        "      export_parameter = lt_export",
        "      tables_parameter = lt_tables",
        "      exception_list = lt_except",
        "      documentation = lt_docu",
        "      source = lt_source.",
        "  CONCATENATE 'FUNCTION' lv_name lv_remote",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "  LOOP AT lt_import INTO ls_import.",
        "    CONCATENATE 'I' ls_import-parameter ls_import-dbfield",
        "      ls_import-types ls_import-optional ls_import-reference",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_export INTO ls_export.",
        "    CONCATENATE 'E' ls_export-parameter ls_export-dbfield",
        "      ls_export-types ls_export-reference",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_change INTO ls_change.",
        "    CONCATENATE 'C' ls_change-parameter ls_change-dbfield",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_tables INTO ls_tables.",
        "    CONCATENATE 'T' ls_tables-parameter ls_tables-dbstruct",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_except INTO ls_except.",
        "    CONCATENATE 'X' ls_except-exception",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "ENDLOOP.",
        "APPEND 'TRKEY' TO lt_type_names.",
        "APPEND 'RSMPE_ADM' TO lt_type_names.",
        "APPEND 'RSMPE_STAT' TO lt_type_names.",
        "APPEND 'RSMPE_FUNT' TO lt_type_names.",
        "APPEND 'RSMPE_MEN' TO lt_type_names.",
        "APPEND 'RSMPE_MNLT' TO lt_type_names.",
        "APPEND 'RSMPE_ACT' TO lt_type_names.",
        "APPEND 'RSMPE_BUT' TO lt_type_names.",
        "APPEND 'RSMPE_PFK' TO lt_type_names.",
        "APPEND 'RSMPE_STAF' TO lt_type_names.",
        "APPEND 'RSMPE_ATRT' TO lt_type_names.",
        "APPEND 'RSMPE_TITT' TO lt_type_names.",
        "APPEND 'RSMPE_BUTS' TO lt_type_names.",
        "LOOP AT lt_type_names INTO lv_type_name.",
        "  CLEAR lv_existing_type.",
        "  SELECT SINGLE tabname FROM dd02l INTO lv_existing_type",
        "    WHERE tabname = lv_type_name",
        "      AND as4local = 'A' AND as4vers = '0000'.",
        "  IF sy-subrc <> 0.",
        "    CONCATENATE 'TYPE_MISSING' lv_type_name",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  REFRESH lt_dfies.",
        "  CALL FUNCTION 'DDIF_FIELDINFO_GET'",
        "    EXPORTING tabname = lv_existing_type langu = sy-langu",
        "    TABLES dfies_tab = lt_dfies",
        "    EXCEPTIONS not_found = 1 internal_error = 2 OTHERS = 3.",
        "  IF sy-subrc <> 0.",
        "    WRITE sy-subrc TO lv_subrc_text.",
        "    CONDENSE lv_subrc_text NO-GAPS.",
        "    CONCATENATE 'FIELDINFO_ERROR' lv_type_name lv_subrc_text",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  CONCATENATE 'STRUCT' lv_type_name",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "  LOOP AT lt_dfies INTO ls_dfies.",
        "    CONCATENATE 'FIELD' lv_type_name ls_dfies-fieldname",
        "      ls_dfies-rollname ls_dfies-inttype ls_dfies-leng",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "ENDLOOP."
    )
}

function New-GuiObjectInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA ls_adm TYPE rsmpe_adm.",
        "DATA lt_sta TYPE TABLE OF rsmpe_stat.",
        "DATA lt_fun TYPE TABLE OF rsmpe_funt.",
        "DATA lt_men TYPE TABLE OF rsmpe_men.",
        "DATA lt_mtx TYPE TABLE OF rsmpe_mnlt.",
        "DATA lt_act TYPE TABLE OF rsmpe_act.",
        "DATA lt_but TYPE TABLE OF rsmpe_but.",
        "DATA lt_pfk TYPE TABLE OF rsmpe_pfk.",
        "DATA lt_set TYPE TABLE OF rsmpe_staf.",
        "DATA lt_doc TYPE TABLE OF rsmpe_atrt.",
        "DATA lt_tit TYPE TABLE OF rsmpe_titt.",
        "DATA lt_biv TYPE TABLE OF rsmpe_buts.",
        "DATA ls_sta TYPE rsmpe_stat.",
        "DATA ls_fun TYPE rsmpe_funt.",
        "DATA ls_men TYPE rsmpe_men.",
        "DATA ls_mtx TYPE rsmpe_mnlt.",
        "DATA ls_act TYPE rsmpe_act.",
        "DATA ls_but TYPE rsmpe_but.",
        "DATA ls_pfk TYPE rsmpe_pfk.",
        "DATA ls_set TYPE rsmpe_staf.",
        "DATA ls_tit TYPE rsmpe_titt.",
        "DATA ls_biv TYPE rsmpe_buts.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_trdir TYPE trdir.",
        "DATA ls_tfdir TYPE tfdir.",
        "DATA lt_code TYPE TABLE OF abaptxt255.",
        "DATA ls_code TYPE abaptxt255.",
        "DATA lv_group TYPE rs38l-area.",
        "DATA lv_include TYPE sy-repid.",
        "DATA lv_lines TYPE i.",
        "DATA lv_langu TYPE eudb-langu.",
        "DATA lv_author TYPE eudb-autor.",
        "DATA lv_subrc_text TYPE c LENGTH 10.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "    AND obj_name = '$GuiProgramName'.",
        "WRITE: / 'TADIR', sy-subrc, ls_tadir-devclass,",
        "  ls_tadir-srcsystem, ls_tadir-genflag.",
        "SELECT SINGLE * FROM trdir INTO ls_trdir",
        "  WHERE name = '$GuiProgramName'.",
        "WRITE: / 'TRDIR', sy-subrc, ls_trdir-subc,",
        "  ls_trdir-rstat, ls_trdir-appl.",
        "READ REPORT '$GuiProgramName' INTO lt_code STATE 'A'.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'SOURCE_ACTIVE', sy-subrc, lv_lines.",
        "REFRESH lt_code.",
        "READ REPORT '$GuiProgramName' INTO lt_code STATE 'I'.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'SOURCE_INACTIVE', sy-subrc, lv_lines.",
        "CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "  EXPORTING program = '$GuiProgramName'",
        "    language = sy-langu state = 'A'",
        "  IMPORTING adm = ls_adm langu = lv_langu author = lv_author",
        "  TABLES sta = lt_sta fun = lt_fun men = lt_men",
        "    mtx = lt_mtx act = lt_act but = lt_but pfk = lt_pfk",
        "    set = lt_set doc = lt_doc tit = lt_tit biv = lt_biv",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE sy-subrc TO lv_subrc_text.",
        "CONDENSE lv_subrc_text NO-GAPS.",
        "WRITE: / 'FETCH', lv_subrc_text, '$GuiProgramName',",
        "  lv_langu, lv_author.",
        "WRITE: / 'ADM', ls_adm-actcode, ls_adm-mencode,",
        "  ls_adm-pfkcode, ls_adm-defaultact, ls_adm-defaultpfk,",
        "  ls_adm-mod_langu.",
        "LOOP AT lt_sta INTO ls_sta.",
        "  WRITE: / 'STA', ls_sta-code, ls_sta-modal,",
        "    ls_sta-actcode, ls_sta-pfkcode, ls_sta-butcode,",
        "    ls_sta-int_note, ls_sta-ctxcode.",
        "ENDLOOP.",
        "LOOP AT lt_fun INTO ls_fun.",
        "  WRITE: / 'FUN', ls_fun-code, ls_fun-textno,",
        "    ls_fun-type, ls_fun-modif, ls_fun-text_type,",
        "    ls_fun-text_name, ls_fun-icon_id, ls_fun-fun_text,",
        "    ls_fun-icon_text, ls_fun-info_text, ls_fun-path.",
        "ENDLOOP.",
        "LOOP AT lt_men INTO ls_men.",
        "  WRITE: / 'MEN', ls_men-code, ls_men-no,",
        "    ls_men-ref_type, ls_men-ref_code, ls_men-ref_no.",
        "ENDLOOP.",
        "LOOP AT lt_mtx INTO ls_mtx.",
        "  WRITE: / 'MTX', ls_mtx-code, ls_mtx-text_type,",
        "    ls_mtx-text_name, ls_mtx-inc_prog,",
        "    ls_mtx-inc_status, ls_mtx-text, ls_mtx-path,",
        "    ls_mtx-int_note.",
        "ENDLOOP.",
        "LOOP AT lt_act INTO ls_act.",
        "  WRITE: / 'ACT', ls_act-code, ls_act-no,",
        "    ls_act-menucode.",
        "ENDLOOP.",
        "LOOP AT lt_but INTO ls_but.",
        "  WRITE: / 'BUT', ls_but-pfk_code, ls_but-code,",
        "    ls_but-no, ls_but-pfno.",
        "ENDLOOP.",
        "LOOP AT lt_pfk INTO ls_pfk.",
        "  WRITE: / 'PFK', ls_pfk-code, ls_pfk-pfno,",
        "    ls_pfk-funcode, ls_pfk-funno.",
        "ENDLOOP.",
        "LOOP AT lt_set INTO ls_set.",
        "  WRITE: / 'SET', ls_set-status, ls_set-function.",
        "ENDLOOP.",
        "LOOP AT lt_tit INTO ls_tit.",
        "  WRITE: / 'TIT', ls_tit-code, ls_tit-text.",
        "ENDLOOP.",
        "LOOP AT lt_biv INTO ls_biv.",
        "  WRITE: / 'BIV', ls_biv-obj_code, ls_biv-sub_code,",
        "    ls_biv-fcode.",
        "ENDLOOP.",
        "SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "  WHERE funcname = 'RS_DELETE_PROGRAM'.",
        "lv_group = ls_tfdir-pname+4.",
        "CONCATENATE 'L' lv_group 'U' ls_tfdir-include",
        "  INTO lv_include.",
        "REFRESH lt_code.",
        "READ REPORT lv_include INTO lt_code.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'DELETE_SOURCE', sy-subrc, lv_include, lv_lines.",
        "LOOP AT lt_code INTO ls_code.",
        "  WRITE: / 'RSDP', sy-tabix, ls_code-line.",
        "ENDLOOP."
    )
}

function New-DdicApiInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lt_names TYPE TABLE OF string.",
        "DATA lv_name TYPE string.",
        "DATA lv_type_kind TYPE c LENGTH 1.",
        "DATA lv_length TYPE i.",
        "DATA lv_decimals TYPE i.",
        "DATA ls_dd01v TYPE dd01v.",
        "DATA lt_dd07v TYPE TABLE OF dd07v.",
        "DATA ls_dd04v TYPE dd04v.",
        "DATA ls_dd02v TYPE dd02v.",
        "DATA ls_dd09v TYPE dd09v.",
        "DATA lt_dd03p TYPE TABLE OF dd03p.",
        "DATA ls_dd40v TYPE dd40v.",
        "DATA lt_dd42v TYPE TABLE OF dd42v.",
        "DATA lt_dd43v TYPE TABLE OF dd43v.",
        "DATA lv_gotstate TYPE ddgotstate.",
        "FIELD-SYMBOLS <ls_any> TYPE any.",
        "APPEND 'DD01V' TO lt_names.",
        "APPEND 'DD07V' TO lt_names.",
        "APPEND 'DD04V' TO lt_names.",
        "APPEND 'DD02V' TO lt_names.",
        "APPEND 'DD03P' TO lt_names.",
        "APPEND 'DD40V' TO lt_names.",
        "APPEND 'DD42V' TO lt_names.",
        "APPEND 'DD43V' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  lo_descr ?= cl_abap_typedescr=>describe_by_name( lv_name ).",
        "  lt_components = lo_descr->get_components( ).",
        "  WRITE: / 'STRUCT', lv_name.",
        "  LOOP AT lt_components INTO ls_component.",
        "    lv_type_kind = ls_component-type->type_kind.",
        "    lv_length = ls_component-type->length.",
        "    lv_decimals = ls_component-type->decimals.",
        "    WRITE: / ls_component-name, lv_type_kind,",
        "      lv_length, lv_decimals.",
        "  ENDLOOP.",
        "ENDLOOP.",
        "CALL FUNCTION 'DDIF_DOMA_GET'",
        "  EXPORTING name = 'BOOLE_D' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd01v_wa = ls_dd01v",
        "  TABLES dd07v_tab = lt_dd07v",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE DOMA', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD01V' ls_dd01v.",
        "LOOP AT lt_dd07v ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD07V' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "CALL FUNCTION 'DDIF_DTEL_GET'",
        "  EXPORTING name = 'BAPI_MSG' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd04v_wa = ls_dd04v",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE DTEL', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD04V' ls_dd04v.",
        "CALL FUNCTION 'DDIF_TABL_GET'",
        "  EXPORTING name = 'BAPIRET2' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "    dd09l_wa = ls_dd09v",
        "  TABLES dd03p_tab = lt_dd03p",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE TABL', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD02V' ls_dd02v.",
        "LOOP AT lt_dd03p ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD03P' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "CALL FUNCTION 'DDIF_TTYP_GET'",
        "  EXPORTING name = 'BAPIRET2_T' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd40v_wa = ls_dd40v",
        "  TABLES dd42v_tab = lt_dd42v dd43v_tab = lt_dd43v",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE TTYP', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD40V' ls_dd40v.",
        "LOOP AT lt_dd42v ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD42V' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "LOOP AT lt_dd43v ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD43V' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "FORM dump_structure USING iv_label TYPE string",
        "  is_data TYPE any.",
        "  DATA lo_local TYPE REF TO cl_abap_structdescr.",
        "  DATA lt_local TYPE abap_component_tab.",
        "  DATA ls_local TYPE abap_componentdescr.",
        "  FIELD-SYMBOLS <lv_value> TYPE any.",
        "  lo_local ?= cl_abap_typedescr=>describe_by_data( is_data ).",
        "  lt_local = lo_local->get_components( ).",
        "  WRITE: / 'ROW', iv_label.",
        "  LOOP AT lt_local INTO ls_local.",
        "    ASSIGN COMPONENT ls_local-name OF STRUCTURE is_data",
        "      TO <lv_value>.",
        "    IF sy-subrc = 0 AND <lv_value> IS NOT INITIAL.",
        "      WRITE: / ls_local-name, <lv_value>.",
        "    ENDIF.",
        "  ENDLOOP.",
        "ENDFORM."
    )
}

function New-DdicObjectDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lt_check TYPE TABLE OF dcinspchk.",
        "DATA ls_check TYPE dcinspchk.",
        "DATA ls_dd02v TYPE dd02v.",
        "DATA ls_dd09v TYPE dd09v.",
        "DATA lt_dd03p TYPE TABLE OF dd03p.",
        "DATA ls_dd03p TYPE dd03p.",
        "DATA lv_gotstate TYPE ddgotstate.",
        "CALL FUNCTION 'DDIF_DD_CHECK'",
        "  EXPORTING objname = '$DdicObjectName'",
        "    objtype = '$DdicObjectType'",
        "  TABLES checktab = lt_check.",
        "LOOP AT lt_check INTO ls_check.",
        "  WRITE: / ls_check-kennz, ls_check-subrc,",
        "    ls_check-msgty, ls_check-msgid, ls_check-msgno,",
        "    ls_check-text.",
        "ENDLOOP.",
        "IF '$DdicObjectType' = 'TABL'.",
        "  CALL FUNCTION 'DDIF_TABL_GET'",
        "    EXPORTING name = '$DdicObjectName' state = 'M'",
        "      langu = sy-langu",
        "    IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "      dd09l_wa = ls_dd09v",
        "    TABLES dd03p_tab = lt_dd03p",
        "    EXCEPTIONS OTHERS = 1.",
        "  WRITE: / 'TABL', sy-subrc, lv_gotstate,",
        "    ls_dd02v-tabname, ls_dd02v-tabclass,",
        "    ls_dd02v-contflag, ls_dd02v-mainflag.",
        "  WRITE: / 'TECH', ls_dd09v-tabname, ls_dd09v-tabkat,",
        "    ls_dd09v-tabart, ls_dd09v-bufallow,",
        "    ls_dd09v-pufferung.",
        "  LOOP AT lt_dd03p INTO ls_dd03p.",
        "    WRITE: / 'FIELD', ls_dd03p-position,",
        "      ls_dd03p-fieldname, ls_dd03p-rollname,",
        "      ls_dd03p-keyflag, ls_dd03p-notnull,",
        "      ls_dd03p-comptype, ls_dd03p-datatype,",
        "      ls_dd03p-leng, ls_dd03p-decimals.",
        "  ENDLOOP.",
        "ENDIF."
    )
}

function New-DdicFunctionSource {
    return @(
        "  DATA ls_dd01v TYPE dd01v.",
        "  DATA lt_dd07v TYPE TABLE OF dd07v.",
        "  DATA ls_dd07v TYPE dd07v.",
        "  DATA ls_dd04v TYPE dd04v.",
        "  DATA ls_dd02v TYPE dd02v.",
        "  DATA ls_dd09v TYPE dd09v.",
        "  DATA ls_requested_dd09v TYPE dd09v.",
        "  DATA lt_dd03p TYPE TABLE OF dd03p.",
        "  DATA ls_dd03p TYPE dd03p.",
        "  DATA ls_dd40v TYPE dd40v.",
        "  DATA ls_current_dd01v TYPE dd01v.",
        "  DATA lt_current_dd07v TYPE TABLE OF dd07v.",
        "  DATA ls_current_dd04v TYPE dd04v.",
        "  DATA ls_current_dd02v TYPE dd02v.",
        "  DATA ls_current_dd09v TYPE dd09v.",
        "  DATA lt_current_dd03p TYPE TABLE OF dd03p.",
        "  DATA lt_append_dd03p TYPE TABLE OF dd03p.",
        "  DATA lt_checked_dd03p TYPE TABLE OF dd03p.",
        "  DATA ls_compare_dd03p TYPE dd03p.",
        "  DATA lt_act_res TYPE TABLE OF dctablres.",
        "  DATA ls_act_res TYPE dctablres.",
        "  DATA lt_expected_tbatg TYPE TABLE OF tbatg.",
        "  DATA lt_current_tbatg TYPE TABLE OF tbatg.",
        "  DATA ls_expected_tbatg TYPE tbatg.",
        "  DATA ls_current_tbatg TYPE tbatg.",
        "  DATA lt_object_range TYPE TABLE OF ddrange.",
        "  DATA lt_tabname_range TYPE TABLE OF ddrange.",
        "  DATA lt_indname_range TYPE TABLE OF ddrange.",
        "  DATA lt_tgorder_range TYPE TABLE OF ddrange.",
        "  DATA lt_fct_range TYPE TABLE OF ddrange.",
        "  DATA lt_execmode_range TYPE TABLE OF ddrange.",
        "  DATA lt_severity_range TYPE TABLE OF ddrange.",
        "  DATA lt_gdate_range TYPE TABLE OF ddrange.",
        "  DATA lt_guser_range TYPE TABLE OF ddrange.",
        "  DATA ls_range TYPE ddrange.",
        "  DATA ls_current_dd40v TYPE dd40v.",
        "  DATA lt_current_dd42v TYPE TABLE OF dd42v.",
        "  DATA lt_current_dd43v TYPE TABLE OF dd43v.",
        "  DATA lt_dd42v TYPE TABLE OF dd42v.",
        "  DATA ls_dd42v TYPE dd42v.",
        "  DATA lt_dd43v TYPE TABLE OF dd43v.",
        "  DATA ls_dd43v TYPE dd43v.",
        "  DATA ls_tadir TYPE tadir.",
        "  DATA ls_source TYPE abaptxt255.",
        "  DATA lv_kind TYPE c LENGTH 1.",
        "  DATA lv_index_text TYPE string.",
        "  DATA lv_index TYPE i.",
        "  DATA lv_property TYPE c LENGTH 30.",
        "  DATA lv_value TYPE string.",
        "  DATA lv_object_type TYPE tadir-object.",
        "  DATA: BEGIN OF ls_corr_object,",
        "    objtype TYPE e071-object,",
        "    objname TYPE e071-obj_name,",
        "  END OF ls_corr_object.",
        "  DATA lv_tadir_type TYPE tadir-object.",
        "  DATA lv_state_type TYPE ddobjtyp.",
        "  DATA lv_gotstate TYPE ddgotstate.",
        "  DATA lv_active_state TYPE ddgotstate.",
        "  DATA lv_current_version TYPE c LENGTH 14.",
        "  DATA lv_existing TYPE c LENGTH 1.",
        "  DATA lv_write TYPE c LENGTH 1.",
        "  DATA lv_delete TYPE c LENGTH 1.",
        "  DATA lv_append TYPE c LENGTH 1.",
        "  DATA lv_patch TYPE c LENGTH 1.",
        "  DATA lv_settings TYPE c LENGTH 1.",
        "  DATA lv_recover TYPE c LENGTH 1.",
        "  DATA lv_changed TYPE c LENGTH 1.",
        "  DATA lv_key_closed TYPE c LENGTH 1.",
        "  DATA lv_current_has_mandt TYPE c LENGTH 1.",
        "  DATA lv_final_has_mandt TYPE c LENGTH 1.",
        "  DATA lv_mode TYPE c LENGTH 1.",
        "  DATA lv_rc TYPE sy-subrc.",
        "  DATA lv_activation_subrc TYPE sy-subrc.",
        "  DATA lv_recorded_request TYPE trkorr.",
        "  DATA lv_ddic_name TYPE ddobjname.",
        "  DATA lv_as4date TYPE as4date.",
        "  DATA lv_as4time TYPE as4time.",
        "  DATA lv_deleted TYPE ddbool_d.",
        "  DATA lt_object_refs TYPE TABLE OF dcobjbez.",
        "  DATA ls_domain_dd01v TYPE dd01v.",
        "  DATA lt_domain_dd07v TYPE TABLE OF dd07v.",
        "  DATA ls_reference_dd04v TYPE dd04v.",
        "  DATA lv_reference_state TYPE ddgotstate.",
        "  DATA lv_text_length TYPE i.",
        "  DATA lv_append_count TYPE i.",
        "  DATA lv_field_count TYPE i.",
        "  DATA lv_current_field_count TYPE i.",
        "  DATA lv_current_complex_count TYPE i.",
        "  DATA lv_final_complex_count TYPE i.",
        "  FIELD-SYMBOLS <ls_value> TYPE dd07v.",
        "  FIELD-SYMBOLS <ls_field> TYPE dd03p.",
        "  FIELD-SYMBOLS <ls_tbatg> TYPE tbatg.",
        "  FIELD-SYMBOLS <lv_component> TYPE any.",
        "  DEFINE add_payload.",
        "    CLEAR ls_source.",
        "    lv_index_text = &2.",
        "    CONDENSE lv_index_text NO-GAPS.",
        "    lv_value = &4.",
        "    REPLACE ALL OCCURRENCES OF '%' IN lv_value WITH '%25'.",
        "    REPLACE ALL OCCURRENCES OF '|' IN lv_value WITH '%7C'.",
        "    CONCATENATE &1 lv_index_text &3 lv_value",
        "      INTO ls_source-line",
        "      SEPARATED BY '|'.",
        "    APPEND ls_source TO it_source.",
        "  END-OF-DEFINITION.",
        "  CASE iv_operation.",
        "    WHEN 'READ_DOMAIN'.",
        "      lv_object_type = 'DOMA'.",
        "    WHEN 'UPSERT_DOMAIN'.",
        "      lv_object_type = 'DOMA'.",
        "      lv_write = 'X'.",
        "    WHEN 'READ_DATA_ELEMENT'.",
        "      lv_object_type = 'DTEL'.",
        "    WHEN 'UPSERT_DATA_ELEMENT'.",
        "      lv_object_type = 'DTEL'.",
        "      lv_write = 'X'.",
        "    WHEN 'READ_STRUCTURE'.",
        "      lv_object_type = 'STRU'.",
        "    WHEN 'UPSERT_STRUCTURE'.",
        "      lv_object_type = 'STRU'.",
        "      lv_write = 'X'.",
        "    WHEN 'READ_TRANSPARENT_TABLE'.",
        "      lv_object_type = 'TABL'.",
        "    WHEN 'CREATE_TRANSPARENT_TABLE'.",
        "      lv_object_type = 'TABL'.",
        "      lv_write = 'X'.",
        "    WHEN 'APPEND_TRANSPARENT_TABLE_FIELDS'.",
        "      lv_object_type = 'TABL'.",
        "      lv_write = 'X'. lv_append = 'X'.",
        "    WHEN 'PATCH_TRANSPARENT_TABLE_FIELDS'.",
        "      lv_object_type = 'TABL'.",
        "      lv_write = 'X'. lv_patch = 'X'.",
        "    WHEN 'PATCH_TRANSPARENT_TABLE_SETTINGS'.",
        "      lv_object_type = 'TABL'.",
        "      lv_write = 'X'. lv_settings = 'X'.",
        "    WHEN 'RECOVER_TABLE_CONVERSION'.",
        "      lv_object_type = 'TABL'.",
        "      lv_write = 'X'. lv_recover = 'X'.",
        "    WHEN 'READ_TABLE_TYPE'.",
        "      lv_object_type = 'TTYP'.",
        "    WHEN 'UPSERT_TABLE_TYPE'.",
        "      lv_object_type = 'TTYP'.",
        "      lv_write = 'X'.",
        "    WHEN 'DELETE_DOMAIN'.",
        "      lv_object_type = 'DOMA'.",
        "      lv_write = 'X'. lv_delete = 'X'.",
        "    WHEN 'DELETE_DATA_ELEMENT'.",
        "      lv_object_type = 'DTEL'.",
        "      lv_write = 'X'. lv_delete = 'X'.",
        "    WHEN 'DELETE_STRUCTURE'.",
        "      lv_object_type = 'STRU'.",
        "      lv_write = 'X'. lv_delete = 'X'.",
        "    WHEN 'DELETE_TRANSPARENT_TABLE'.",
        "      lv_object_type = 'TABL'.",
        "      lv_write = 'X'. lv_delete = 'X'.",
        "    WHEN 'DELETE_TABLE_TYPE'.",
        "      lv_object_type = 'TTYP'.",
        "      lv_write = 'X'. lv_delete = 'X'.",
        "    WHEN OTHERS.",
        "      ev_status = 'E'. ev_code = 'OPERATION_NOT_SUPPORTED'.",
        "      ev_message = 'Unsupported DDIC operation'.",
        "      ev_version = '1.2'. RETURN.",
        "  ENDCASE.",
        "  IF iv_object_name IS INITIAL.",
        "    ev_status = 'E'. ev_code = 'OBJECT_NAME_REQUIRED'.",
        "    ev_message = 'DDIC object name is required'.",
        "    ev_version = '1.2'. RETURN.",
        "  ENDIF.",
        "  lv_ddic_name = iv_object_name.",
        "  IF lv_write = 'X'.",
        "    IF iv_object_name(1) <> 'Z'",
        "       AND iv_object_name(1) <> 'Y'.",
        "      ev_status = 'E'. ev_code = 'CUSTOMER_OBJECT_REQUIRED'.",
        "      ev_message = 'Only Z or Y DDIC objects are writable'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    lv_value = iv_object_name.",
        "    CONDENSE lv_value NO-GAPS.",
        "    IF lv_value CN 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'.",
        "      ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "      ev_message = 'Invalid customer DDIC object name'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "       OR iv_request IS INITIAL",
        "       OR ( iv_description IS INITIAL AND lv_delete IS INITIAL",
        "         AND lv_append IS INITIAL AND lv_patch IS INITIAL",
        "         AND lv_settings IS INITIAL AND lv_recover IS INITIAL ).",
        "      ev_status = 'E'. ev_code = 'WRITE_INPUT_REQUIRED'.",
        "      ev_message = 'Description package and request required'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF lv_write = 'X'.",
        "    LOOP AT it_source INTO ls_source.",
        "      CLEAR: lv_kind, lv_index_text, lv_property, lv_value.",
        "      SPLIT ls_source-line AT '|' INTO lv_kind lv_index_text",
        "        lv_property lv_value.",
        "      IF lv_index_text IS INITIAL",
        "         OR lv_index_text CN '0123456789'.",
        "        ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "        ev_message = 'DDIC payload index is invalid'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      lv_index = lv_index_text.",
        "      TRANSLATE lv_property TO UPPER CASE.",
        "      REPLACE ALL OCCURRENCES OF '%7C' IN lv_value WITH '|'.",
        "      REPLACE ALL OCCURRENCES OF '%25' IN lv_value WITH '%'.",
        "      IF lv_index <= 0 OR lv_property IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "        ev_message = 'DDIC payload is invalid'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      UNASSIGN <lv_component>.",
        "      CASE lv_kind.",
        "        WHEN 'H'.",
        "          IF lv_index <> 1.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Header index must be one'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          CASE lv_object_type.",
        "            WHEN 'DOMA'.",
        "              IF lv_property <> 'DATATYPE'",
        "                 AND lv_property <> 'LENG'",
        "                 AND lv_property <> 'OUTPUTLEN'",
        "                 AND lv_property <> 'DECIMALS'",
        "                 AND lv_property <> 'LOWERCASE'",
        "                 AND lv_property <> 'SIGNFLAG'",
        "                 AND lv_property <> 'ENTITYTAB'",
        "                 AND lv_property <> 'CONVEXIT'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Domain property not allowed'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'DATATYPE'",
        "                 AND lv_value <> 'CHAR' AND lv_value <> 'NUMC'",
        "                 AND lv_value <> 'DEC' AND lv_value <> 'DATS'",
        "                 AND lv_value <> 'TIMS'.",
        "                ev_status = 'E'. ev_code = 'DATATYPE_INVALID'.",
        "                ev_message = 'Unsupported domain data type'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF ( lv_property = 'LENG'",
        "                   OR lv_property = 'OUTPUTLEN'",
        "                   OR lv_property = 'DECIMALS' )",
        "                 AND ( lv_value IS INITIAL",
        "                   OR lv_value CN '0123456789' ).",
        "                ev_status = 'E'. ev_code = 'NUMBER_INVALID'.",
        "                ev_message = 'Domain length or decimals invalid'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF ( lv_property = 'LOWERCASE'",
        "                   OR lv_property = 'SIGNFLAG' )",
        "                 AND lv_value IS NOT INITIAL AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "                ev_message = 'Domain flag must be X or empty'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              ASSIGN COMPONENT lv_property",
        "                OF STRUCTURE ls_dd01v TO <lv_component>.",
        "            WHEN 'DTEL'.",
        "              IF lv_property <> 'DOMNAME'",
        "                 AND lv_property <> 'REPTEXT'",
        "                 AND lv_property <> 'SCRTEXT_S'",
        "                 AND lv_property <> 'SCRTEXT_M'",
        "                 AND lv_property <> 'SCRTEXT_L'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Data element property not allowed'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'DOMNAME'",
        "                 AND lv_value CN",
        "                   'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/'.",
        "                ev_status = 'E'. ev_code = 'REFERENCE_INVALID'.",
        "                ev_message = 'Invalid domain reference'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              ASSIGN COMPONENT lv_property",
        "                OF STRUCTURE ls_dd04v TO <lv_component>.",
            "            WHEN 'TTYP'.",
        "              IF lv_property <> 'ROWTYPE'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Table type property not allowed'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF lv_value IS INITIAL OR lv_value CN",
        "                   'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/'.",
        "                ev_status = 'E'. ev_code = 'REFERENCE_INVALID'.",
        "                ev_message = 'Invalid table row type reference'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
              "              ASSIGN COMPONENT lv_property",
              "                OF STRUCTURE ls_dd40v TO <lv_component>.",
        "            WHEN 'TABL'.",
        "              IF lv_property <> 'CONTFLAG'",
        "                 AND lv_property <> 'MAINFLAG'",
        "                 AND lv_property <> 'TABKAT'",
        "                 AND lv_property <> 'TABART'",
        "                 AND lv_property <> 'BUFALLOW'",
        "                 AND lv_property <> 'PUFFERUNG'",
        "                 AND lv_property <> 'SCHFELDANZ'",
        "                 AND lv_property <> 'PROTOKOLL'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Table property not allowed'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'TABART'",
        "                 AND lv_value <> 'APPL0'",
        "                 AND lv_value <> 'APPL1'",
        "                 AND lv_value <> 'APPL2'.",
        "                ev_status = 'E'. ev_code = 'DATA_CLASS_INVALID'.",
        "                ev_message = 'Invalid table data class'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'CONTFLAG'",
        "                 AND lv_value <> 'A' AND lv_value <> 'C'",
        "                 AND lv_value <> 'L' AND lv_value <> 'G'",
        "                 AND lv_value <> 'E' AND lv_value <> 'S'",
        "                 AND lv_value <> 'W'.",
        "                ev_status = 'E'.",
        "                ev_code = 'DELIVERY_CLASS_INVALID'.",
        "                ev_message = 'Invalid table delivery class'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'MAINFLAG'",
        "                 AND lv_value IS NOT INITIAL",
        "                 AND lv_value <> 'X' AND lv_value <> 'R'.",
        "                ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "                ev_message = 'Invalid table maintenance flag'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'TABKAT'",
        "                 AND ( lv_value IS INITIAL",
        "                   OR lv_value CN '01234' ).",
        "                ev_status = 'E'. ev_code = 'NUMBER_INVALID'.",
        "                ev_message = 'Invalid table size category'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'BUFALLOW'",
        "                 AND lv_value <> 'N' AND lv_value <> 'A'",
        "                 AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "                ev_message = 'Invalid table buffering allowance'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'PUFFERUNG'",
        "                 AND lv_value IS NOT INITIAL",
        "                 AND lv_value <> 'P' AND lv_value <> 'G'",
        "                 AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "                ev_message = 'Invalid table buffering mode'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_settings IS INITIAL",
        "                 AND ( ( lv_property = 'BUFALLOW'",
        "                   AND lv_value <> 'N' )",
        "                   OR ( lv_property = 'PUFFERUNG'",
        "                   AND lv_value IS NOT INITIAL ) ).",
        "                ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "                ev_message = 'New tables must disable buffering'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'SCHFELDANZ'",
        "                 AND lv_value IS NOT INITIAL",
        "                 AND lv_value CN '0123456789'.",
        "                ev_status = 'E'. ev_code = 'NUMBER_INVALID'.",
        "                ev_message = 'Invalid generic key field count'.",
        "                ev_version = '1.7'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'PROTOKOLL'",
        "                 AND lv_value IS NOT INITIAL AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "                ev_message = 'Log data changes must be X or empty'.",
        "                ev_version = '1.7'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'CONTFLAG'",
        "                 OR lv_property = 'MAINFLAG'.",
        "                ASSIGN COMPONENT lv_property",
        "                  OF STRUCTURE ls_dd02v TO <lv_component>.",
        "              ELSE.",
        "                ASSIGN COMPONENT lv_property",
        "                  OF STRUCTURE ls_dd09v TO <lv_component>.",
        "              ENDIF.",
            "            WHEN OTHERS.",
        "              ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "              ev_message = 'Structure has no header payload'.",
        "              ev_version = '1.2'. RETURN.",
        "          ENDCASE.",
        "        WHEN 'V'.",
        "          IF lv_object_type <> 'DOMA'",
        "             OR ( lv_property <> 'DOMVALUE_L'",
        "             AND lv_property <> 'DOMVALUE_H'",
        "             AND lv_property <> 'DDTEXT' ).",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Fixed value property not allowed'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd07v ) < lv_index.",
        "            CLEAR ls_dd07v. APPEND ls_dd07v TO lt_dd07v.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd07v ASSIGNING <ls_value>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_value> TO <lv_component>.",
        "        WHEN 'F'.",
        "          IF lv_recover = 'X'.",
        "            IF lv_property <> 'OBJECT'",
        "               AND lv_property <> 'TABNAME'",
        "               AND lv_property <> 'INDNAME'",
        "               AND lv_property <> 'TGORDER'",
        "               AND lv_property <> 'FCT'",
        "               AND lv_property <> 'EXECMODE'",
        "               AND lv_property <> 'SEVERITY'",
        "               AND lv_property <> 'GDATE'",
        "               AND lv_property <> 'GUSER'.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Conversion property not allowed'.",
        "              ev_version = '1.7'. RETURN.",
        "            ENDIF.",
        "            WHILE lines( lt_expected_tbatg ) < lv_index.",
        "              CLEAR ls_expected_tbatg.",
        "              APPEND ls_expected_tbatg TO lt_expected_tbatg.",
        "            ENDWHILE.",
        "            READ TABLE lt_expected_tbatg ASSIGNING <ls_tbatg>",
        "              INDEX lv_index.",
        "            ASSIGN COMPONENT lv_property",
        "              OF STRUCTURE <ls_tbatg> TO <lv_component>.",
        "          ELSE.",
        "          IF lv_object_type <> 'STRU' AND lv_object_type <> 'TABL'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Field payload not allowed'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          IF ( lv_property = 'PRECFIELD'",
        "               OR lv_property = 'COMPTYPE'",
        "               OR lv_property = 'ADMINFIELD'",
        "               OR lv_property = 'GROUPNAME'",
        "               OR lv_property = 'EXCLASS' )",
        "             AND lv_patch IS INITIAL.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Complex component metadata is read-only'.",
        "            ev_version = '1.7'. RETURN.",
        "          ENDIF.",
        "          IF lv_property <> 'FIELDNAME'",
        "             AND lv_property <> 'ROLLNAME'",
        "             AND ( lv_object_type <> 'TABL'",
        "               OR ( lv_property <> 'KEYFLAG'",
        "                 AND lv_property <> 'NOTNULL'",
        "                 AND lv_property <> 'PRECFIELD'",
        "                 AND lv_property <> 'COMPTYPE'",
        "                 AND lv_property <> 'ADMINFIELD'",
        "                 AND lv_property <> 'GROUPNAME'",
        "                 AND lv_property <> 'EXCLASS' ) ).",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Table field property not allowed'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          IF lv_property = 'FIELDNAME'",
        "             AND ( lv_value IS INITIAL OR lv_value CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_' )",
        "             AND ( lv_patch IS INITIAL OR lv_value CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-' ).",
        "            ev_status = 'E'. ev_code = 'FIELD_VALUE_INVALID'.",
        "            ev_message = 'Invalid structure field name'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          IF lv_property = 'ROLLNAME'",
        "             AND ( lv_value IS INITIAL OR lv_value CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/' )",
        "             AND lv_patch IS INITIAL.",
        "            ev_status = 'E'. ev_code = 'REFERENCE_INVALID'.",
        "            ev_message = 'Invalid data element reference'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          IF ( lv_property = 'KEYFLAG'",
        "               OR lv_property = 'NOTNULL' )",
        "             AND lv_value IS NOT INITIAL AND lv_value <> 'X'.",
        "            ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "            ev_message = 'Table field flag must be X or empty'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          IF lv_object_type = 'TABL'",
        "             AND lv_append IS INITIAL",
        "             AND lv_patch IS INITIAL",
        "             AND lv_property = 'NOTNULL' AND lv_value <> 'X'.",
        "            ev_status = 'E'. ev_code = 'NOTNULL_REQUIRED'.",
        "            ev_message = 'Transparent table fields must be not null'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd03p ) < lv_index.",
        "            CLEAR ls_dd03p. APPEND ls_dd03p TO lt_dd03p.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd03p ASSIGNING <ls_field>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_field> TO <lv_component>.",
        "          ENDIF.",
        "        WHEN OTHERS.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unknown DDIC payload row type'.",
        "          ev_version = '1.2'. RETURN.",
        "      ENDCASE.",
        "      IF <lv_component> IS NOT ASSIGNED.",
        "        ev_status = 'E'. ev_code = 'PROPERTY_INVALID'.",
        "        ev_message = 'Unknown DDIC payload property'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      <lv_component> = lv_value.",
        "    ENDLOOP.",
        "  ENDIF.",
        "  IF lv_settings = 'X'.",
        "    ls_requested_dd09v = ls_dd09v.",
        "  ENDIF.",
        "  IF lv_object_type = 'STRU'.",
        "    lv_tadir_type = 'TABL'.",
        "    lv_state_type = 'TABL'.",
        "  ELSE.",
        "    lv_tadir_type = lv_object_type.",
        "    lv_state_type = lv_object_type.",
        "  ENDIF.",
        "  IF lv_recover = 'X'.",
        "    IF lt_expected_tbatg[] IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'WORKLIST_REQUIRED'.",
        "      ev_message = 'Expected conversion worklist is required'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    LOOP AT lt_expected_tbatg INTO ls_expected_tbatg.",
        "      IF ls_expected_tbatg-object <> 'TABL'",
        "         OR ls_expected_tbatg-tabname <> iv_object_name.",
        "        ev_status = 'E'. ev_code = 'WORKLIST_SCOPE_INVALID'.",
        "        ev_message = 'Conversion entry is outside target table'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDLOOP.",
        "    SELECT SINGLE * FROM tadir INTO ls_tadir",
        "      WHERE pgmid = 'R3TR' AND object = 'TABL'",
        "        AND obj_name = iv_object_name.",
        "    IF sy-subrc <> 0.",
        "      ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "      ev_message = 'Transparent table does not exist'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    IF ls_tadir-devclass <> iv_package.",
        "      ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "      ev_message = 'Existing object belongs to another package'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CLEAR ls_current_dd02v-tabclass.",
        "    SELECT SINGLE tabclass FROM dd02l",
        "      INTO ls_current_dd02v-tabclass",
        "      WHERE tabname = iv_object_name AND as4local = 'A'.",
        "    IF sy-subrc <> 0 OR ls_current_dd02v-tabclass <> 'TRANSP'.",
        "      ev_status = 'E'. ev_code = 'OBJECT_TYPE_MISMATCH'.",
        "      ev_message = 'Dictionary object is not a transparent table'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    SELECT * FROM tbatg INTO TABLE lt_current_tbatg",
        "      WHERE object = 'TABL' AND tabname = iv_object_name.",
        "    SORT lt_expected_tbatg BY object tabname indname tgorder",
        "      fct execmode severity gdate guser.",
        "    SORT lt_current_tbatg BY object tabname indname tgorder",
        "      fct execmode severity gdate guser.",
        "    DESCRIBE TABLE lt_expected_tbatg LINES lv_field_count.",
        "    DESCRIBE TABLE lt_current_tbatg LINES lv_current_field_count.",
        "    IF lv_field_count <> lv_current_field_count.",
        "      ev_status = 'E'. ev_code = 'WORKLIST_CONFLICT'.",
        "      ev_message = 'Native conversion worklist changed'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    LOOP AT lt_expected_tbatg INTO ls_expected_tbatg.",
        "      READ TABLE lt_current_tbatg INTO ls_current_tbatg",
        "        INDEX sy-tabix.",
        "      IF sy-subrc <> 0",
        "         OR ls_current_tbatg <> ls_expected_tbatg.",
        "        ev_status = 'E'. ev_code = 'WORKLIST_CONFLICT'.",
        "        ev_message = 'Native conversion worklist changed'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDLOOP.",
        "    CLEAR: ls_corr_object, lv_recorded_request.",
        "    ls_corr_object-objtype = 'TABL'.",
        "    ls_corr_object-objname = iv_object_name.",
        "    CALL FUNCTION 'RS_CORR_INSERT'",
        "      EXPORTING object = ls_corr_object",
        "        object_class = 'DICT' mode = 'M'",
        "        devclass = iv_package korrnum = iv_request",
        "        use_korrnum_immediatedly = 'X'",
        "        master_language = sy-langu suppress_dialog = 'X'",
        "      IMPORTING korrnum = lv_recorded_request",
        "      EXCEPTIONS cancelled = 1 permission_failure = 2",
        "        unknown_objectclass = 3 OTHERS = 4.",
        "    IF sy-subrc <> 0.",
        "      ROLLBACK WORK.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_RECORD_FAILED'.",
        "      ev_message = 'Failed to record table on transport'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    REFRESH: lt_object_range, lt_tabname_range,",
        "      lt_indname_range, lt_tgorder_range, lt_fct_range,",
        "      lt_execmode_range, lt_severity_range, lt_gdate_range,",
        "      lt_guser_range.",
        "    LOOP AT lt_expected_tbatg INTO ls_expected_tbatg.",
        "      CLEAR ls_range.",
        "      ls_range-sign = 'I'. ls_range-option = 'EQ'.",
        "      ls_range-low = ls_expected_tbatg-object.",
        "      APPEND ls_range TO lt_object_range.",
        "      ls_range-low = ls_expected_tbatg-tabname.",
        "      APPEND ls_range TO lt_tabname_range.",
        "      ls_range-low = ls_expected_tbatg-indname.",
        "      APPEND ls_range TO lt_indname_range.",
        "      ls_range-low = ls_expected_tbatg-tgorder.",
        "      APPEND ls_range TO lt_tgorder_range.",
        "      ls_range-low = ls_expected_tbatg-fct.",
        "      APPEND ls_range TO lt_fct_range.",
        "      ls_range-low = ls_expected_tbatg-execmode.",
        "      APPEND ls_range TO lt_execmode_range.",
        "      ls_range-low = ls_expected_tbatg-severity.",
        "      APPEND ls_range TO lt_severity_range.",
        "      ls_range-low = ls_expected_tbatg-gdate.",
        "      APPEND ls_range TO lt_gdate_range.",
        "      ls_range-low = ls_expected_tbatg-guser.",
        "      APPEND ls_range TO lt_guser_range.",
        "    ENDLOOP.",
        "    SORT lt_object_range BY low.",
        "    SORT lt_tabname_range BY low.",
        "    SORT lt_indname_range BY low.",
        "    SORT lt_tgorder_range BY low.",
        "    SORT lt_fct_range BY low.",
        "    SORT lt_execmode_range BY low.",
        "    SORT lt_severity_range BY low.",
        "    SORT lt_gdate_range BY low.",
        "    SORT lt_guser_range BY low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_object_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_tabname_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_indname_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_tgorder_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_fct_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_execmode_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_severity_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_gdate_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_guser_range",
        "      COMPARING low.",
        "    CALL FUNCTION 'DD_DB_CONVERTER'",
        "      EXPORTING parallel = ' ' asynchron = ' '",
        "        log_display = ' ' file_log = ' ' db_log = 'X'",
        "        pre_done = ' '",
        "      TABLES object = lt_object_range",
        "        tabname = lt_tabname_range indname = lt_indname_range",
        "        tgorder = lt_tgorder_range fct = lt_fct_range",
        "        execmode = lt_execmode_range severity = lt_severity_range",
        "        gdate = lt_gdate_range guser = lt_guser_range.",
        "    REFRESH lt_current_tbatg.",
        "    SELECT * FROM tbatg INTO TABLE lt_current_tbatg",
        "      WHERE object = 'TABL' AND tabname = iv_object_name.",
        "    IF lt_current_tbatg[] IS NOT INITIAL.",
        "      ev_status = 'E'. ev_code = 'CONVERSION_RECOVERY_PENDING'.",
        "      ev_message = 'Native conversion worklist remains'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CLEAR lv_active_state.",
        "    CALL FUNCTION 'DDIF_STATE_GET'",
        "      EXPORTING type = 'TABL' name = lv_ddic_name state = 'A'",
        "      IMPORTING gotstate = lv_active_state",
        "      EXCEPTIONS OTHERS = 1.",
        "    IF sy-subrc <> 0 OR lv_active_state <> 'A'.",
        "      ev_status = 'E'. ev_code = 'CONVERSION_VERIFY_FAILED'.",
        "      ev_message = 'Active table unavailable after conversion'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CALL FUNCTION 'DDIF_TABL_GET'",
        "      EXPORTING name = lv_ddic_name state = 'A'",
        "        langu = sy-langu",
        "      IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "        dd09l_wa = ls_dd09v",
        "      TABLES dd03p_tab = lt_dd03p",
        "      EXCEPTIONS OTHERS = 1.",
        "    IF sy-subrc <> 0 OR lv_gotstate <> 'A'.",
        "      ev_status = 'E'. ev_code = 'CONVERSION_VERIFY_FAILED'.",
        "      ev_message = 'Active table read failed after conversion'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CONCATENATE ls_dd02v-as4date ls_dd02v-as4time",
        "      INTO lv_current_version.",
        "    REFRESH it_source.",
        "    add_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "    add_payload 'M' '1' 'VERSION' lv_current_version.",
        "    add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "    ev_status = 'S'. ev_code = 'DDIC_CONVERSION_RECOVERED'.",
        "    ev_message = 'Native table conversion completed and verified'.",
        "    ev_version = '1.7'. RETURN.",
        "  ENDIF.",
        "  CLEAR: lv_gotstate, lv_current_version, lv_existing.",
        "  CASE lv_object_type.",
        "    WHEN 'DOMA'.",
        "      CALL FUNCTION 'DDIF_DOMA_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd01v_wa = ls_current_dd01v",
        "        TABLES dd07v_tab = lt_current_dd07v",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'DTEL'.",
        "      CALL FUNCTION 'DDIF_DTEL_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd04v_wa = ls_current_dd04v",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'STRU'.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd02v_wa = ls_current_dd02v",
        "          dd09l_wa = ls_current_dd09v",
        "        TABLES dd03p_tab = lt_current_dd03p",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'TABL'.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd02v_wa = ls_current_dd02v",
        "          dd09l_wa = ls_current_dd09v",
        "        TABLES dd03p_tab = lt_current_dd03p",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'TTYP'.",
        "      CALL FUNCTION 'DDIF_TTYP_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd40v_wa = ls_current_dd40v",
        "        TABLES dd42v_tab = lt_current_dd42v",
        "          dd43v_tab = lt_current_dd43v",
        "        EXCEPTIONS OTHERS = 1.",
        "  ENDCASE.",
        "  IF sy-subrc <> 0.",
        "    ev_status = 'E'. ev_code = 'DDIC_READ_FAILED'.",
        "    ev_message = 'DDIC read interface failed'.",
        "    ev_version = '1.2'. RETURN.",
        "  ENDIF.",
        "  IF lv_gotstate IS NOT INITIAL.",
        "    IF lv_gotstate <> 'A'.",
        "      IF lv_write IS INITIAL",
        "         OR iv_expected_version IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_VERSION_EXISTS'.",
        "        ev_message = 'Inactive DDIC version must be resolved'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_active_state.",
        "      CALL FUNCTION 'DDIF_STATE_GET'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          state = 'A'",
        "        IMPORTING gotstate = lv_active_state",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0 OR lv_active_state IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_VERSION_EXISTS'.",
        "        ev_message = 'Active object has inactive changes'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_deleted. REFRESH lt_object_refs.",
        "      CALL FUNCTION 'DDIF_OBJECT_DELETE'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          authority_check = 'X'",
        "        IMPORTING deleted = lv_deleted",
        "        TABLES objects_with_references = lt_object_refs",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0 OR lv_deleted IS INITIAL",
        "         OR lt_object_refs[] IS NOT INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_RESET_FAILED'.",
        "        ev_message = 'Failed to reset inactive new object'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR lv_gotstate.",
        "    ELSE.",
        "      lv_existing = 'X'.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF lv_existing = 'X'.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        CONCATENATE ls_current_dd01v-as4date",
        "          ls_current_dd01v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'DTEL'.",
        "        CONCATENATE ls_current_dd04v-as4date",
        "          ls_current_dd04v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'STRU'.",
        "        CONCATENATE ls_current_dd02v-as4date",
        "          ls_current_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TABL'.",
        "        CONCATENATE ls_current_dd02v-as4date",
        "          ls_current_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TTYP'.",
        "        SELECT SINGLE as4date as4time FROM dd40l",
        "          INTO (lv_as4date, lv_as4time)",
        "          WHERE typename = iv_object_name",
        "            AND as4local = 'A'.",
        "        CONCATENATE lv_as4date lv_as4time",
        "          INTO lv_current_version.",
        "    ENDCASE.",
        "  ENDIF.",
        "  IF lv_write IS INITIAL AND lv_existing = 'X'.",
        "    ls_dd01v = ls_current_dd01v.",
        "    lt_dd07v[] = lt_current_dd07v[].",
        "    ls_dd04v = ls_current_dd04v.",
        "    ls_dd02v = ls_current_dd02v.",
        "    ls_dd09v = ls_current_dd09v.",
        "    lt_dd03p[] = lt_current_dd03p[].",
        "    ls_dd40v = ls_current_dd40v.",
        "    lt_dd42v[] = lt_current_dd42v[].",
        "    lt_dd43v[] = lt_current_dd43v[].",
        "  ENDIF.",
        "  IF lv_write IS INITIAL AND lv_existing IS INITIAL.",
        "    ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "    ev_message = 'DDIC object does not exist'.",
        "    ev_version = '1.2'. RETURN.",
        "  ENDIF.",
        "  IF lv_object_type = 'TABL' AND lv_existing = 'X'",
        "     AND ls_current_dd02v-tabclass <> 'TRANSP'.",
        "    ev_status = 'E'. ev_code = 'OBJECT_TYPE_MISMATCH'.",
        "    ev_message = 'Dictionary object is not a transparent table'.",
        "    ev_version = '1.3'. RETURN.",
        "  ENDIF.",
        "  IF lv_object_type = 'STRU' AND lv_existing = 'X'",
        "     AND ls_current_dd02v-tabclass <> 'INTTAB'.",
        "    ev_status = 'E'. ev_code = 'OBJECT_TYPE_MISMATCH'.",
        "    ev_message = 'Dictionary object is not a structure'.",
        "    ev_version = '1.4'. RETURN.",
        "  ENDIF.",
        "  IF lv_write = 'X'.",
        "    IF lv_object_type = 'TABL' AND lv_existing = 'X'",
        "       AND lv_append IS INITIAL AND lv_patch IS INITIAL",
        "       AND lv_settings IS INITIAL AND lv_delete IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'DDIC_OBJECT_EXISTS'.",
        "      ev_message = 'Existing transparent tables cannot be replaced'.",
        "      ev_version = '1.3'. RETURN.",
        "    ENDIF.",
        "    IF lv_existing = 'X' AND iv_expected_version IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'EXPECTED_VERSION_REQUIRED'.",
        "      ev_message = 'Existing object requires version token'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_existing = 'X'",
        "       AND iv_expected_version <> lv_current_version.",
        "      ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "      ev_message = 'DDIC object changed since it was read'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_existing IS INITIAL",
        "       AND iv_expected_version IS NOT INITIAL.",
        "      ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "      ev_message = 'Expected object version no longer exists'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_settings = 'X'.",
        "      IF lv_existing IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Transparent table does not exist'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      ls_dd02v = ls_current_dd02v.",
        "      ls_dd09v = ls_current_dd09v.",
        "      lt_dd03p[] = lt_current_dd03p[].",
        "      ls_dd09v-tabart = ls_requested_dd09v-tabart.",
        "      ls_dd09v-tabkat = ls_requested_dd09v-tabkat.",
        "      ls_dd09v-bufallow = ls_requested_dd09v-bufallow.",
        "      ls_dd09v-pufferung = ls_requested_dd09v-pufferung.",
        "      ls_dd09v-schfeldanz = ls_requested_dd09v-schfeldanz.",
        "      ls_dd09v-protokoll = ls_requested_dd09v-protokoll.",
        "      IF ls_dd09v-bufallow = 'N'",
        "         AND ( ls_dd09v-pufferung IS NOT INITIAL",
        "           OR ls_dd09v-schfeldanz IS NOT INITIAL ).",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Disabled buffering has no mode or key count'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-bufallow = 'A'",
        "         AND ( ls_dd09v-pufferung IS NOT INITIAL",
        "           OR ls_dd09v-schfeldanz IS NOT INITIAL ).",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Inactive buffering has no mode or key count'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-bufallow = 'X'",
        "         AND ls_dd09v-pufferung <> 'P'",
        "         AND ls_dd09v-pufferung <> 'G'",
        "         AND ls_dd09v-pufferung <> 'X'.",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Enabled buffering requires a valid mode'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-pufferung <> 'G'",
        "         AND ls_dd09v-schfeldanz IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Generic key count requires generic buffering'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-pufferung = 'G'.",
        "        CLEAR lv_field_count.",
        "        LOOP AT lt_current_dd03p INTO ls_compare_dd03p",
        "          WHERE keyflag = 'X'.",
        "          IF ls_compare_dd03p-fieldname NP '.INCLU*'.",
        "            lv_field_count = lv_field_count + 1.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF ls_dd09v-schfeldanz IS INITIAL",
        "           OR ls_dd09v-schfeldanz > lv_field_count.",
        "          ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "          ev_message = 'Generic key count exceeds key fields'.",
        "          ev_version = '1.7'. RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      IF ls_dd09v-tabart = ls_current_dd09v-tabart",
        "         AND ls_dd09v-tabkat = ls_current_dd09v-tabkat",
        "         AND ls_dd09v-bufallow = ls_current_dd09v-bufallow",
        "         AND ls_dd09v-pufferung = ls_current_dd09v-pufferung",
        "         AND ls_dd09v-schfeldanz = ls_current_dd09v-schfeldanz",
        "         AND ls_dd09v-protokoll = ls_current_dd09v-protokoll.",
        "        ev_status = 'E'. ev_code = 'NO_CHANGES'.",
        "        ev_message = 'Technical settings equal active definition'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDIF.",
        "    IF lv_append = 'X'.",
        "      IF lv_existing IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Transparent table does not exist'.",
        "        ev_version = '1.5'. RETURN.",
        "      ENDIF.",
        "      IF lt_dd03p[] IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "        ev_message = 'Fields to append are required'.",
        "        ev_version = '1.5'. RETURN.",
        "      ENDIF.",
        "      lt_append_dd03p[] = lt_dd03p[].",
        "      lt_dd03p[] = lt_current_dd03p[].",
        "      CLEAR lv_index.",
        "      LOOP AT lt_dd03p INTO ls_compare_dd03p.",
        "        IF ls_compare_dd03p-fieldname CP '.INCLU--AP*'.",
        "          lv_index = sy-tabix. EXIT.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      LOOP AT lt_append_dd03p INTO ls_dd03p.",
        "        IF ls_dd03p-fieldname IS INITIAL",
        "           OR ls_dd03p-rollname IS INITIAL",
        "           OR ls_dd03p-fieldname = 'MANDT'",
        "           OR ls_dd03p-keyflag IS NOT INITIAL",
        "           OR ls_dd03p-notnull IS NOT INITIAL.",
        "          ev_status = 'E'. ev_code = 'UNSAFE_TABLE_CHANGE'.",
        "          ev_message = 'Only nullable non-key fields may append'.",
        "          ev_version = '1.5'. RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_dd03p TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_dd03p-fieldname.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'. ev_code = 'FIELD_ALREADY_EXISTS'.",
        "          ev_message = 'Transparent table field already exists'.",
        "          ev_version = '1.5'. RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_reference_dd04v, lv_reference_state.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = ls_dd03p-rollname state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_reference_state",
        "            dd04v_wa = ls_reference_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_reference_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active data element reference not found'.",
        "          ev_version = '1.5'. RETURN.",
        "        ENDIF.",
        "        ls_dd03p-tabname = iv_object_name.",
        "        ls_dd03p-ddlanguage = sy-langu.",
        "        ls_dd03p-comptype = 'E'.",
        "        IF lv_index > 0.",
        "          INSERT ls_dd03p INTO lt_dd03p INDEX lv_index.",
        "          lv_index = lv_index + 1.",
        "        ELSE.",
        "          APPEND ls_dd03p TO lt_dd03p.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      LOOP AT lt_dd03p ASSIGNING <ls_field>.",
        "        <ls_field>-position = sy-tabix.",
        "      ENDLOOP.",
        "      ls_dd02v = ls_current_dd02v.",
        "      ls_dd09v = ls_current_dd09v.",
        "    ENDIF.",
        "    IF lv_patch = 'X'.",
        "      IF lv_existing IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Transparent table does not exist'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      IF lt_dd03p[] IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "        ev_message = 'Final table fields are required'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_current_has_mandt, lv_final_has_mandt,",
        "        lv_changed, lv_key_closed, lv_current_complex_count,",
        "        lv_final_complex_count.",
        "      READ TABLE lt_current_dd03p TRANSPORTING NO FIELDS",
        "        WITH KEY fieldname = 'MANDT'.",
        "      IF sy-subrc = 0. lv_current_has_mandt = 'X'. ENDIF.",
        "      LOOP AT lt_current_dd03p INTO ls_compare_dd03p.",
        "        IF ls_compare_dd03p-fieldname CP '.INCLU*'",
        "           OR ( ls_compare_dd03p-adminfield IS NOT INITIAL",
        "             AND ls_compare_dd03p-adminfield <> '0' )",
        "           OR ( ls_compare_dd03p-comptype IS NOT INITIAL",
        "             AND ls_compare_dd03p-comptype <> 'E' ).",
        "          lv_current_complex_count = lv_current_complex_count + 1.",
        "          READ TABLE lt_dd03p TRANSPORTING NO FIELDS",
        "            WITH KEY fieldname = ls_compare_dd03p-fieldname",
        "              rollname = ls_compare_dd03p-rollname",
        "              precfield = ls_compare_dd03p-precfield",
        "              comptype = ls_compare_dd03p-comptype",
        "              adminfield = ls_compare_dd03p-adminfield",
        "              groupname = ls_compare_dd03p-groupname",
        "              exclass = ls_compare_dd03p-exclass",
        "              keyflag = ls_compare_dd03p-keyflag",
        "              notnull = ls_compare_dd03p-notnull.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'COMPLEX_COMPONENT_CHANGE_FORBIDDEN'.",
        "            ev_message = 'Include and Append components are immutable'.",
        "            ev_version = '1.7'. RETURN.",
        "          ENDIF.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      REFRESH lt_checked_dd03p.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        lv_index = sy-tabix.",
        "        IF ls_dd03p-fieldname CP '.INCLU*'",
        "           OR ( ls_dd03p-adminfield IS NOT INITIAL",
        "             AND ls_dd03p-adminfield <> '0' )",
        "           OR ( ls_dd03p-comptype IS NOT INITIAL",
        "             AND ls_dd03p-comptype <> 'E' ).",
        "          lv_final_complex_count = lv_final_complex_count + 1.",
        "          READ TABLE lt_current_dd03p TRANSPORTING NO FIELDS",
        "            WITH KEY fieldname = ls_dd03p-fieldname",
        "              rollname = ls_dd03p-rollname",
        "              precfield = ls_dd03p-precfield",
        "              comptype = ls_dd03p-comptype",
        "              adminfield = ls_dd03p-adminfield",
        "              groupname = ls_dd03p-groupname",
        "              exclass = ls_dd03p-exclass",
        "              keyflag = ls_dd03p-keyflag",
        "              notnull = ls_dd03p-notnull.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'COMPLEX_COMPONENT_CHANGE_FORBIDDEN'.",
        "            ev_message = 'Include and Append components are immutable'.",
        "            ev_version = '1.7'. RETURN.",
        "          ENDIF.",
        "          READ TABLE lt_current_dd03p INTO ls_compare_dd03p",
        "            INDEX lv_index.",
        "          IF sy-subrc <> 0",
        "             OR ls_compare_dd03p-fieldname <> ls_dd03p-fieldname",
        "             OR ls_compare_dd03p-precfield <> ls_dd03p-precfield",
        "             OR ls_compare_dd03p-adminfield <> ls_dd03p-adminfield.",
        "            lv_changed = 'X'.",
        "          ENDIF.",
        "          IF ls_dd03p-fieldname NP '.INCLU*'.",
        "            READ TABLE lt_checked_dd03p TRANSPORTING NO FIELDS",
        "              WITH KEY fieldname = ls_dd03p-fieldname.",
        "            IF sy-subrc = 0.",
        "              ev_status = 'E'. ev_code = 'DUPLICATE_FIELD'.",
        "              ev_message = 'Duplicate final field name'.",
        "              ev_version = '1.7'. RETURN.",
        "            ENDIF.",
        "            APPEND ls_dd03p TO lt_checked_dd03p.",
        "            IF ls_dd03p-keyflag IS INITIAL.",
        "              lv_key_closed = 'X'.",
        "            ELSEIF lv_key_closed = 'X'.",
        "              ev_status = 'E'. ev_code = 'KEY_ORDER_INVALID'.",
        "              ev_message = 'Key fields must be first'.",
        "              ev_version = '1.7'. RETURN.",
        "            ENDIF.",
        "          ENDIF.",
        "          ls_dd03p-tabname = iv_object_name.",
        "          ls_dd03p-ddlanguage = sy-langu.",
        "          ls_dd03p-position = lv_index.",
        "          MODIFY lt_dd03p FROM ls_dd03p INDEX lv_index.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF ls_dd03p-fieldname IS INITIAL",
        "           OR ls_dd03p-rollname IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELD_VALUE_INVALID'.",
        "          ev_message = 'Field and data element are required'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_checked_dd03p TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_dd03p-fieldname.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'. ev_code = 'DUPLICATE_FIELD'.",
        "          ev_message = 'Duplicate final field name'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd03p-keyflag IS INITIAL.",
        "          lv_key_closed = 'X'.",
        "        ELSEIF lv_key_closed = 'X'.",
        "          ev_status = 'E'. ev_code = 'KEY_ORDER_INVALID'.",
        "          ev_message = 'Key fields must be first'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd03p-keyflag = 'X'",
        "           AND ls_dd03p-notnull IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'KEY_NULLABLE'.",
        "          ev_message = 'Key fields must be not null'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd03p-fieldname = 'MANDT'.",
        "          lv_final_has_mandt = 'X'.",
        "          IF lv_index <> 1 OR ls_dd03p-keyflag <> 'X'",
        "             OR ls_dd03p-notnull <> 'X'",
        "             OR ls_dd03p-rollname <> 'MANDT'.",
        "            ev_status = 'E'. ev_code = 'MANDT_CHANGE_FORBIDDEN'.",
        "            ev_message = 'MANDT definition cannot be changed'.",
        "            ev_version = '1.6'. RETURN.",
        "          ENDIF.",
        "        ENDIF.",
        "        CLEAR: ls_reference_dd04v, lv_reference_state.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = ls_dd03p-rollname state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_reference_state",
        "            dd04v_wa = ls_reference_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_reference_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active data element reference not found'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_current_dd03p INTO ls_compare_dd03p",
        "          INDEX lv_index.",
        "        IF sy-subrc <> 0",
        "           OR ls_compare_dd03p-fieldname <> ls_dd03p-fieldname",
        "           OR ls_compare_dd03p-rollname <> ls_dd03p-rollname",
        "           OR ls_compare_dd03p-keyflag <> ls_dd03p-keyflag",
        "           OR ls_compare_dd03p-notnull <> ls_dd03p-notnull.",
        "          lv_changed = 'X'.",
        "        ENDIF.",
        "        ls_dd03p-tabname = iv_object_name.",
        "        ls_dd03p-ddlanguage = sy-langu.",
        "        ls_dd03p-position = lv_index.",
        "        ls_dd03p-comptype = 'E'.",
        "        MODIFY lt_dd03p FROM ls_dd03p INDEX lv_index.",
        "        APPEND ls_dd03p TO lt_checked_dd03p.",
        "      ENDLOOP.",
        "      IF lv_current_complex_count <> lv_final_complex_count.",
        "        ev_status = 'E'.",
        "        ev_code = 'COMPLEX_COMPONENT_CHANGE_FORBIDDEN'.",
        "        ev_message = 'Include and Append components are immutable'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF lv_current_has_mandt <> lv_final_has_mandt.",
        "        ev_status = 'E'. ev_code = 'MANDT_CHANGE_FORBIDDEN'.",
        "        ev_message = 'MANDT definition cannot be changed'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      DESCRIBE TABLE lt_current_dd03p LINES lv_current_field_count.",
        "      DESCRIBE TABLE lt_dd03p LINES lv_field_count.",
        "      IF lv_current_field_count <> lv_field_count.",
        "        lv_changed = 'X'.",
        "      ENDIF.",
        "      IF lv_changed IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'NO_CHANGES'.",
        "        ev_message = 'Final fields equal active definition'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      ls_dd02v = ls_current_dd02v.",
        "      ls_dd09v = ls_current_dd09v.",
        "    ENDIF.",
        "    lv_mode = 'M'.",
        "    SELECT SINGLE * FROM tadir INTO ls_tadir",
        "      WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "        AND obj_name = iv_object_name.",
        "    IF sy-subrc = 0 AND ls_tadir-devclass <> iv_package.",
        "      ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "      ev_message = 'Existing object belongs to another package'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF sy-subrc <> 0.",
        "      lv_mode = 'I'.",
        "    ENDIF.",
        "    IF lv_delete = 'X'. lv_mode = 'D'. ENDIF.",
        "    ls_corr_object-objtype = lv_object_type.",
        "    ls_corr_object-objname = iv_object_name.",
        "    CALL FUNCTION 'RS_CORR_INSERT'",
        "      EXPORTING object = ls_corr_object",
        "        object_class = 'DICT' mode = lv_mode",
        "        devclass = iv_package korrnum = iv_request",
        "        use_korrnum_immediatedly = 'X'",
        "        master_language = sy-langu suppress_dialog = 'X'",
        "      IMPORTING korrnum = lv_recorded_request",
        "      EXCEPTIONS cancelled = 1 permission_failure = 2",
        "        unknown_objectclass = 3 OTHERS = 4.",
        "    IF sy-subrc <> 0.",
        "      ROLLBACK WORK.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_RECORD_FAILED'.",
        "      MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "        WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "        INTO ev_message.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_delete = 'X'.",
        "      CLEAR lv_deleted. REFRESH lt_object_refs.",
        "      CALL FUNCTION 'DDIF_OBJECT_DELETE'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          authority_check = 'X'",
        "        IMPORTING deleted = lv_deleted",
        "        TABLES objects_with_references = lt_object_refs",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF lt_object_refs[] IS NOT INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'DEPENDENCIES_EXIST'.",
        "        ev_message = 'DDIC object is still referenced'.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        "      IF sy-subrc <> 0 OR lv_deleted IS INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'DDIC_DELETE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR lv_active_state.",
        "      CALL FUNCTION 'DDIF_STATE_GET'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          state = 'A'",
        "        IMPORTING gotstate = lv_active_state",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc = 0 AND lv_active_state IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'DDIC object still exists after delete'.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_dd01v, ls_dd04v, ls_dd02v, ls_dd09v,",
        "        ls_dd40v.",
        "      REFRESH: lt_dd07v, lt_dd03p, lt_dd42v, lt_dd43v.",
        "      ev_status = 'S'. ev_code = 'DDIC_OBJECT_DELETED'.",
        "      ev_message = 'DDIC object deleted after dependency check'.",
        "      ev_version = '1.4'. RETURN.",
        "    ENDIF.",
        "    CLEAR lv_rc.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        ls_dd01v-domname = iv_object_name.",
        "        ls_dd01v-ddlanguage = sy-langu.",
        "        ls_dd01v-ddtext = iv_description.",
        "        IF ls_dd01v-outputlen IS INITIAL.",
        "          ls_dd01v-outputlen = ls_dd01v-leng.",
        "        ENDIF.",
        "        LOOP AT lt_dd07v ASSIGNING <ls_value>.",
        "          <ls_value>-domname = iv_object_name.",
        "          <ls_value>-ddlanguage = sy-langu.",
        "          <ls_value>-valpos = sy-tabix.",
        "        ENDLOOP.",
        "        IF lt_dd07v[] IS INITIAL.",
        "          CLEAR ls_dd01v-valexi.",
        "        ELSE.",
        "          ls_dd01v-valexi = 'X'.",
        "        ENDIF.",
        "        CALL FUNCTION 'DDIF_DOMA_PUT'",
        "          EXPORTING name = lv_ddic_name dd01v_wa = ls_dd01v",
        "          TABLES dd07v_tab = lt_dd07v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_DOMA_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'DTEL'.",
        "        ls_dd04v-rollname = iv_object_name.",
        "        ls_dd04v-ddlanguage = sy-langu.",
        "        ls_dd04v-ddtext = iv_description.",
        "        CLEAR: ls_domain_dd01v, lt_domain_dd07v.",
        "        CALL FUNCTION 'DDIF_DOMA_GET'",
        "          EXPORTING name = ls_dd04v-domname state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_active_state",
        "            dd01v_wa = ls_domain_dd01v",
        "          TABLES dd07v_tab = lt_domain_dd07v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_active_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active domain reference not found'.",
        "          ev_version = '1.2'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd04v-reptext IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-reptext ).",
        "          ls_dd04v-headlen = lv_text_length.",
        "          IF ls_domain_dd01v-outputlen > ls_dd04v-headlen.",
        "            IF ls_domain_dd01v-outputlen > 55.",
        "              ls_dd04v-headlen = 55.",
        "            ELSE.",
        "              ls_dd04v-headlen = ls_domain_dd01v-outputlen.",
        "            ENDIF.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF ls_dd04v-scrtext_s IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-scrtext_s ).",
        "          IF lv_text_length < 10. lv_text_length = 10. ENDIF.",
        "          ls_dd04v-scrlen1 = lv_text_length.",
        "        ENDIF.",
        "        IF ls_dd04v-scrtext_m IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-scrtext_m ).",
        "          IF lv_text_length < 15. lv_text_length = 15. ENDIF.",
        "          ls_dd04v-scrlen2 = lv_text_length.",
        "        ENDIF.",
        "        IF ls_dd04v-scrtext_l IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-scrtext_l ).",
        "          IF lv_text_length < 20. lv_text_length = 20. ENDIF.",
        "          ls_dd04v-scrlen3 = lv_text_length.",
        "        ENDIF.",
        "        CALL FUNCTION 'DDIF_DTEL_PUT'",
        "          EXPORTING name = lv_ddic_name dd04v_wa = ls_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_DTEL_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'STRU'.",
        "        IF lt_dd03p[] IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "          ev_message = 'Structure fields are required'.",
        "          ev_version = '1.2'. RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_dd02v, ls_dd09v.",
        "        ls_dd02v-tabname = iv_object_name.",
        "        ls_dd02v-ddlanguage = sy-langu.",
        "        ls_dd02v-tabclass = 'INTTAB'.",
        "        ls_dd02v-masterlang = sy-langu.",
        "        ls_dd02v-ddtext = iv_description.",
        "        LOOP AT lt_dd03p ASSIGNING <ls_field>.",
        "          <ls_field>-tabname = iv_object_name.",
        "          <ls_field>-ddlanguage = sy-langu.",
        "          <ls_field>-position = sy-tabix.",
        "          <ls_field>-comptype = 'E'.",
        "        ENDLOOP.",
        "        CALL FUNCTION 'DDIF_TABL_PUT'",
        "          EXPORTING name = lv_ddic_name dd02v_wa = ls_dd02v",
        "            dd09l_wa = ls_dd09v",
        "          TABLES dd03p_tab = lt_dd03p",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_TABL_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "              excommit = 'X'",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'TABL'.",
        "        IF lt_dd03p[] IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "          ev_message = 'Transparent table fields are required'.",
        "          ev_version = '1.3'. RETURN.",
        "        ENDIF.",
        "        ls_dd02v-tabname = iv_object_name.",
        "        ls_dd02v-ddlanguage = sy-langu.",
        "        ls_dd02v-tabclass = 'TRANSP'.",
        "        ls_dd02v-masterlang = sy-langu.",
        "        ls_dd02v-ddtext = iv_description.",
        "        ls_dd09v-tabname = iv_object_name.",
        "        LOOP AT lt_dd03p ASSIGNING <ls_field>.",
        "          IF lv_append IS INITIAL AND lv_patch IS INITIAL",
        "             AND lv_settings IS INITIAL.",
        "            <ls_field>-tabname = iv_object_name.",
        "            <ls_field>-ddlanguage = sy-langu.",
        "            <ls_field>-position = sy-tabix.",
        "            <ls_field>-comptype = 'E'.",
        "            <ls_field>-notnull = 'X'.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF lv_settings = 'X'.",
        "          CALL FUNCTION 'DDIF_TABT_PUT'",
        "            EXPORTING name = lv_ddic_name dd09l_wa = ls_dd09v",
        "            EXCEPTIONS OTHERS = 1.",
        "        ELSE.",
        "          CALL FUNCTION 'DDIF_TABL_PUT'",
        "            EXPORTING name = lv_ddic_name dd02v_wa = ls_dd02v",
        "              dd09l_wa = ls_dd09v",
        "            TABLES dd03p_tab = lt_dd03p",
        "            EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "        IF sy-subrc = 0.",
        "          REFRESH lt_act_res.",
        "          CALL FUNCTION 'DD_TABL_ACT'",
        "            EXPORTING tabname = iv_object_name auth_chk = 'X'",
        "              excommit = 'X'",
        "            IMPORTING act_result = lv_rc",
        "            TABLES act_res_tab = lt_act_res",
        "            EXCEPTIONS actok_failure = 1 dbchange_failure = 2",
        "              lockact_failure = 3 ntab_gen_failure = 4",
        "              put_failure = 5 read_failure = 6",
        "              unlockact_failure = 7 access_failure = 8",
        "              OTHERS = 9.",
        "          READ TABLE lt_act_res INTO ls_act_res",
        "            WITH KEY tabname = iv_object_name.",
        "        ENDIF.",
        "      WHEN 'TTYP'.",
        "        CLEAR: lt_dd42v, lt_dd43v.",
        "        ls_dd40v-typename = iv_object_name.",
        "        ls_dd40v-ddlanguage = sy-langu.",
        "        ls_dd40v-rowkind = 'S'.",
        "        ls_dd40v-datatype = 'STRU'.",
        "        ls_dd40v-accessmode = 'T'.",
        "        ls_dd40v-keydef = 'D'.",
        "        ls_dd40v-keykind = 'N'.",
        "        ls_dd40v-ddtext = iv_description.",
        "        CALL FUNCTION 'DDIF_TTYP_PUT'",
        "          EXPORTING name = lv_ddic_name dd40v_wa = ls_dd40v",
        "          TABLES dd42v_tab = lt_dd42v dd43v_tab = lt_dd43v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_TTYP_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "    ENDCASE.",
        "    lv_activation_subrc = sy-subrc.",
        "    IF lv_object_type = 'TABL'",
        "       AND ( lv_activation_subrc <> 0 OR lv_rc <> 0 ).",
        "      CLEAR lv_append_count.",
        "      SELECT COUNT(*) FROM tbatg INTO lv_append_count",
        "        WHERE object = 'TABL' AND tabname = iv_object_name.",
        "      IF lv_append_count > 0.",
        "        REFRESH it_source.",
        "        add_payload 'M' '1' 'PACKAGE' iv_package.",
        "        add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "        add_payload 'M' '1' 'CONVERSION_ACTION'",
        "          ls_act_res-action.",
        "        add_payload 'M' '1' 'CONVERSION_MODE'",
        "          ls_act_res-modeflag.",
        "        add_payload 'M' '1' 'CONVERSION_DATA_LOSS'",
        "          ls_act_res-dataloss_d.",
        "        ev_status = 'E'. ev_code = 'DDIC_CONVERSION_PENDING'.",
        "        ev_message = 'Native table conversion requires recovery'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDIF.",
        "    IF lv_activation_subrc = 0 AND lv_rc <> 0.",
        "      CLEAR lv_active_state.",
        "      CALL FUNCTION 'DDIF_STATE_GET'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          state = 'A'",
        "        IMPORTING gotstate = lv_active_state",
        "        EXCEPTIONS OTHERS = 1.",
        "    ENDIF.",
        "    IF lv_activation_subrc <> 0 OR lv_active_state IS INITIAL",
        "       AND lv_rc <> 0.",
        "      ROLLBACK WORK.",
        "      ev_status = 'E'. ev_code = 'DDIC_SAVE_FAILED'.",
        "      MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "        WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "        INTO ev_message.",
        "      IF ev_message IS INITIAL.",
        "        ev_message = 'DDIC put or activation failed'.",
        "      ENDIF.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    COMMIT WORK AND WAIT.",
        "    CLEAR: lv_gotstate, lv_current_version.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        REFRESH lt_dd07v.",
        "        CALL FUNCTION 'DDIF_DOMA_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd01v_wa = ls_dd01v",
        "          TABLES dd07v_tab = lt_dd07v",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd01v-as4date ls_dd01v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'DTEL'.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd04v_wa = ls_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd04v-as4date ls_dd04v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'STRU'.",
        "        REFRESH lt_dd03p.",
        "        CALL FUNCTION 'DDIF_TABL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "            dd09l_wa = ls_dd09v",
        "          TABLES dd03p_tab = lt_dd03p",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd02v-as4date ls_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TABL'.",
        "        REFRESH lt_dd03p.",
        "        CALL FUNCTION 'DDIF_TABL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "            dd09l_wa = ls_dd09v",
        "          TABLES dd03p_tab = lt_dd03p",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd02v-as4date ls_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TTYP'.",
        "        CALL FUNCTION 'DDIF_TTYP_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd40v_wa = ls_dd40v",
        "          TABLES dd42v_tab = lt_dd42v dd43v_tab = lt_dd43v",
        "          EXCEPTIONS OTHERS = 1.",
        "        SELECT SINGLE as4date as4time FROM dd40l",
        "          INTO (lv_as4date, lv_as4time)",
        "          WHERE typename = iv_object_name",
        "            AND as4local = 'A'.",
        "        CONCATENATE lv_as4date lv_as4time",
        "          INTO lv_current_version.",
        "    ENDCASE.",
        "    IF sy-subrc <> 0 OR lv_gotstate <> 'A'.",
        "      ev_status = 'E'. ev_code = 'VERIFY_FAILED'.",
        "      ev_message = 'Activated DDIC object could not be read'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  SELECT SINGLE * FROM tadir INTO ls_tadir",
        "    WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "      AND obj_name = iv_object_name.",
        "  REFRESH it_source.",
        "  add_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "  add_payload 'M' '1' 'VERSION' lv_current_version.",
        "  add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "  IF ls_act_res-action IS NOT INITIAL.",
        "    add_payload 'M' '1' 'CONVERSION_ACTION' ls_act_res-action.",
        "    add_payload 'M' '1' 'CONVERSION_MODE' ls_act_res-modeflag.",
        "    add_payload 'M' '1' 'CONVERSION_DATA_LOSS'",
        "      ls_act_res-dataloss_d.",
        "  ENDIF.",
        "  CASE lv_object_type.",
        "    WHEN 'DOMA'.",
        "      add_payload 'H' '1' 'DOMNAME' ls_dd01v-domname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd01v-ddtext.",
        "      add_payload 'H' '1' 'DATATYPE' ls_dd01v-datatype.",
        "      add_payload 'H' '1' 'LENG' ls_dd01v-leng.",
        "      add_payload 'H' '1' 'OUTPUTLEN' ls_dd01v-outputlen.",
        "      add_payload 'H' '1' 'DECIMALS' ls_dd01v-decimals.",
        "      add_payload 'H' '1' 'LOWERCASE' ls_dd01v-lowercase.",
        "      add_payload 'H' '1' 'SIGNFLAG' ls_dd01v-signflag.",
        "      add_payload 'H' '1' 'ENTITYTAB' ls_dd01v-entitytab.",
        "      add_payload 'H' '1' 'CONVEXIT' ls_dd01v-convexit.",
        "      LOOP AT lt_dd07v INTO ls_dd07v.",
        "        lv_index = sy-tabix.",
        "        add_payload 'V' lv_index 'DOMVALUE_L'",
        "          ls_dd07v-domvalue_l.",
        "        add_payload 'V' lv_index 'DOMVALUE_H'",
        "          ls_dd07v-domvalue_h.",
        "        add_payload 'V' lv_index 'DDTEXT' ls_dd07v-ddtext.",
        "      ENDLOOP.",
        "    WHEN 'DTEL'.",
        "      add_payload 'H' '1' 'ROLLNAME' ls_dd04v-rollname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd04v-ddtext.",
        "      add_payload 'H' '1' 'DOMNAME' ls_dd04v-domname.",
        "      add_payload 'H' '1' 'REPTEXT' ls_dd04v-reptext.",
        "      add_payload 'H' '1' 'SCRTEXT_S' ls_dd04v-scrtext_s.",
        "      add_payload 'H' '1' 'SCRTEXT_M' ls_dd04v-scrtext_m.",
        "      add_payload 'H' '1' 'SCRTEXT_L' ls_dd04v-scrtext_l.",
        "    WHEN 'STRU'.",
        "      add_payload 'H' '1' 'TABNAME' ls_dd02v-tabname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd02v-ddtext.",
        "      add_payload 'H' '1' 'TABCLASS' ls_dd02v-tabclass.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        lv_index = sy-tabix.",
        "        add_payload 'F' lv_index 'FIELDNAME'",
        "          ls_dd03p-fieldname.",
        "        add_payload 'F' lv_index 'POSITION'",
        "          ls_dd03p-position.",
        "        add_payload 'F' lv_index 'ROLLNAME'",
        "          ls_dd03p-rollname.",
        "        add_payload 'F' lv_index 'DDTEXT' ls_dd03p-ddtext.",
        "        add_payload 'F' lv_index 'DATATYPE' ls_dd03p-datatype.",
        "        add_payload 'F' lv_index 'LENG' ls_dd03p-leng.",
        "        add_payload 'F' lv_index 'COMPTYPE' ls_dd03p-comptype.",
        "      ENDLOOP.",
        "    WHEN 'TABL'.",
        "      add_payload 'H' '1' 'TABNAME' ls_dd02v-tabname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd02v-ddtext.",
        "      add_payload 'H' '1' 'TABCLASS' ls_dd02v-tabclass.",
        "      add_payload 'H' '1' 'CONTFLAG' ls_dd02v-contflag.",
        "      add_payload 'H' '1' 'MAINFLAG' ls_dd02v-mainflag.",
        "      add_payload 'H' '1' 'TABKAT' ls_dd09v-tabkat.",
        "      add_payload 'H' '1' 'TABART' ls_dd09v-tabart.",
        "      add_payload 'H' '1' 'BUFALLOW' ls_dd09v-bufallow.",
        "      add_payload 'H' '1' 'PUFFERUNG' ls_dd09v-pufferung.",
        "      add_payload 'H' '1' 'SCHFELDANZ' ls_dd09v-schfeldanz.",
        "      add_payload 'H' '1' 'PROTOKOLL' ls_dd09v-protokoll.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        lv_index = sy-tabix.",
        "        add_payload 'F' lv_index 'FIELDNAME'",
        "          ls_dd03p-fieldname.",
        "        add_payload 'F' lv_index 'POSITION'",
        "          ls_dd03p-position.",
        "        add_payload 'F' lv_index 'ROLLNAME'",
        "          ls_dd03p-rollname.",
        "        add_payload 'F' lv_index 'DDTEXT' ls_dd03p-ddtext.",
        "        add_payload 'F' lv_index 'DATATYPE' ls_dd03p-datatype.",
        "        add_payload 'F' lv_index 'LENG' ls_dd03p-leng.",
        "        add_payload 'F' lv_index 'COMPTYPE' ls_dd03p-comptype.",
        "        add_payload 'F' lv_index 'PRECFIELD' ls_dd03p-precfield.",
        "        add_payload 'F' lv_index 'ADMINFIELD'",
        "          ls_dd03p-adminfield.",
        "        add_payload 'F' lv_index 'GROUPNAME' ls_dd03p-groupname.",
        "        add_payload 'F' lv_index 'EXCLASS' ls_dd03p-exclass.",
        "        add_payload 'F' lv_index 'KEYFLAG'",
        "          ls_dd03p-keyflag.",
        "        add_payload 'F' lv_index 'NOTNULL'",
        "          ls_dd03p-notnull.",
        "      ENDLOOP.",
        "    WHEN 'TTYP'.",
        "      add_payload 'H' '1' 'TYPENAME' ls_dd40v-typename.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd40v-ddtext.",
        "      add_payload 'H' '1' 'ROWTYPE' ls_dd40v-rowtype.",
        "      add_payload 'H' '1' 'ROWKIND' ls_dd40v-rowkind.",
        "      add_payload 'H' '1' 'DATATYPE' ls_dd40v-datatype.",
        "      add_payload 'H' '1' 'ACCESSMODE' ls_dd40v-accessmode.",
        "      add_payload 'H' '1' 'KEYDEF' ls_dd40v-keydef.",
        "      add_payload 'H' '1' 'KEYKIND' ls_dd40v-keykind.",
        "  ENDCASE.",
        "  ev_status = 'S'.",
        "  IF lv_write = 'X'.",
        "    ev_code = 'DDIC_OBJECT_SAVED'.",
        "    ev_message = 'DDIC object saved activated and verified'.",
        "  ELSE.",
        "    ev_code = 'DDIC_OBJECT_READ'.",
        "    ev_message = 'DDIC object read successfully'.",
        "  ENDIF.",
        "  ev_version = '1.7'."
    )
}

function New-InstallProgram {
    param(
        [switch]$ReplaceExisting,
        [string]$FunctionName = "Z_ORVANTA_MCP_EXECUTE"
    )

    $existingObjectLines = if ($ReplaceExisting) {
        @(
            "IF sy-subrc = 0.",
            "  CALL FUNCTION 'FUNCTION_DELETE'",
            "    EXPORTING",
            "      funcname = '$FunctionName'",
            "      suppress_success_message = 'X'",
            "    EXCEPTIONS error_message = 1.",
            "  IF sy-subrc <> 0.",
            "    WRITE: / 'DELETE_ERROR', sy-subrc, sy-msgid, sy-msgno.",
            "    ROLLBACK WORK.",
            "    STOP.",
            "  ENDIF.",
            "  COMMIT WORK AND WAIT.",
            "  WRITE / 'DELETED $FunctionName'.",
            "ELSEIF sy-subrc <> 1.",
            "  WRITE: / 'EXISTENCE_CHECK_ERROR', sy-subrc.",
            "  STOP.",
            "ENDIF."
        )
    }
    else {
        @(
            "IF sy-subrc = 0.",
            "  WRITE / 'ALREADY_EXISTS'.",
            "  STOP.",
            "ELSEIF sy-subrc <> 1.",
            "  WRITE: / 'EXISTENCE_CHECK_ERROR', sy-subrc.",
            "  STOP.",
            "ENDIF."
        )
    }

    # CAPABILITIES payload rows (docs/helper-capabilities-protocol.md). $FunctionName
    # is interpolated because this body is shared by Z_ORVANTA_MCP_EXECUTE and
    # Z_ORVANTA_MCP_DYNPRO_API. Package/transport values are escaped here, at
    # generation time; the runtime values (hash, sy-sysid/sy-mandt, sy-datum/
    # sy-uzeit/sy-tzone) cannot contain the payload separators.
    # >>> ORVANTA-CAPABILITIES-SOURCE
    $capabilityHashSlots = @(
        "ORVANTAHASHSLOT1",
        "ORVANTAHASHSLOT2",
        "ORVANTAHASHSLOT3",
        "ORVANTAHASHSLOT4"
    )
    $capabilityPackageValue = ([string]$PackageName).Replace("%", "%25").Replace("|", "%7C")
    $capabilityTransportValue = (
        @([string]$TransportNumber, [string]$TransportTask) | ForEach-Object {
            $_.Replace("%", "%25").Replace("|", "%7C")
        }
    ) -join "|"
    $capabilityBranchLines = @(
        "    WHEN 'CAPABILITIES'.",
        "      CLEAR ls_source.",
        "      ls_source-line = 'HELPER|$FunctionName'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'PROTOCOL|MIN|$helperCapabilityMinVersion'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'PROTOCOL|MAX|$helperCapabilityMaxVersion'.",
        "      APPEND ls_source TO it_source."
    )
    foreach ($capabilityOperation in $helperCapabilityOperations) {
        $capabilityOperationParts = $capabilityOperation -split "\|"
        $capabilityBranchLines += @(
            "      CONCATENATE 'OPERATION|$($capabilityOperationParts[0])' '$($capabilityOperationParts[1])|$($capabilityOperationParts[2])'",
            "        INTO ls_source-line SEPARATED BY '|'.",
            "      APPEND ls_source TO it_source."
        )
    }
    foreach ($capabilityScope in $helperCapabilityScopes) {
        $capabilityBranchLines += @(
            "      ls_source-line = 'SCOPE|$capabilityScope'.",
            "      APPEND ls_source TO it_source."
        )
    }
    $capabilityBranchLines += @(
        "      CLEAR ls_source.",
        "      CONCATENATE 'SOURCE|HASH|' '$($capabilityHashSlots[0])' '$($capabilityHashSlots[1])'",
        "        '$($capabilityHashSlots[2])' '$($capabilityHashSlots[3])' INTO ls_source-line.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'SOURCE|PACKAGE|$capabilityPackageValue'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'SOURCE|TRANSPORT|$capabilityTransportValue'.",
        "      APPEND ls_source TO it_source.",
        "      CONCATENATE sy-sysid sy-mandt INTO lv_payload_value",
        "        SEPARATED BY '/'.",
        "      REPLACE ALL OCCURRENCES OF '%' IN lv_payload_value WITH '%25'.",
        "      REPLACE ALL OCCURRENCES OF '|' IN lv_payload_value WITH '%7C'.",
        "      CONCATENATE 'RUNTIME|HOST' lv_payload_value INTO ls_source-line",
        "        SEPARATED BY '|'.",
        "      APPEND ls_source TO it_source.",
        "      CONCATENATE sy-datum sy-uzeit INTO lv_payload_value.",
        "      REPLACE ALL OCCURRENCES OF '%' IN lv_payload_value WITH '%25'.",
        "      REPLACE ALL OCCURRENCES OF '|' IN lv_payload_value WITH '%7C'.",
        "      CONCATENATE 'RUNTIME|TIME' lv_payload_value sy-tzone",
        "        INTO ls_source-line SEPARATED BY '|'.",
        "      APPEND ls_source TO it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'CAPABILITIES'.",
        "      ev_version = '$helperCapabilityMaxVersion'.",
        "      ev_message = 'ORVANTA helper capabilities'.",
        "      RETURN."
    )
    # <<< ORVANTA-CAPABILITIES-SOURCE

    $repositoryFunctionSource = @(
        "  TYPE-POOLS abap.",
        "  DATA lt_fieldtexts TYPE TABLE OF d021t.",
        "  DATA ls_header TYPE d020s.",
        "  DATA ls_tadir TYPE tadir.",
        "  DATA lt_modsap TYPE TABLE OF modsap.",
        "  DATA ls_modsap TYPE modsap.",
        "  DATA ls_modsapt TYPE modsapt.",
        "  DATA lt_modact TYPE TABLE OF modact.",
        "  DATA ls_modact TYPE modact.",
        "  DATA ls_modattr TYPE modattr.",
        "  DATA ls_tbe01 TYPE tbe01.",
        "  DATA ls_tbe01t TYPE tbe01t.",
        "  DATA lt_tbe31 TYPE TABLE OF tbe31.",
        "  DATA ls_tbe31 TYPE tbe31.",
        "  DATA lt_tbe34 TYPE TABLE OF tbe34.",
        "  DATA ls_tbe34 TYPE tbe34.",
        "  DATA ls_tps01 TYPE tps01.",
        "  DATA ls_tps01t TYPE tps01t.",
        "  DATA lt_tps31 TYPE TABLE OF tps31.",
        "  DATA ls_tps31 TYPE tps31.",
        "  DATA lt_tps34 TYPE TABLE OF tps34.",
        "  DATA ls_tps34 TYPE tps34.",
        "  DATA ls_tbe11 TYPE tbe11.",
        "  DATA ls_tbe24 TYPE tbe24.",
        "  DATA lv_bte_application TYPE c LENGTH 20.",
        "  DATA lv_bte_product TYPE c LENGTH 20.",
        "  DATA ls_sxs_attr TYPE sxs_attr.",
