        "  DATA lt_sxs_inter TYPE TABLE OF sxs_inter.",
        "  DATA ls_sxs_inter TYPE sxs_inter.",
        "  DATA lt_sxc_exit TYPE TABLE OF sxc_exit.",
        "  DATA ls_sxc_exit TYPE sxc_exit.",
        "  DATA ls_sxc_attr TYPE sxc_attr.",
        "  DATA ls_sxc_attrt TYPE sxc_attrt.",
        "  DATA lt_sxc_class TYPE TABLE OF sxc_class.",
        "  DATA ls_sxc_class TYPE sxc_class.",
        "  DATA lv_badi_implementation TYPE c LENGTH 20.",
        "  DATA lv_badi_assignment_index TYPE i.",
        "  DATA lv_badi_class_index TYPE i.",
        "  DATA li_enh_tool TYPE REF TO if_enh_tool.",
        "  DATA li_enh_object TYPE REF TO if_enh_object.",
        "  DATA li_enh_docu TYPE REF TO if_enh_object_docu.",
        "  DATA lo_enh_hook TYPE REF TO cl_enh_tool_hook_impl.",
