        "  FIELD-SYMBOLS <ls_fm_changing> TYPE rscha.",
        "  FIELD-SYMBOLS <ls_fm_table> TYPE rstbl.",
        "  FIELD-SYMBOLS <ls_fm_exception> TYPE rsexc.",
        "  DATA: BEGIN OF ls_text_change,",
        "    id TYPE textpool-key,",
        "    entry TYPE textpool-entry,",
        "    length TYPE textpool-length,",
        "    action TYPE c LENGTH 6,",
        "  END OF ls_text_change.",
        "  DATA lt_text_changes LIKE TABLE OF ls_text_change.",
        "  FIELD-SYMBOLS <ls_text_change> LIKE ls_text_change.",
        "  FIELD-SYMBOLS <ls_message_row> TYPE t100.",
        "  DATA lv_payload_kind TYPE c LENGTH 1.",
        "  DATA lv_fm_payload_kind TYPE c LENGTH 2.",
        "  DATA lv_payload_index_text TYPE string.",
        "  DATA lv_payload_index TYPE i.",
        "  DATA lv_payload_property TYPE c LENGTH 30.",
        "  DATA lv_payload_value TYPE string.",
        "  DATA lv_patch_count TYPE i.",
        "  DATA lv_patch_index TYPE i.",
        "  DATA lv_patch_row_index TYPE i.",
        "  DATA lv_patch_operation TYPE c LENGTH 10.",
        "  DATA lv_patch_name TYPE c LENGTH 132.",
        "  DATA lv_patch_flow TYPE c LENGTH 1.",
        "  DATA lv_patch_params TYPE c LENGTH 1.",
        "  DATA lv_patch_header TYPE c LENGTH 1.",
        "  DATA lv_patch_description TYPE c LENGTH 1.",
        "  FIELD-SYMBOLS <ls_screen_field> TYPE rpy_dyfatc.",
        "  FIELD-SYMBOLS <ls_screen_flow> TYPE rpy_dyflow.",
        "  FIELD-SYMBOLS <ls_screen_param> TYPE rpy_dypara.",
        "  FIELD-SYMBOLS <lv_payload_component> TYPE any.",
        "  DEFINE add_repo_payload.",
        "    CLEAR ls_source.",
        "    lv_payload_index_text = &2.",
        "    CONDENSE lv_payload_index_text NO-GAPS.",
        "    lv_payload_value = &4.",
        "    REPLACE ALL OCCURRENCES OF '%'",
        "      IN lv_payload_value WITH '%25'.",
        "    REPLACE ALL OCCURRENCES OF '|'",
        "      IN lv_payload_value WITH '%7C'.",
        "    CONCATENATE &1 lv_payload_index_text &3",
        "      lv_payload_value INTO ls_source-line",
        "      SEPARATED BY '|'.",
        "    APPEND ls_source TO it_source.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_repo_component.",
        "    ASSIGN COMPONENT &3 OF STRUCTURE &4",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      add_repo_payload &1 &2 &3 <lv_payload_component>.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_repo_alias.",
        "    ASSIGN COMPONENT &4 OF STRUCTURE &5",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      add_repo_payload &1 &2 &3 <lv_payload_component>.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_bte_application.",
        "    CLEAR: lv_bte_application, ls_tbe11.",
        "    ASSIGN COMPONENT 'APPLK' OF STRUCTURE &3",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      IF <lv_payload_component> IS NOT INITIAL.",
        "        lv_bte_application = <lv_payload_component>.",
        "        SELECT SINGLE * FROM tbe11 INTO ls_tbe11",
        "          WHERE applk = lv_bte_application.",
        "        IF sy-subrc = 0.",
        "          add_repo_alias &1 &2 'APPLICATION_ACTIVE'",
        "            'AKTIV' ls_tbe11.",
        "          add_repo_alias &1 &2 'APPLICATION_TEXT'",
        "            'TXTSU' ls_tbe11.",
        "        ENDIF.",
        "      ENDIF.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_bte_product.",
        "    CLEAR: lv_bte_product, ls_tbe24.",
        "    ASSIGN COMPONENT 'PRDKT' OF STRUCTURE &3",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc <> 0.",
        "      ASSIGN COMPONENT 'PRODUCT' OF STRUCTURE &3",
        "        TO <lv_payload_component>.",
        "    ENDIF.",
        "    IF sy-subrc = 0.",
        "      IF <lv_payload_component> IS NOT INITIAL.",
        "        lv_bte_product = <lv_payload_component>.",
        "        SELECT SINGLE * FROM tbe24 INTO ls_tbe24",
        "          WHERE prdkt = lv_bte_product.",
        "        IF sy-subrc = 0.",
        "        ASSIGN COMPONENT 'AKTIV' OF STRUCTURE ls_tbe24",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ASSIGN COMPONENT 'ACTIVE' OF STRUCTURE ls_tbe24",
        "            TO <lv_payload_component>.",
        "        ENDIF.",
        "        IF sy-subrc = 0.",
        "          add_repo_payload &1 &2 'PRODUCT_ACTIVE'",
        "            <lv_payload_component>.",
        "        ENDIF.",
        "        UNASSIGN <lv_payload_component>.",
        "        ASSIGN COMPONENT 'TEXT1' OF STRUCTURE ls_tbe24",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ASSIGN COMPONENT 'TEXT' OF STRUCTURE ls_tbe24",
        "            TO <lv_payload_component>.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ASSIGN COMPONENT 'TXTSU' OF STRUCTURE ls_tbe24",
        "            TO <lv_payload_component>.",
        "        ENDIF.",
        "        IF sy-subrc = 0.",
        "          add_repo_payload &1 &2 'PRODUCT_TEXT'",
        "            <lv_payload_component>.",
        "        ENDIF.",
        "          add_repo_alias &1 &2 'PRODUCT_RFC_DESTINATION'",
        "            'RFCDS' ls_tbe24.",
        "        ENDIF.",
        "      ENDIF.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE emit_gui_payload.",
        "    REFRESH it_source.",
        "    add_repo_payload 'M' '1' 'VERSION'",
        "      lv_gui_current_version.",
        "    add_repo_payload 'M' '1' 'LANGUAGE' lv_gui_language.",
        "    add_repo_payload 'M' '1' 'AUTHOR' lv_gui_author.",
        "    add_repo_payload 'M' '1' 'DATE' lv_gui_date.",
        "    add_repo_payload 'M' '1' 'TIME' lv_gui_time.",
        "    add_repo_payload 'M' '1' 'CAUTHOR' lv_gui_cauthor.",
        "    add_repo_payload 'M' '1' 'CDATE' lv_gui_cdate.",
        "    add_repo_payload 'M' '1' 'CTIME' lv_gui_ctime.",
        "    add_repo_payload 'M' '1' 'GDATE' lv_gui_gdate.",
        "    add_repo_payload 'M' '1' 'GTIME' lv_gui_gtime.",
        "    add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "    add_repo_component 'ADM' '1' 'ACTCODE' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'MENCODE' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'PFKCODE' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'DEFAULTACT' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'DEFAULTPFK' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'MOD_LANGU' ls_gui_adm.",
        "    LOOP AT lt_gui_sta INTO ls_gui_sta.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'STA' lv_payload_index 'CODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'MODAL' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'ACTCODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'PFKCODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'BUTCODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'INT_NOTE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'CTXCODE' ls_gui_sta.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_fun INTO ls_gui_fun.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'FUN' lv_payload_index 'CODE' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TEXTNO' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TYPE' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'MODIF' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TEXT_TYPE' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TEXT_NAME' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'ICON_ID' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'FUN_TEXT' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'ICON_TEXT' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'INFO_TEXT' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'PATH' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'SFW_SWITCHID'",
        "        ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'SFW_SHOWHIDE'",
        "        ls_gui_fun.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_men INTO ls_gui_men.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'MEN' lv_payload_index 'CODE' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'NO' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'REF_TYPE' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'REF_CODE' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'REF_NO' ls_gui_men.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_mtx INTO ls_gui_mtx.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'MTX' lv_payload_index 'CODE' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'TEXT_TYPE' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'TEXT_NAME' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'INC_PROG' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'INC_STATUS'",
        "        ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'SFW_SWITCHID'",
        "        ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'SFW_SHOWHIDE'",
        "        ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'TEXT' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'PATH' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'INT_NOTE' ls_gui_mtx.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_act INTO ls_gui_act.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'ACT' lv_payload_index 'CODE' ls_gui_act.",
        "      add_repo_component 'ACT' lv_payload_index 'NO' ls_gui_act.",
        "      add_repo_component 'ACT' lv_payload_index 'MENUCODE' ls_gui_act.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_but INTO ls_gui_but.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'BUT' lv_payload_index 'PFK_CODE' ls_gui_but.",
        "      add_repo_component 'BUT' lv_payload_index 'CODE' ls_gui_but.",
        "      add_repo_component 'BUT' lv_payload_index 'NO' ls_gui_but.",
        "      add_repo_component 'BUT' lv_payload_index 'PFNO' ls_gui_but.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_pfk INTO ls_gui_pfk.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'PFK' lv_payload_index 'CODE' ls_gui_pfk.",
        "      add_repo_component 'PFK' lv_payload_index 'PFNO' ls_gui_pfk.",
        "      add_repo_component 'PFK' lv_payload_index 'FUNCODE' ls_gui_pfk.",
        "      add_repo_component 'PFK' lv_payload_index 'FUNNO' ls_gui_pfk.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_set INTO ls_gui_set.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'SET' lv_payload_index 'STATUS' ls_gui_set.",
        "      add_repo_component 'SET' lv_payload_index 'FUNCTION'",
        "        ls_gui_set.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_doc INTO ls_gui_doc.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'DOC' lv_payload_index 'OBJ_TYPE' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'OBJ_CODE' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'SUB_CODE' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'MODAL' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'NORM' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'INT_NOTE' ls_gui_doc.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_tit INTO ls_gui_tit.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'TIT' lv_payload_index 'CODE' ls_gui_tit.",
        "      add_repo_component 'TIT' lv_payload_index 'TEXT' ls_gui_tit.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_biv INTO ls_gui_biv.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'BIV' lv_payload_index 'OBJ_CODE' ls_gui_biv.",
        "      add_repo_component 'BIV' lv_payload_index 'SUB_CODE' ls_gui_biv.",
        "      add_repo_component 'BIV' lv_payload_index 'FCODE' ls_gui_biv.",
        "    ENDLOOP.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_repo_passvalue.",
        "    ASSIGN COMPONENT 'REFERENCE' OF STRUCTURE &3",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      CLEAR lv_payload_value.",
        "      IF <lv_payload_component> IS INITIAL.",
        "        lv_payload_value = 'X'.",
        "      ENDIF.",
        "      add_repo_payload &1 &2 'PASSVALUE' lv_payload_value.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE validate_enh_transport.",
        "    IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "       OR iv_request IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'ENH_WRITE_INPUT_REQUIRED'.",
        "      ev_message = 'Transportable package and request required'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    CLEAR: ls_package, ls_request, ls_task.",
        "    SELECT SINGLE * FROM tdevc INTO ls_package",
        "      WHERE devclass = iv_package.",
        "    IF sy-subrc <> 0.",
        "      ev_status = 'E'. ev_code = 'PACKAGE_NOT_FOUND'.",
        "      ev_message = 'Transportable package does not exist'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    SELECT SINGLE * FROM e070 INTO ls_request",
        "      WHERE trkorr = iv_request.",
        "    IF sy-subrc <> 0.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "      ev_message = 'Transport request or task does not exist'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    IF ls_request-strkorr IS NOT INITIAL.",
        "      ls_task = ls_request.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = ls_task-strkorr.",
        "    ELSE.",
        "      SELECT SINGLE * FROM e070 INTO ls_task",
        "        WHERE strkorr = ls_request-trkorr",
        "          AND as4user = sy-uname AND trstatus = 'D'.",
        "    ENDIF.",
        "    IF ls_request-trfunction <> 'K'",
        "       OR ls_request-trstatus <> 'D'",
        "       OR ls_task-trstatus <> 'D'",
        "       OR ls_task-as4user <> sy-uname.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "      ev_message = 'Open workbench task for user is required'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    lv_enh_devclass = iv_package.",
        "    lv_enh_trkorr = ls_task-trkorr.",
        "  END-OF-DEFINITION.",
        "  DEFINE emit_fm_difference.",
        "* One native difference per section; values bounded to 60 chars.",
        "    IF &2[] <> &3[].",
        "      ADD 1 TO lv_fm_diff_id.",
        "      add_repo_payload 'D' lv_fm_diff_id 'SECTION' &1.",
        "      lv_fm_diff_count = lines( &2 ).",
        "      add_repo_payload 'D' lv_fm_diff_id 'EXPECTED_ROWS'",
        "        lv_fm_diff_count.",
        "      lv_fm_diff_count = lines( &3 ).",
        "      add_repo_payload 'D' lv_fm_diff_id 'ACTUAL_ROWS'",
        "        lv_fm_diff_count.",
        "      LOOP AT &2 ASSIGNING <ls_fm_diff_expected>.",
        "        lv_fm_diff_row = sy-tabix.",
        "        READ TABLE &3 ASSIGNING <ls_fm_diff_actual>",
        "          INDEX lv_fm_diff_row.",
        "        IF sy-subrc <> 0.",
        "          add_repo_payload 'D' lv_fm_diff_id 'ROW'",
        "            lv_fm_diff_row.",
        "          add_repo_payload 'D' lv_fm_diff_id 'FIELD'",
        "            'MISSING_ROW'.",
        "          EXIT.",
        "        ENDIF.",
        "        IF <ls_fm_diff_expected> = <ls_fm_diff_actual>.",
        "          CONTINUE.",
        "        ENDIF.",
        "        add_repo_payload 'D' lv_fm_diff_id 'ROW'",
        "          lv_fm_diff_row.",
        "        lo_fm_diff ?= cl_abap_typedescr=>describe_by_data(",
        "          <ls_fm_diff_expected> ).",
        "        lt_fm_diff_components = lo_fm_diff->get_components( ).",
        "        LOOP AT lt_fm_diff_components INTO ls_fm_diff_component.",
        "          ASSIGN COMPONENT ls_fm_diff_component-name",
        "            OF STRUCTURE <ls_fm_diff_expected>",
        "            TO <lv_fm_diff_expected>.",
        "          IF sy-subrc <> 0. CONTINUE. ENDIF.",
        "          ASSIGN COMPONENT ls_fm_diff_component-name",
        "            OF STRUCTURE <ls_fm_diff_actual>",
        "            TO <lv_fm_diff_actual>.",
        "          IF sy-subrc <> 0. CONTINUE. ENDIF.",
        "          IF <lv_fm_diff_expected> = <lv_fm_diff_actual>.",
        "            CONTINUE.",
        "          ENDIF.",
        "          add_repo_payload 'D' lv_fm_diff_id 'FIELD'",
        "            ls_fm_diff_component-name.",
        "          lv_fm_diff_text = <lv_fm_diff_expected>.",
        "          add_repo_payload 'D' lv_fm_diff_id 'EXPECTED'",
        "            lv_fm_diff_text.",
        "          lv_fm_diff_text = <lv_fm_diff_actual>.",
        "          add_repo_payload 'D' lv_fm_diff_id 'ACTUAL'",
        "            lv_fm_diff_text.",
        "          EXIT.",
        "        ENDLOOP.",
        "        EXIT.",
        "      ENDLOOP.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE emit_fm_payload.",
        "    REFRESH it_source.",
        "    add_repo_payload 'M' '1' 'FUNCTION_GROUP'",
        "      lv_function_pool.",
        "    add_repo_payload 'M' '1' 'SHORT_TEXT' lv_short_text.",
        "    add_repo_payload 'M' '1' 'REMOTE_ENABLED'",
        "      lv_remote_call.",
        "    add_repo_payload 'M' '1' 'UPDATE_TASK' lv_update_task.",
        "    add_repo_payload 'M' '1' 'GLOBAL_INTERFACE'",
        "      lv_global_flag.",
        "    LOOP AT lt_fm_import INTO ls_fm_import.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'I' lv_payload_index 'PARAMETER'",
        "        ls_fm_import.",
        "      add_repo_component 'I' lv_payload_index 'TYP'",
        "        ls_fm_import.",
        "      add_repo_component 'I' lv_payload_index 'DBFIELD'",
        "        ls_fm_import.",
        "      add_repo_component 'I' lv_payload_index 'OPTIONAL'",
        "        ls_fm_import.",
        "      add_repo_passvalue 'I' lv_payload_index ls_fm_import.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_import-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'I' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_export INTO ls_fm_export.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'E' lv_payload_index 'PARAMETER'",
        "        ls_fm_export.",
        "      add_repo_component 'E' lv_payload_index 'TYP'",
        "        ls_fm_export.",
        "      add_repo_component 'E' lv_payload_index 'DBFIELD'",
        "        ls_fm_export.",
        "      add_repo_component 'E' lv_payload_index 'OPTIONAL'",
        "        ls_fm_export.",
        "      add_repo_passvalue 'E' lv_payload_index ls_fm_export.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_export-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'E' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_changing INTO ls_fm_changing.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'C' lv_payload_index 'PARAMETER'",
        "        ls_fm_changing.",
        "      add_repo_component 'C' lv_payload_index 'TYP'",
        "        ls_fm_changing.",
        "      add_repo_component 'C' lv_payload_index 'DBFIELD'",
        "        ls_fm_changing.",
        "      add_repo_component 'C' lv_payload_index 'OPTIONAL'",
        "        ls_fm_changing.",
        "      add_repo_passvalue 'C' lv_payload_index ls_fm_changing.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_changing-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'C' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_tables INTO ls_fm_table.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'T' lv_payload_index 'PARAMETER'",
        "        ls_fm_table.",
        "      add_repo_component 'T' lv_payload_index 'TYP'",
        "        ls_fm_table.",
        "      add_repo_component 'T' lv_payload_index 'DBSTRUCT'",
        "        ls_fm_table.",
        "      add_repo_component 'T' lv_payload_index 'OPTIONAL'",
        "        ls_fm_table.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_table-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'T' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_exceptions INTO ls_fm_exception.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'X' lv_payload_index 'EXCEPTION'",
        "        ls_fm_exception.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_exception-exception",
        "          kind = 'X'.",
        "      add_repo_payload 'X' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_source INTO ls_fm_source.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_payload 'S' lv_payload_index 'LINE'",
        "        ls_fm_source-line.",
        "    ENDLOOP.",
        "  END-OF-DEFINITION.",
        "  IF iv_operation = 'UPSERT_SCREEN'",
        "     OR iv_operation = 'PATCH_SCREEN'",
        "     OR iv_operation = 'PATCH_GUI_DEFINITION'",
        "     OR iv_operation = 'CREATE_MODULE_POOL'",
        "     OR iv_operation = 'DELETE_MODULE_POOL'",
        "     OR iv_operation = 'MERGE_TEXT_ELEMENTS'",
        "     OR iv_operation = 'CREATE_REPORT_TRANSACTION'.",
        "    IF iv_program IS INITIAL",
        "       OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_PROGRAM_REQUIRED'.",
        "      ev_message = 'Only Z or Y programs are allowed'.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'READ_SCREEN'",
        "     OR iv_operation = 'READ_GUI_DEFINITION'.",
        "    IF iv_program IS INITIAL.",
        "      ev_status = 'E'.",
        "      ev_code = 'PROGRAM_REQUIRED'.",
        "      ev_message = 'Program name is required'.",
        "      ev_version = '2.2'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_TRANSACTION'",
        "     OR iv_operation = 'DELETE_TRANSACTION'",
        "     OR iv_operation = 'CREATE_REPORT_TRANSACTION'.",
        "    IF iv_transaction IS INITIAL",
        "       OR ( iv_transaction(1) <> 'Z'",
        "       AND iv_transaction(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_TRANSACTION_REQUIRED'.",
        "      ev_message = 'Only Z or Y transactions are allowed'.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'READ_TRANSACTION'.",
        "    IF iv_transaction IS INITIAL.",
        "      ev_status = 'E'.",
        "      ev_code = 'TRANSACTION_REQUIRED'.",
        "      ev_message = 'Transaction name is required'.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_MESSAGE_CLASS'",
        "     OR iv_operation = 'UPDATE_MESSAGE_CLASS'",
        "     OR iv_operation = 'DELETE_MESSAGE_CLASS'.",
        "    IF iv_object_name IS INITIAL",
        "       OR ( iv_object_name(1) <> 'Z'",
        "       AND iv_object_name(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_MESSAGE_CLASS_REQUIRED'.",
        "      ev_message = 'Only Z or Y message classes are allowed'.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_FUNCTION_GROUP'.",
        "    IF iv_object_name IS INITIAL",
        "       OR ( iv_object_name(1) <> 'Z'",
        "       AND iv_object_name(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_FUNCTION_GROUP_REQUIRED'.",
        "      ev_message = 'Only Z or Y function groups are allowed'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_FUNCTION_INCLUDE'.",
        "    IF iv_program IS INITIAL",
        "       OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' )",
        "       OR iv_object_name IS INITIAL.",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_FUNCTION_INCLUDE_REQUIRED'.",
        "      ev_message = 'Only Z or Y function group Includes allowed'.",
        "      ev_version = '1.7'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  CASE iv_operation."
    ) + $capabilityBranchLines + @(
        "    WHEN 'READ_ENHANCEMENT_IMPLEMENTATION'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_REQUIRED'.",
        "        ev_message = 'Exact enhancement name is required'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name",
        "            run_dark = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          li_enh_docu ?= li_enh_tool.",
        "          lv_enh_tool_type = li_enh_tool->get_tool( ).",
        "          lv_enh_shorttext =",
        "            li_enh_docu->get_shorttext( ).",
        "          lv_enh_active =",
        "            li_enh_object->has_active_version( ).",
        "          lv_enh_inactive =",
        "            li_enh_object->has_inactive_version( ).",
        "          lv_enh_saved_inactive =",
        "            li_enh_object->has_saved_inactive_version( ).",
        "          lv_enh_unsaved_inactive =",
        "            li_enh_object->has_not_saved_inactive_version( ).",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_READ_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.5'. RETURN.",
        "      ENDTRY.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NAME' iv_object_name.",
        "      add_repo_payload 'M' '1' 'TOOL' lv_enh_tool_type.",
        "      add_repo_payload 'M' '1' 'SHORT_TEXT' lv_enh_shorttext.",
        "      add_repo_payload 'M' '1' 'ACTIVE' lv_enh_active.",
        "      add_repo_payload 'M' '1' 'INACTIVE' lv_enh_inactive.",
        "      add_repo_payload 'M' '1' 'SAVED_INACTIVE'",
        "        lv_enh_saved_inactive.",
        "      add_repo_payload 'M' '1' 'UNSAVED_INACTIVE'",
        "        lv_enh_unsaved_inactive.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      IF lv_enh_tool_type = cl_enh_tool_hook_impl=>tooltype.",
        "        lo_enh_hook ?= li_enh_tool.",
        "        CLEAR ls_enh_hook_admin.",
        "        lo_enh_hook->get_original_object(",
        "          IMPORTING pgmid = ls_enh_hook_admin-pgmid",
        "            obj_name = ls_enh_hook_admin-org_obj_name",
        "            obj_type = ls_enh_hook_admin-org_obj_type",
        "            main_type = ls_enh_hook_admin-org_main_type",
        "            main_name = ls_enh_hook_admin-org_main_name",
        "            program = ls_enh_hook_admin-programname ).",
        "        add_repo_payload 'M' '1' 'ORIGINAL_OBJECT_TYPE'",
        "          ls_enh_hook_admin-org_obj_type.",
        "        add_repo_payload 'M' '1' 'ORIGINAL_OBJECT_NAME'",
        "          ls_enh_hook_admin-org_obj_name.",
        "        add_repo_payload 'M' '1' 'MAIN_OBJECT_TYPE'",
        "          ls_enh_hook_admin-org_main_type.",
        "        add_repo_payload 'M' '1' 'MAIN_OBJECT_NAME'",
        "          ls_enh_hook_admin-org_main_name.",
        "        add_repo_payload 'M' '1' 'PROGRAM_NAME'",
        "          ls_enh_hook_admin-programname.",
        "        lt_enh_hooks = lo_enh_hook->get_hook_impls( ).",
        "        CLEAR: lv_enh_row_count, lv_badi_class_index.",
        "        LOOP AT lt_enh_hooks INTO ls_enh_hook.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_payload 'H' lv_payload_index 'SPOT_NAME'",
        "            ls_enh_hook-spotname.",
        "          add_repo_payload 'H' lv_payload_index 'PROGRAM_NAME'",
        "            ls_enh_hook-programname.",
        "          add_repo_payload 'H' lv_payload_index 'EXTID'",
        "            ls_enh_hook-extid.",
        "          add_repo_payload 'H' lv_payload_index 'ID'",
        "            ls_enh_hook-id.",
        "          add_repo_payload 'H' lv_payload_index 'OVERWRITE'",
        "            ls_enh_hook-overwrite.",
        "          add_repo_payload 'H' lv_payload_index 'METHOD'",
        "            ls_enh_hook-method.",
        "          add_repo_payload 'H' lv_payload_index 'MODE'",
        "            ls_enh_hook-enhmode.",
        "          add_repo_payload 'H' lv_payload_index 'FULL_NAME'",
        "            ls_enh_hook-full_name.",
        "          add_repo_payload 'H' lv_payload_index",
        "            'PARENT_FULL_NAME' ls_enh_hook-parent_full_name.",
        "          DESCRIBE TABLE ls_enh_hook-source",
        "            LINES lv_enh_row_count.",
        "          add_repo_payload 'H' lv_payload_index 'SOURCE_COUNT'",
        "            lv_enh_row_count.",
        "          LOOP AT ls_enh_hook-source INTO lv_enh_source_line.",
        "            lv_enh_source_index = sy-tabix.",
        "            ADD 1 TO lv_badi_class_index.",
        "            add_repo_payload 'S' lv_badi_class_index",
        "              'HOOK_INDEX' lv_payload_index.",
        "            add_repo_payload 'S' lv_badi_class_index",
        "              'LINE_NUMBER' lv_enh_source_index.",
        "            add_repo_payload 'S' lv_badi_class_index 'LINE'",
        "              lv_enh_source_line.",
        "          ENDLOOP.",
        "        ENDLOOP.",
        "      ELSEIF lv_enh_tool_type =",
        "             cl_enh_tool_badi_impl=>tooltype.",
        "        lo_enh_badi ?= li_enh_tool.",
        "        lv_enh_spot_name = lo_enh_badi->get_spot_name( ).",
        "        add_repo_payload 'M' '1' 'SPOT_NAME' lv_enh_spot_name.",
        "        lt_enh_badis = lo_enh_badi->get_implementations( ).",
        "        CLEAR lv_badi_class_index.",
        "        LOOP AT lt_enh_badis INTO ls_enh_badi.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_payload 'B' lv_payload_index 'SPOT_NAME'",
        "            ls_enh_badi-spot_name.",
        "          add_repo_payload 'B' lv_payload_index 'BADI_NAME'",
        "            ls_enh_badi-badi_name.",
        "          add_repo_payload 'B' lv_payload_index 'IMPL_NAME'",
        "            ls_enh_badi-impl_name.",
        "          add_repo_payload 'B' lv_payload_index 'IMPL_CLASS'",
        "            ls_enh_badi-impl_class.",
        "          add_repo_payload 'B' lv_payload_index 'ACTIVE'",
        "            ls_enh_badi-active.",
        "          add_repo_payload 'B' lv_payload_index 'IS_DEFAULT'",
        "            ls_enh_badi-is_default.",
        "          add_repo_payload 'B' lv_payload_index 'SHORT_TEXT'",
        "            ls_enh_badi-impl_shorttext.",
        "          ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "            TO <lt_enh_filters>.",
        "          IF sy-subrc = 0.",
        "            LOOP AT <lt_enh_filters> ASSIGNING <ls_enh_filter>.",
        "              ADD 1 TO lv_badi_class_index.",
        "              add_repo_payload 'F' lv_badi_class_index",
        "                'IMPLEMENTATION_NAME' ls_enh_badi-impl_name.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'DISJ_IDX' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'CONJ_IDX' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_NAME' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_TYPE' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'COMPARE' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_CHAR_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_CHAR_VALUE2' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_INT_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_INT_VALUE2' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_NUMERIC_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_NUMERIC_VALUE2' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_STRING_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_STRING_VALUE2' <ls_enh_filter>.",
        "            ENDLOOP.",
        "          ENDIF.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'ENHANCEMENT_IMPLEMENTATION_READ'.",
        "      ev_message = 'Enhancement implementation read'.",
        "      ev_version = '2.6'. RETURN.",
        "    WHEN 'CREATE_HOOK_ENHANCEMENT'",
        "      OR 'CREATE_BADI_ENHANCEMENT'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' )",
        "         OR iv_description IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'ENH_CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Customer name and description required'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_EXISTS'.",
        "        ev_message = 'Enhancement implementation exists'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_enh_hook_admin, ls_enh_badi,",
        "        lv_enh_full_name, lv_enh_mode, lv_enh_overwrite,",
        "        lv_enh_spot_name, lv_enh_badi_name,",
        "        lv_enh_impl_name, lv_enh_impl_class, lv_enh_default.",
        "      REFRESH lt_enh_source.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Enhancement payload index invalid'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        TRANSLATE lv_payload_property TO UPPER CASE.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'M'.",
        "          CASE lv_payload_property.",
        "            WHEN 'ORIGINAL_OBJECT_TYPE'.",
        "              ls_enh_hook_admin-org_obj_type = lv_payload_value.",
        "            WHEN 'ORIGINAL_OBJECT_NAME'.",
        "              ls_enh_hook_admin-org_obj_name = lv_payload_value.",
        "            WHEN 'MAIN_OBJECT_TYPE'.",
        "              ls_enh_hook_admin-org_main_type = lv_payload_value.",
        "            WHEN 'MAIN_OBJECT_NAME'.",
        "              ls_enh_hook_admin-org_main_name = lv_payload_value.",
        "            WHEN 'PROGRAM_NAME'.",
        "              ls_enh_hook_admin-programname = lv_payload_value.",
        "            WHEN 'FULL_NAME'.",
        "              lv_enh_full_name = lv_payload_value.",
        "            WHEN 'MODE'. lv_enh_mode = lv_payload_value.",
        "            WHEN 'REPLACEMENT'.",
        "              lv_enh_overwrite = lv_payload_value.",
        "            WHEN 'SPOT_NAME'.",
        "              lv_enh_spot_name = lv_payload_value.",
        "            WHEN 'BADI_NAME'.",
        "              lv_enh_badi_name = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_NAME'.",
        "              lv_enh_impl_name = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_CLASS'.",
        "              lv_enh_impl_class = lv_payload_value.",
        "            WHEN 'DEFAULT_IMPLEMENTATION'.",
        "              lv_enh_default = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Enhancement property not allowed'.",
        "              ev_version = '2.5'. RETURN.",
        "          ENDCASE.",
        "        ELSEIF lv_payload_kind = 'S'",
        "          AND iv_operation = 'CREATE_HOOK_ENHANCEMENT'",
        "          AND lv_payload_property = 'LINE'.",
        "          APPEND lv_payload_value TO lt_enh_source.",
        "        ELSEIF lv_payload_kind = 'F'",
        "          AND iv_operation = 'CREATE_BADI_ENHANCEMENT'.",
        "          ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "            TO <lt_enh_filters>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_TYPE_INVALID'.",
        "            ev_message = 'BAdI filter structure unavailable'.",
        "            ev_version = '2.5'. RETURN.",
        "          ENDIF.",
        "          DESCRIBE TABLE <lt_enh_filters>",
        "            LINES lv_enh_row_count.",
        "          WHILE lv_enh_row_count < lv_payload_index.",
        "            APPEND INITIAL LINE TO <lt_enh_filters>.",
        "            ADD 1 TO lv_enh_row_count.",
        "          ENDWHILE.",
        "          READ TABLE <lt_enh_filters>",
        "            ASSIGNING <ls_enh_filter> INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_enh_filter>",
        "            TO <lv_payload_component>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown New BAdI filter property'.",
        "            ev_version = '2.5'. RETURN.",
        "          ENDIF.",
        "          <lv_payload_component> = lv_payload_value.",
        "        ELSE.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unexpected enhancement payload row'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      ls_enh_hook_admin-pgmid = 'R3TR'.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          IF iv_operation = 'CREATE_HOOK_ENHANCEMENT'.",
        "            IF ls_enh_hook_admin-org_obj_type IS INITIAL",
        "               OR ls_enh_hook_admin-org_obj_name IS INITIAL",
        "               OR ls_enh_hook_admin-org_main_type IS INITIAL",
        "               OR ls_enh_hook_admin-org_main_name IS INITIAL",
        "               OR ls_enh_hook_admin-programname IS INITIAL",
        "               OR lv_enh_full_name IS INITIAL",
        "               OR lv_enh_mode IS INITIAL.",
        "              ev_status = 'E'.",
        "              ev_code = 'HOOK_CREATE_INPUT_REQUIRED'.",
        "              ev_message = 'Complete hook identity required'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            cl_enh_factory=>create_enhancement(",
        "              EXPORTING enhname = lv_enh_name",
        "                enhtype =",
        "                  cl_abstract_enh_tool_redef=>credefinition",
        "                enhtooltype = cl_enh_tool_hook_impl=>tooltype",
        "                dark = 'X'",
        "              IMPORTING enhancement = li_enh_tool",
        "              CHANGING trkorr = lv_enh_trkorr",
        "                devclass = lv_enh_devclass ).",
        "            li_enh_object ?= li_enh_tool.",
        "            lo_enh_hook ?= li_enh_tool.",
        "            lv_enh_shorttext = iv_description.",
        "            lo_enh_hook->if_enh_object_docu~set_shorttext(",
        "              lv_enh_shorttext ).",
        "            lo_enh_hook->set_original_object(",
        "              pgmid = ls_enh_hook_admin-pgmid",
        "              obj_name = ls_enh_hook_admin-org_obj_name",
        "              obj_type = ls_enh_hook_admin-org_obj_type",
        "              program = ls_enh_hook_admin-programname",
        "              main_type = ls_enh_hook_admin-org_main_type",
        "              main_name = ls_enh_hook_admin-org_main_name ).",
        "            lo_enh_hook->add_hook_impl(",
        "              overwrite = lv_enh_overwrite method = space",
        "              enhmode = lv_enh_mode full_name = lv_enh_full_name",
        "              source = lt_enh_source ).",
        "          ELSE.",
        "            IF lv_enh_spot_name IS INITIAL",
        "               OR lv_enh_badi_name IS INITIAL",
        "               OR lv_enh_impl_name IS INITIAL",
        "               OR lv_enh_impl_class IS INITIAL.",
        "              ev_status = 'E'.",
        "              ev_code = 'BADI_CREATE_INPUT_REQUIRED'.",
        "              ev_message = 'Complete New BAdI identity required'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            cl_enh_factory=>create_enhancement(",
        "              EXPORTING enhname = lv_enh_name",
        "                enhtype =",
        "                  cl_abstract_enh_tool_redef=>credefinition",
        "                enhtooltype = cl_enh_tool_badi_impl=>tooltype",
        "                dark = 'X'",
        "              IMPORTING enhancement = li_enh_tool",
        "              CHANGING trkorr = lv_enh_trkorr",
        "                devclass = lv_enh_devclass ).",
        "            li_enh_object ?= li_enh_tool.",
        "            lo_enh_badi ?= li_enh_tool.",
        "            lo_enh_badi->set_spot_name( lv_enh_spot_name ).",
        "            lv_enh_shorttext = iv_description.",
        "            lo_enh_badi->if_enh_object_docu~set_shorttext(",
        "              lv_enh_shorttext ).",
        "            ls_enh_badi-spot_name = lv_enh_spot_name.",
        "            ls_enh_badi-badi_name = lv_enh_badi_name.",
        "            ls_enh_badi-impl_name = lv_enh_impl_name.",
        "            ls_enh_badi-impl_class = lv_enh_impl_class.",
        "            ls_enh_badi-active = 'X'.",
        "            ls_enh_badi-is_default = lv_enh_default.",
        "            ls_enh_badi-impl_shorttext = iv_description.",
        "            lo_enh_badi->add_implementation( ls_enh_badi ).",
        "          ENDIF.",
        "          li_enh_object->save(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->activate(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_CREATE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.5'. RETURN.",
        "      ENDTRY.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'CREATE_HOOK_ENHANCEMENT'.",
        "        ev_code = 'HOOK_ENHANCEMENT_CREATED'.",
        "      ELSE.",
        "        ev_code = 'BADI_ENHANCEMENT_CREATED'.",
        "      ENDIF.",
        "      ev_message = 'Enhancement created and activated'.",
        "      ev_version = '2.5'. RETURN.",
        "    WHEN 'UPDATE_HOOK_ENHANCEMENT'",
        "      OR 'UPDATE_BADI_ENHANCEMENT'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_ENHANCEMENT_REQUIRED'.",
        "        ev_message = 'Only Z or Y enhancements are writable'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      IF ls_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Enhancement belongs to another package'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_enh_badi, ls_enh_badi_existing,",
        "        lv_enh_extid, lv_enh_impl_name,",
        "        lv_enh_impl_class, lv_enh_impl_active,",
        "        lv_enh_default.",
        "      REFRESH lt_enh_source.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Enhancement payload index invalid'.",
        "          ev_version = '2.6'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        TRANSLATE lv_payload_property TO UPPER CASE.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'M'.",
        "          CASE lv_payload_property.",
        "            WHEN 'EXTID'. lv_enh_extid = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_NAME'.",
        "              lv_enh_impl_name = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_CLASS'.",
        "              lv_enh_impl_class = lv_payload_value.",
        "            WHEN 'ACTIVE'.",
        "              lv_enh_impl_active = lv_payload_value.",
        "            WHEN 'DEFAULT_IMPLEMENTATION'.",
        "              lv_enh_default = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Enhancement property not allowed'.",
        "              ev_version = '2.6'. RETURN.",
        "          ENDCASE.",
        "        ELSEIF lv_payload_kind = 'S'",
        "          AND iv_operation = 'UPDATE_HOOK_ENHANCEMENT'",
        "          AND lv_payload_property = 'LINE'.",
        "          APPEND lv_payload_value TO lt_enh_source.",
        "        ELSEIF lv_payload_kind = 'F'",
        "          AND iv_operation = 'UPDATE_BADI_ENHANCEMENT'.",
        "          ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "            TO <lt_enh_filters>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_TYPE_INVALID'.",
        "            ev_message = 'BAdI filter structure unavailable'.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          DESCRIBE TABLE <lt_enh_filters>",
        "            LINES lv_enh_row_count.",
        "          WHILE lv_enh_row_count < lv_payload_index.",
        "            APPEND INITIAL LINE TO <lt_enh_filters>.",
        "            ADD 1 TO lv_enh_row_count.",
        "          ENDWHILE.",
        "          READ TABLE <lt_enh_filters>",
        "            ASSIGNING <ls_enh_filter> INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_enh_filter>",
        "            TO <lv_payload_component>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown New BAdI filter property'.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          <lv_payload_component> = lv_payload_value.",
        "        ELSE.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unexpected enhancement payload row'.",
        "          ev_version = '2.6'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF iv_operation = 'UPDATE_HOOK_ENHANCEMENT'",
        "         AND lv_enh_extid IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'HOOK_UPDATE_INPUT_REQUIRED'.",
        "        ev_message = 'Exact hook extId is required'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      IF iv_operation = 'UPDATE_BADI_ENHANCEMENT'",
        "         AND ( lv_enh_impl_name IS INITIAL",
        "           OR lv_enh_impl_class IS INITIAL ).",
        "        ev_status = 'E'. ev_code = 'BADI_UPDATE_INPUT_REQUIRED'.",
        "        ev_message = 'Implementation name and class required'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name run_dark = 'X'",
        "            lock = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          li_enh_docu ?= li_enh_tool.",
        "          lv_enh_inactive =",
        "            li_enh_object->has_inactive_version( ).",
        "          IF lv_enh_inactive = 'X'.",
        "            li_enh_object->unlock( ).",
        "            ev_status = 'E'.",
        "            ev_code = 'ENHANCEMENT_INACTIVE_VERSION_EXISTS'.",
        "            ev_message = 'Resolve inactive version before update'.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          lv_enh_tool_type = li_enh_tool->get_tool( ).",
        "          IF iv_operation = 'UPDATE_HOOK_ENHANCEMENT'.",
        "            IF lv_enh_tool_type <> cl_enh_tool_hook_impl=>tooltype.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'.",
        "              ev_code = 'ENHANCEMENT_TOOL_TYPE_MISMATCH'.",
        "              ev_message = 'ENHO is not a hook implementation'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            lo_enh_hook ?= li_enh_tool.",
        "            lt_enh_hooks = lo_enh_hook->get_hook_impls( 'A' ).",
        "            READ TABLE lt_enh_hooks INTO ls_enh_hook",
        "              WITH KEY extid = lv_enh_extid.",
        "            IF sy-subrc <> 0.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'. ev_code = 'ENHANCEMENT_HOOK_NOT_FOUND'.",
        "              ev_message = 'Hook extId not found'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            lo_enh_hook->modify_hook_impl(",
        "              overwrite = ls_enh_hook-overwrite",
        "              method = ls_enh_hook-method",
        "              enhmode = ls_enh_hook-enhmode",
        "              full_name = ls_enh_hook-full_name",
        "              source = lt_enh_source extid = lv_enh_extid",
        "              spot = ls_enh_hook-spotname",
        "              parent_full_name = ls_enh_hook-parent_full_name ).",
        "          ELSE.",
        "            IF lv_enh_tool_type <> cl_enh_tool_badi_impl=>tooltype.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'.",
        "              ev_code = 'ENHANCEMENT_TOOL_TYPE_MISMATCH'.",
        "              ev_message = 'ENHO is not a BAdI implementation'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            lo_enh_badi ?= li_enh_tool.",
        "            ls_enh_badi_existing = lo_enh_badi->get_implementation(",
        "              impl_name = lv_enh_impl_name version = 'A' ).",
        "            ls_enh_badi_existing-impl_class = lv_enh_impl_class.",
        "            ls_enh_badi_existing-active = lv_enh_impl_active.",
        "            ls_enh_badi_existing-is_default = lv_enh_default.",
        "            IF iv_description IS NOT INITIAL.",
        "              ls_enh_badi_existing-impl_shorttext =",
        "                iv_description.",
        "            ENDIF.",
        "            ASSIGN COMPONENT 'FILTERS'",
        "              OF STRUCTURE ls_enh_badi_existing",
        "              TO <lt_enh_existing_filters>.",
        "            ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "              TO <lt_enh_filters>.",
        "            IF sy-subrc <> 0",
        "               OR <lt_enh_existing_filters> IS NOT ASSIGNED.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'. ev_code = 'FILTER_TYPE_INVALID'.",
        "              ev_message = 'BAdI filter structure unavailable'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            <lt_enh_existing_filters> = <lt_enh_filters>.",
        "            lo_enh_badi->delete_implementation( lv_enh_impl_name ).",
        "            lo_enh_badi->add_implementation(",
        "              ls_enh_badi_existing ).",
        "          ENDIF.",
        "          IF iv_description IS NOT INITIAL.",
        "            lv_enh_shorttext = iv_description.",
        "            li_enh_docu->set_shorttext(",
        "              lv_enh_shorttext ).",
        "          ENDIF.",
        "          li_enh_object->save(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->activate(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_UPDATE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.6'. RETURN.",
        "      ENDTRY.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'UPDATE_HOOK_ENHANCEMENT'.",
        "        ev_code = 'HOOK_ENHANCEMENT_UPDATED'.",
        "      ELSE.",
        "        ev_code = 'BADI_ENHANCEMENT_UPDATED'.",
        "      ENDIF.",
        "      ev_message = 'Enhancement updated and activated'.",
        "      ev_version = '2.6'. RETURN.",
        "    WHEN 'MANAGE_ENHANCEMENT_STATE'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' )",
        "         OR ( iv_object_type <> 'ACTIVATE'",
        "           AND iv_object_type <> 'DISCARD_INACTIVE' ).",
        "        ev_status = 'E'. ev_code = 'ENH_STATE_INPUT_INVALID'.",
        "        ev_message = 'Customer enhancement and action required'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      IF ls_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Enhancement belongs to another package'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name run_dark = 'X'",
        "            lock = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          lv_enh_inactive =",
        "            li_enh_object->has_inactive_version( ).",
        "          IF lv_enh_inactive IS INITIAL.",
        "            li_enh_object->unlock( ).",
        "            IF iv_object_type = 'ACTIVATE'.",
        "              ev_status = 'S'. ev_code = 'ENHANCEMENT_ALREADY_ACTIVE'.",
        "              ev_message = 'No inactive version to activate'.",
        "            ELSE.",
        "              ev_status = 'E'.",
        "              ev_code = 'ENHANCEMENT_NO_INACTIVE_VERSION'.",
        "              ev_message = 'No inactive version to discard'.",
        "            ENDIF.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          IF iv_object_type = 'ACTIVATE'.",
        "            li_enh_object->activate(",
        "              EXPORTING run_dark = 'X'",
        "              CHANGING devclass = lv_enh_devclass",
        "                trkorr = lv_enh_trkorr ).",
        "          ELSE.",
        "            li_enh_object->reset_to_active_version(",
        "              CHANGING devclass = lv_enh_devclass",
        "                trkorr = lv_enh_trkorr ).",
        "          ENDIF.",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENH_STATE_CHANGE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.6'. RETURN.",
        "      ENDTRY.",
        "      ev_status = 'S'.",
        "      IF iv_object_type = 'ACTIVATE'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_ACTIVATED'.",
        "        ev_message = 'Enhancement implementation activated'.",
        "      ELSE.",
        "        ev_code = 'ENHANCEMENT_INACTIVE_VERSION_DISCARDED'.",
        "        ev_message = 'Inactive enhancement version discarded'.",
        "      ENDIF.",
        "      ev_version = '2.6'. RETURN.",
        "    WHEN 'DELETE_ENHANCEMENT_IMPLEMENTATION'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_ENHANCEMENT_REQUIRED'.",
        "        ev_message = 'Only Z or Y enhancements are writable'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      IF ls_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Enhancement belongs to another package'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name run_dark = 'X'",
        "            lock = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          li_enh_object->delete(",
        "            EXPORTING nevertheless_delete = 'X' run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_DELETE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.5'. RETURN.",
        "      ENDTRY.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'. ev_code = 'ENHANCEMENT_DELETE_PARTIAL'.",
        "        ev_message = 'Enhancement still exists after delete'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'ENHANCEMENT_IMPLEMENTATION_DELETED'.",
        "      ev_message = 'Enhancement implementation deleted'.",
        "      ev_version = '2.5'. RETURN.",
        "    WHEN 'MANAGE_CLASSIC_BADI_IMPLEMENTATION'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' )",
        "         OR ( iv_object_type <> 'CREATE'",
        "           AND iv_object_type <> 'ACTIVATE'",
        "           AND iv_object_type <> 'DEACTIVATE'",
        "           AND iv_object_type <> 'DELETE' ).",
        "        ev_status = 'E'. ev_code = 'CLASSIC_BADI_INPUT_INVALID'.",
        "        ev_message = 'Customer implementation and action required'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR: ls_classic_impl, lv_classic_action.",
        "      REFRESH: lt_classic_filters, lt_classic_methods,",
        "        lt_classic_protocol.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Classic BAdI payload index invalid'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        TRANSLATE lv_payload_property TO UPPER CASE.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        CASE lv_payload_kind.",
        "          WHEN 'M'.",
        "            CASE lv_payload_property.",
        "              WHEN 'ACTION'.",
        "                lv_classic_action = lv_payload_value.",
        "              WHEN 'DEFINITION_NAME'.",
        "                ls_classic_impl-exit_name = lv_payload_value.",
        "              WHEN 'INTERFACE_NAME'.",
        "                ls_classic_impl-inter_name = lv_payload_value.",
        "              WHEN 'IMPLEMENTATION_CLASS'.",
        "                ls_classic_impl-imp_class = lv_payload_value.",
        "              WHEN OTHERS.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Classic BAdI property invalid'.",
        "                ev_version = '2.5'. RETURN.",
        "            ENDCASE.",
        "          WHEN 'F'.",
        "            DESCRIBE TABLE lt_classic_filters",
        "              LINES lv_enh_row_count.",
        "            WHILE lv_enh_row_count < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_classic_filters.",
        "              ADD 1 TO lv_enh_row_count.",
        "            ENDWHILE.",
        "            READ TABLE lt_classic_filters",
        "              ASSIGNING <ls_classic_filter>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_classic_filter>",
        "              TO <lv_payload_component>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'.",
        "              ev_code = 'FILTER_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown Classic BAdI filter field'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            <lv_payload_component> = lv_payload_value.",
        "          WHEN 'N'.",
        "            IF lv_payload_property <> 'METHOD_NAME'.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Classic BAdI method name required'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            DESCRIBE TABLE lt_classic_methods",
        "              LINES lv_enh_row_count.",
        "            WHILE lv_enh_row_count < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_classic_methods.",
        "              ADD 1 TO lv_enh_row_count.",
        "            ENDWHILE.",
        "            READ TABLE lt_classic_methods",
        "              ASSIGNING <ls_classic_method>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT 'METHODNAME'",
        "              OF STRUCTURE <ls_classic_method>",
        "              TO <lv_payload_component>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Method structure unavailable'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            <lv_payload_component> = lv_payload_value.",
        "          WHEN 'S'.",
        "            READ TABLE lt_classic_methods",
        "              ASSIGNING <ls_classic_method>",
        "              INDEX lv_payload_index.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Method source precedes method name'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            ASSIGN COMPONENT 'SOURCE'",
        "              OF STRUCTURE <ls_classic_method>",
        "              TO <lt_classic_source>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Method source structure unavailable'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            APPEND lv_payload_value TO <lt_classic_source>.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Unexpected Classic BAdI payload row'.",
        "            ev_version = '2.5'. RETURN.",
        "        ENDCASE.",
        "      ENDLOOP.",
        "      IF lv_classic_action <> iv_object_type.",
        "        ev_status = 'E'. ev_code = 'ACTION_CONFLICT'.",
        "        ev_message = 'Classic BAdI action payload conflicts'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      ls_classic_impl-imp_name = iv_object_name.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'SXCI'",
        "          AND obj_name = iv_object_name.",
        "      IF iv_object_type = 'CREATE'.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'CLASSIC_BADI_IMPLEMENTATION_EXISTS'.",
        "          ev_message = 'Classic BAdI implementation exists'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        IF ls_classic_impl-exit_name IS INITIAL",
        "           OR ls_classic_impl-inter_name IS INITIAL",
        "           OR ls_classic_impl-imp_class IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'CLASSIC_BADI_CREATE_INPUT_REQUIRED'.",
        "          ev_message = 'Definition interface and class required'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "      ELSE.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'CLASSIC_BADI_IMPLEMENTATION_NOT_FOUND'.",
        "          ev_message = 'Classic BAdI implementation not found'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        IF ls_tadir-devclass <> iv_package.",
        "          ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "          ev_message = 'Implementation belongs to another package'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      lv_classic_language = sy-langu.",
        "      IF iv_object_type = 'CREATE'.",
        "        CALL FUNCTION 'SXO_IMPL_CREATE'",
        "          EXPORTING impl = ls_classic_impl active = 'X'",
        "          CHANGING mast_langu = lv_classic_language",
        "            filters = lt_classic_filters",
        "            korrnum = lv_enh_trkorr",
        "            devclass = lv_enh_devclass",
        "            method_implements = lt_classic_methods",
        "          EXCEPTIONS OTHERS = 1.",
        "      ELSEIF iv_object_type = 'ACTIVATE'.",
        "        CALL FUNCTION 'SXO_IMPL_ACTIVE'",
        "          EXPORTING imp_name = iv_object_name no_dialog = 'X'",
        "          CHANGING protocol = lt_classic_protocol",
        "          EXCEPTIONS OTHERS = 1.",
        "      ELSEIF iv_object_type = 'DEACTIVATE'.",
        "        CALL FUNCTION 'SXO_IMPL_DACTVE'",
        "          EXPORTING imp_name = iv_object_name no_dialog = 'X'",
        "          CHANGING protocol = lt_classic_protocol",
        "          EXCEPTIONS OTHERS = 1.",
        "      ELSE.",
        "        CALL FUNCTION 'SXO_IMPL_DELETE'",
        "          EXPORTING imp_name = iv_object_name no_dialog = 'X'",
        "          CHANGING korr_num = lv_enh_trkorr",
        "          EXCEPTIONS OTHERS = 1.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'CLASSIC_BADI_CHANGE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'CLASSIC_BADI_IMPLEMENTATION_CHANGED'.",
        "      ev_message = 'Classic BAdI implementation changed'.",
        "      ev_version = '2.5'. RETURN.",
        "    WHEN 'READ_CLASSIC_BADI_DEFINITION'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CLASSIC_BADI_DEFINITION_REQUIRED'.",
        "        ev_message = 'Exact Classic BAdI definition name required'.",
        "        ev_version = '2.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_sxs_attr, ls_sxs_attrt,",
        "        lv_badi_implementation, lv_badi_assignment_index,",
        "        lv_badi_class_index.",
        "      REFRESH: lt_sxs_inter, lt_sxc_exit, it_source.",
        "      SELECT SINGLE * FROM sxs_attr INTO ls_sxs_attr",
        "        WHERE exit_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CLASSIC_BADI_DEFINITION_NOT_FOUND'.",
        "        ev_message = 'Classic BAdI definition does not exist'.",
        "        ev_version = '2.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM sxs_attrt INTO ls_sxs_attrt",
        "        WHERE exit_name = iv_object_name",
        "          AND sprsl = sy-langu.",
        "      SELECT * FROM sxs_inter INTO TABLE lt_sxs_inter",
        "        WHERE exit_name = iv_object_name.",
        "      SORT lt_sxs_inter BY inter_name.",
        "      SELECT * FROM sxc_exit INTO TABLE lt_sxc_exit",
        "        WHERE exit_name = iv_object_name.",
        "      SORT lt_sxc_exit BY imp_name flt_val.",
        "      add_repo_payload 'M' '1' 'NAME' iv_object_name.",
        "      add_repo_alias 'M' '1' 'DESCRIPTION' 'TEXT'",
        "        ls_sxs_attrt.",
        "      add_repo_alias 'M' '1' 'VERSION' 'VERSION'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'FILTER_TYPE' 'FLT_TYPE'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'FILTER_EXTENSION' 'FLT_EXT'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MULTIPLE_USE' 'MLTP_USE'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'PACKAGE' 'DEVCLASS'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MASTER_LANGUAGE' 'MST_LANG'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'DEFAULT_CLASS' 'DEF_CLNAME'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'EXAMPLE_CLASS' 'EXM_CLNAME'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'CHECK_CLASS' 'COC_CLNAME'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'INTERNAL' 'INTERNAL'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MIGRATION_ENHANCEMENT_SPOT'",
        "        'MIG_ENHSPOTNAME' ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MIGRATION_BADI_NAME'",
        "        'MIG_BADI_NAME' ls_sxs_attr.",
        "      LOOP AT lt_sxs_inter INTO ls_sxs_inter.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_alias 'I' lv_payload_index 'INTERFACE_NAME'",
        "          'INTER_NAME' ls_sxs_inter.",
        "      ENDLOOP.",
        "      LOOP AT lt_sxc_exit INTO ls_sxc_exit.",
        "        ADD 1 TO lv_badi_assignment_index.",
        "        lv_payload_index = lv_badi_assignment_index.",
        "        IF lv_badi_implementation <> ls_sxc_exit-imp_name.",
        "          lv_badi_implementation = ls_sxc_exit-imp_name.",
        "          CLEAR: ls_sxc_attr, ls_sxc_attrt.",
        "          SELECT SINGLE * FROM sxc_attr INTO ls_sxc_attr",
        "            WHERE imp_name = lv_badi_implementation.",
        "          SELECT SINGLE * FROM sxc_attrt INTO ls_sxc_attrt",
        "            WHERE imp_name = lv_badi_implementation",
        "              AND sprsl = sy-langu.",
        "          REFRESH lt_sxc_class.",
        "          SELECT * FROM sxc_class INTO TABLE lt_sxc_class",
        "            WHERE imp_name = lv_badi_implementation.",
        "          SORT lt_sxc_class BY inter_name imp_class.",
        "          CLEAR ls_tadir.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'SXCI'",
        "              AND obj_name = lv_badi_implementation.",
        "          LOOP AT lt_sxc_class INTO ls_sxc_class.",
        "            ADD 1 TO lv_badi_class_index.",
        "            add_repo_alias 'C' lv_badi_class_index",
        "              'IMPLEMENTATION_NAME' 'IMP_NAME' ls_sxc_class.",
        "            add_repo_alias 'C' lv_badi_class_index",
        "              'INTERFACE_NAME' 'INTER_NAME' ls_sxc_class.",
        "            add_repo_alias 'C' lv_badi_class_index",
        "              'IMPLEMENTATION_CLASS' 'IMP_CLASS' ls_sxc_class.",
        "          ENDLOOP.",
        "        ENDIF.",
        "        add_repo_alias 'A' lv_payload_index",
        "          'IMPLEMENTATION_NAME' 'IMP_NAME' ls_sxc_exit.",
        "        add_repo_alias 'A' lv_payload_index 'FILTER_VALUE'",
        "          'FLT_VAL' ls_sxc_exit.",
        "        add_repo_alias 'A' lv_payload_index 'ACTIVE' 'ACTIVE'",
        "          ls_sxc_attr.",
        "        add_repo_alias 'A' lv_payload_index 'DESCRIPTION' 'TEXT'",
        "          ls_sxc_attrt.",
        "        add_repo_alias 'A' lv_payload_index 'VERSION' 'VERSION'",
        "          ls_sxc_attr.",
        "        add_repo_alias 'A' lv_payload_index 'MASTER_LANGUAGE'",
        "          'MST_LANG' ls_sxc_attr.",
        "        add_repo_alias 'A' lv_payload_index 'LAYER' 'LAYER'",
        "          ls_sxc_attr.",
        "        add_repo_payload 'A' lv_payload_index 'PACKAGE'",
        "          ls_tadir-devclass.",
        "        add_repo_alias 'A' lv_payload_index",
        "          'MIGRATION_ENHANCEMENT' 'MIG_ENHNAME' ls_sxc_attr.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'CLASSIC_BADI_DEFINITION_READ'.",
        "      ev_message = 'Classic BAdI definition and implementations read'.",
        "      ev_version = '2.4'.",
        "      RETURN.",
        "    WHEN 'READ_BTE_CONFIGURATION'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_type <> 'E' AND iv_object_type <> 'P' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'BTE_CONFIGURATION_INPUT_REQUIRED'.",
        "        ev_message = 'Exact BTE identifier and kind required'.",
        "        ev_version = '2.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_tbe31, lt_tbe34, lt_tps31, lt_tps34, it_source.",
        "      CLEAR: ls_tbe01, ls_tbe01t, ls_tps01, ls_tps01t.",
        "      IF iv_object_type = 'E'.",
        "        SELECT SINGLE * FROM tbe01 INTO ls_tbe01",
        "          WHERE event = iv_object_name.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'BTE_DEFINITION_NOT_FOUND'.",
        "          ev_message = 'BTE Event definition does not exist'.",
        "          ev_version = '2.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        SELECT SINGLE * FROM tbe01t INTO ls_tbe01t",
        "          WHERE event = iv_object_name AND spras = sy-langu.",
        "        SELECT * FROM tbe31 INTO TABLE lt_tbe31",
        "          WHERE event = iv_object_name.",
        "        SELECT * FROM tbe34 INTO TABLE lt_tbe34",
        "          WHERE event = iv_object_name.",
        "        add_repo_payload 'M' '1' 'IDENTIFIER' iv_object_name.",
        "        add_repo_payload 'M' '1' 'KIND' 'E'.",
        "        add_repo_alias 'M' '1' 'DESCRIPTION' 'TEXT1' ls_tbe01t.",
        "        LOOP AT lt_tbe31 INTO ls_tbe31.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'S' lv_payload_index 'COUNTRY' 'LAND' ls_tbe31.",
        "          add_repo_alias 'S' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tbe31.",
        "          add_repo_alias 'S' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tbe31.",
        "          add_bte_application 'S' lv_payload_index ls_tbe31.",
        "        ENDLOOP.",
        "        LOOP AT lt_tbe34 INTO ls_tbe34.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'C' lv_payload_index 'COUNTRY' 'LAND' ls_tbe34.",
        "          add_repo_alias 'C' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tbe34.",
        "          add_repo_alias 'C' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tbe34.",
        "          add_repo_alias 'C' lv_payload_index 'PRODUCT'",
        "            'PRDKT' ls_tbe34.",
        "          add_bte_application 'C' lv_payload_index ls_tbe34.",
        "          add_bte_product 'C' lv_payload_index ls_tbe34.",
        "        ENDLOOP.",
        "      ELSE.",
        "        SELECT SINGLE * FROM tps01 INTO ls_tps01",
        "          WHERE procs = iv_object_name.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'BTE_DEFINITION_NOT_FOUND'.",
        "          ev_message = 'BTE Process definition does not exist'.",
        "          ev_version = '2.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        SELECT SINGLE * FROM tps01t INTO ls_tps01t",
        "          WHERE procs = iv_object_name AND spras = sy-langu.",
        "        SELECT * FROM tps31 INTO TABLE lt_tps31",
        "          WHERE procs = iv_object_name.",
        "        SELECT * FROM tps34 INTO TABLE lt_tps34",
        "          WHERE procs = iv_object_name.",
        "        add_repo_payload 'M' '1' 'IDENTIFIER' iv_object_name.",
        "        add_repo_payload 'M' '1' 'KIND' 'P'.",
        "        add_repo_alias 'M' '1' 'DESCRIPTION' 'TEXT1' ls_tps01t.",
        "        LOOP AT lt_tps31 INTO ls_tps31.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'S' lv_payload_index 'COUNTRY' 'LAND' ls_tps31.",
        "          add_repo_alias 'S' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tps31.",
        "          add_repo_alias 'S' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tps31.",
        "          add_bte_application 'S' lv_payload_index ls_tps31.",
        "        ENDLOOP.",
        "        LOOP AT lt_tps34 INTO ls_tps34.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'C' lv_payload_index 'COUNTRY' 'LAND' ls_tps34.",
        "          add_repo_alias 'C' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tps34.",
        "          add_repo_alias 'C' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tps34.",
        "          add_repo_alias 'C' lv_payload_index 'PRODUCT'",
        "            'PRDKT' ls_tps34.",
        "          add_bte_application 'C' lv_payload_index ls_tps34.",
        "          add_bte_product 'C' lv_payload_index ls_tps34.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'BTE_CONFIGURATION_READ'.",
        "      ev_message = 'BTE definition and configured handlers read'.",
        "      ev_version = '2.3'.",
        "      RETURN.",
        "    WHEN 'READ_CUSTOMER_EXIT_DEFINITION'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_DEFINITION_REQUIRED'.",
        "        ev_message = 'Exact SMOD enhancement name is required'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT * FROM modsap INTO TABLE lt_modsap",
        "        WHERE name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_DEFINITION_NOT_FOUND'.",
        "        ev_message = 'SMOD enhancement definition does not exist'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM modsapt INTO ls_modsapt",
        "        WHERE name = iv_object_name AND sprsl = sy-langu.",
        "      SORT lt_modsap BY typ member.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NAME' iv_object_name.",
        "      add_repo_payload 'M' '1' 'DESCRIPTION'",
        "        ls_modsapt-modtext.",
        "      LOOP AT lt_modsap INTO ls_modsap.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'C' lv_payload_index 'TYPE'",
        "          ls_modsap-typ.",
        "        add_repo_payload 'C' lv_payload_index 'MEMBER'",
        "          ls_modsap-member.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'CUSTOMER_EXIT_DEFINITION_READ'.",
        "      ev_message = 'SMOD enhancement definition read'.",
        "      ev_version = '2.2'.",
        "      RETURN.",
        "    WHEN 'READ_CUSTOMER_EXIT_PROJECT'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_PROJECT_REQUIRED'.",
        "        ev_message = 'Exact CMOD project name is required'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM modattr INTO ls_modattr",
        "        WHERE name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_PROJECT_NOT_FOUND'.",
        "        ev_message = 'CMOD enhancement project does not exist'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT * FROM modact INTO TABLE lt_modact",
        "        WHERE name = iv_object_name AND typ = space.",
        "      SORT lt_modact BY member.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'CMOD'",
        "          AND obj_name = iv_object_name.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NAME' ls_modattr-name.",
        "      add_repo_payload 'M' '1' 'STATUS' ls_modattr-status.",
        "      add_repo_payload 'M' '1' 'CHANGED_BY' ls_modattr-anam.",
        "      add_repo_payload 'M' '1' 'CHANGED_ON' ls_modattr-adat.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      LOOP AT lt_modact INTO ls_modact.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'A' lv_payload_index 'TYPE'",
        "          ls_modact-typ.",
        "        add_repo_payload 'A' lv_payload_index 'MEMBER'",
        "          ls_modact-member.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'CUSTOMER_EXIT_PROJECT_READ'.",
        "      ev_message = 'CMOD enhancement project read'.",
        "      ev_version = '2.2'.",
        "      RETURN.",
        "    WHEN 'CREATE_FUNCTION_GROUP'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_INPUT_REQUIRED'.",
        "        ev_message = 'Transportable package request required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_EXISTS'.",
        "        ev_message = 'Function group already exists'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_function_pool = iv_object_name.",
        "      lv_short_text = iv_description.",
        "      lv_recorded_request = ls_task-trkorr.",
        "      CLEAR lv_group_corrnum.",
        "      CALL FUNCTION 'RS_FUNCTION_POOL_INSERT'",
        "        EXPORTING function_pool = lv_function_pool",
        "          short_text = lv_short_text",
        "          responsible = sy-uname",
        "          devclass = iv_package",
        "          corrnum = lv_recorded_request",
        "          suppress_corr_check = space",
        "        IMPORTING corrnum = lv_group_corrnum",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ROLLBACK WORK.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "            AND obj_name = iv_object_name.",
        "        ev_status = 'E'.",
        "        IF sy-subrc = 0.",
        "          ev_code = 'CREATE_PARTIAL'.",
        "          ev_message = 'Function group exists after failure'.",
        "        ELSE.",
        "          ev_code = 'FUNCTION_GROUP_CREATE_FAILED'.",
        "        ENDIF.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_object_name",
        "          AND devclass = iv_package.",
        "      SELECT SINGLE * FROM tlibg INTO ls_tlibg",
        "        WHERE area = iv_object_name.",
        "      CONCATENATE 'SAPL' iv_object_name",
        "        INTO lv_group_program.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = lv_group_program.",
        "      IF ls_tadir-obj_name IS INITIAL",
        "         OR ls_tlibg-area IS INITIAL",
        "         OR ls_trdir-name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_PARTIAL'.",
        "        ev_message = 'Function group verification failed'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_PARTIAL'.",
        "        ev_message = 'Function group transport missing'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        ls_request-trkorr.",
        "      add_repo_payload 'M' '1' 'TASK' ls_task-trkorr.",
        "      add_repo_payload 'M' '1' 'ACTIVE' 'X'.",
        "      add_repo_payload 'M' '1' 'GENERATED' 'X'.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_GROUP_CREATED'.",
        "      ev_message = 'Function group created and verified'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    WHEN 'CREATE_FUNCTION_INCLUDE'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_INPUT_REQUIRED'.",
        "        ev_message = 'Package request and source are required'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE 'L' iv_program '*' INTO lv_group_program.",
        "      IF iv_object_name NP lv_group_program.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_NAME_INVALID'.",
        "        ev_message = 'Include must belong to the function group'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_NOT_FOUND'.",
        "        ev_message = 'Parent function group package mismatch'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_EXISTS'.",
        "        ev_message = 'Function group Include already exists'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_program.",
        "      IF sy-subrc <> 0.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_request-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'FUGR'",
        "            AND obj_name = iv_program.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_TRANSPORT_MISMATCH'.",
        "        ev_message = 'Parent function group is not in the request'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      INSERT REPORT iv_object_name FROM it_source",
        "        PROGRAM TYPE 'I'.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_CREATE_FAILED'.",
        "        ev_message = 'Function group Include source write failed'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_object_name AND subc = 'I'.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_VERIFY_FAILED'.",
        "        ev_message = 'Created Include metadata is inconsistent'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'REQUEST' ls_task-trkorr.",
        "      add_repo_payload 'M' '1' 'PARENT' iv_program.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_INCLUDE_CREATED'.",
        "      ev_message = 'Function group Include created and verified'.",
        "      ev_version = '1.7'.",
        "      RETURN.",
        "    WHEN 'READ_FUNCTION_INTERFACE'.",
        "      lv_function_name = iv_object_name.",
        "      REFRESH lt_fm_long_source.",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables,",
        "        lt_fm_exceptions, lt_fm_documentation,",
        "        lt_fm_source.",
        "      CLEAR: lv_global_flag, lv_remote_call,",
        "        lv_update_task, lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_import",
        "          changing_parameter = lt_fm_changing",
        "          export_parameter = lt_fm_export",
        "          tables_parameter = lt_fm_tables",
        "          exception_list = lt_fm_exceptions",
        "          documentation = lt_fm_documentation",
        "          source = lt_fm_source",
        "        CHANGING new_source = lt_fm_long_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF lt_fm_long_source[] IS NOT INITIAL.",
        "        IF iv_object_type <> 'SRC1'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SOURCE_CLIENT_UPGRADE_REQUIRED'.",
        "          ev_message = 'Long source requires SRC1 client'.",
        "          ev_version = '2.1'. RETURN.",
        "        ENDIF.",
        "        LOOP AT lt_fm_long_source INTO lv_fm_long_line.",
        "          IF strlen( lv_fm_long_line ) > 255.",
        "            ev_status = 'E'.",
        "            ev_code = 'SOURCE_LINE_TOO_LONG'.",
        "            ev_message = 'Source line exceeds 255 characters'.",
        "            ev_version = '2.1'. RETURN.",
        "          ENDIF.",
        "        ENDLOOP.",
        "* The short-source table may contain only a partial read.",
        "        REFRESH lt_fm_source.",
        "      ENDIF.",
        "      emit_fm_payload.",
        "      IF lt_fm_long_source[] IS NOT INITIAL.",
        "        add_repo_payload 'M' '1' 'SOURCE_FORMAT' 'CHUNKS_V1'.",
        "        lv_fm_source_length = lines( lt_fm_long_source ).",
        "        add_repo_payload 'M' '1' 'SOURCE_LINES'",
        "          lv_fm_source_length.",
        "        LOOP AT lt_fm_long_source INTO lv_fm_long_line.",
        "          lv_payload_index = sy-tabix.",
        "          lv_fm_source_length = strlen( lv_fm_long_line ).",
        "          add_repo_payload 'S' lv_payload_index 'LENGTH'",
        "            lv_fm_source_length.",
        "          CLEAR: lv_fm_source_offset, lv_fm_chunk_number.",
        "          WHILE lv_fm_source_offset < lv_fm_source_length.",
        "            lv_fm_chunk_length = lv_fm_source_length -",
        "              lv_fm_source_offset.",
        "            IF lv_fm_chunk_length > 60.",
        "              lv_fm_chunk_length = 60.",
        "            ENDIF.",
        "            ADD 1 TO lv_fm_chunk_number.",
        "            lv_fm_chunk_number_text = lv_fm_chunk_number.",
        "            CONDENSE lv_fm_chunk_number_text NO-GAPS.",
        "            CONCATENATE 'PART' lv_fm_chunk_number_text",
        "              INTO lv_fm_chunk_property.",
        "            lv_fm_source_chunk =",
        "              lv_fm_long_line+lv_fm_source_offset(lv_fm_chunk_length).",
        "            add_repo_payload 'S' lv_payload_index",
        "              lv_fm_chunk_property lv_fm_source_chunk.",
        "            ADD lv_fm_chunk_length TO lv_fm_source_offset.",
        "          ENDWHILE.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_INTERFACE_READ'.",
        "      ev_message = 'Function interface read successfully'.",
        "      ev_version = '2.1'.",
        "      RETURN.",
        "    WHEN 'CREATE_FUNCTION_MODULE'.",
        "      lv_function_name = iv_object_name.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "         AND iv_object_name(1) <> 'Y' )",
        "         OR iv_program IS INITIAL",
        "         OR ( iv_program(1) <> 'Z'",
        "         AND iv_program(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Customer function group package request required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_PACKAGE_MISMATCH'.",
        "        ev_message = 'Function group package does not match'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "        WHERE funcname = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_EXISTS'.",
        "        ev_message = 'Function module already exists'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables,",
        "        lt_fm_exceptions, lt_fm_documentation,",
        "        lt_fm_source.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "          ev_message = 'Function payload index is invalid'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_property = 'PASSVALUE'",
        "           AND lv_payload_kind <> 'T'.",
        "          lv_payload_property = 'REFERENCE'.",
        "          IF lv_payload_value = 'X'.",
        "            CLEAR lv_payload_value.",
        "          ELSE.",
        "            lv_payload_value = 'X'.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "          ev_message = 'Serialized function payload is invalid'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        IF lv_payload_property = 'TEXT'",
        "           AND lv_payload_kind CA 'IECT'.",
        "          CLEAR ls_fm_documentation.",
        "          CASE lv_payload_kind.",
        "            WHEN 'I'.",
        "              READ TABLE lt_fm_import INTO ls_fm_import",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_import-parameter.",
        "            WHEN 'E'.",
        "              READ TABLE lt_fm_export INTO ls_fm_export",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_export-parameter.",
        "            WHEN 'C'.",
        "              READ TABLE lt_fm_changing INTO ls_fm_changing",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_changing-parameter.",
        "            WHEN 'T'.",
        "              READ TABLE lt_fm_tables INTO ls_fm_table",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_table-parameter.",
        "          ENDCASE.",
        "          IF sy-subrc <> 0",
        "             OR ls_fm_documentation-parameter IS INITIAL.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "            ev_message = 'Parameter text precedes its name'.",
        "            ev_version = '2.0'.",
        "            RETURN.",
        "          ENDIF.",
        "          ls_fm_documentation-kind = 'P'.",
        "          ls_fm_documentation-stext = lv_payload_value.",
        "          ls_fm_documentation-index = lv_payload_index.",
        "          APPEND ls_fm_documentation",
        "            TO lt_fm_documentation.",
        "          CONTINUE.",
        "        ENDIF.",
        "        CASE lv_payload_kind.",
        "          WHEN 'I'.",
        "            WHILE lines( lt_fm_import ) < lv_payload_index.",
        "              CLEAR ls_fm_import.",
        "              APPEND ls_fm_import TO lt_fm_import.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_import ASSIGNING <ls_fm_import>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_import>",
        "              TO <lv_payload_component>.",
        "          WHEN 'E'.",
        "            WHILE lines( lt_fm_export ) < lv_payload_index.",
        "              CLEAR ls_fm_export.",
        "              APPEND ls_fm_export TO lt_fm_export.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_export ASSIGNING <ls_fm_export>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_export>",
        "              TO <lv_payload_component>.",
        "          WHEN 'C'.",
        "            WHILE lines( lt_fm_changing ) < lv_payload_index.",
        "              CLEAR ls_fm_changing.",
        "              APPEND ls_fm_changing TO lt_fm_changing.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_changing",
        "              ASSIGNING <ls_fm_changing>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_changing>",
        "              TO <lv_payload_component>.",
        "          WHEN 'T'.",
        "            WHILE lines( lt_fm_tables ) < lv_payload_index.",
        "              CLEAR ls_fm_table.",
        "              APPEND ls_fm_table TO lt_fm_tables.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_tables ASSIGNING <ls_fm_table>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_table>",
        "              TO <lv_payload_component>.",
        "          WHEN 'X'.",
        "            WHILE lines( lt_fm_exceptions )",
        "              < lv_payload_index.",
        "              CLEAR ls_fm_exception.",
        "              APPEND ls_fm_exception TO lt_fm_exceptions.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_exceptions",
        "              ASSIGNING <ls_fm_exception>",
        "              INDEX lv_payload_index.",
        "            IF lv_payload_property = 'TEXT'.",
        "              CLEAR ls_fm_documentation.",
        "              ls_fm_documentation-parameter =",
        "                <ls_fm_exception>-exception.",
        "              ls_fm_documentation-kind = 'X'.",
        "              ls_fm_documentation-stext = lv_payload_value.",
        "              ls_fm_documentation-index = lv_payload_index.",
        "              APPEND ls_fm_documentation",
        "                TO lt_fm_documentation.",
        "              CONTINUE.",
        "            ENDIF.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_exception>",
        "              TO <lv_payload_component>.",
        "          WHEN 'S'.",
        "            IF lv_payload_property <> 'LINE'.",
        "              ev_status = 'E'.",
        "              ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown source payload property'.",
        "              ev_version = '1.3'.",
        "              RETURN.",
        "            ENDIF.",
        "            CLEAR ls_fm_source.",
        "            ls_fm_source-line = lv_payload_value.",
        "            APPEND ls_fm_source TO lt_fm_source.",
        "            CONTINUE.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "            ev_message = 'Unknown function payload row type'.",
        "            ev_version = '1.3'.",
        "            RETURN.",
        "        ENDCASE.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown function payload property'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      IF lt_fm_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_REQUIRED'.",
        "        ev_message = 'Function source is required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_function_pool = iv_program.",
        "      lv_short_text = iv_description.",
        "      lv_remote_call = iv_object_type.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_INSERT'",
        "        EXPORTING funcname = lv_function_name",
        "          function_pool = lv_function_pool",
        "          remote_call = lv_remote_call",
        "          short_text = lv_short_text",
        "          corrnum = iv_request",
        "        TABLES import_parameter = lt_fm_import",
        "          changing_parameter = lt_fm_changing",
        "          export_parameter = lt_fm_export",
        "          tables_parameter = lt_fm_tables",
        "          exception_list = lt_fm_exceptions",
        "          parameter_docu = lt_fm_documentation",
        "          source = lt_fm_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "          WHERE funcname = iv_object_name.",
        "        ev_status = 'E'.",
        "        IF sy-subrc = 0.",
        "          ev_code = 'CREATE_PARTIAL'.",
        "          ev_message = 'Function exists after failed create'.",
        "        ELSE.",
        "          ev_code = 'FUNCTION_CREATE_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "        ENDIF.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables,",
        "        lt_fm_exceptions, lt_fm_documentation,",
        "        lt_fm_source.",
        "      CLEAR: lv_global_flag, lv_remote_call,",
        "        lv_update_task, lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_import",
        "          changing_parameter = lt_fm_changing",
        "          export_parameter = lt_fm_export",
        "          tables_parameter = lt_fm_tables",
        "          exception_list = lt_fm_exceptions",
        "          documentation = lt_fm_documentation",
        "          source = lt_fm_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_PARTIAL'.",
        "        ev_message = 'Function created but re-read failed'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      emit_fm_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_MODULE_CREATED'.",
        "      ev_message = 'Function created and verified'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    WHEN 'PATCH_FUNCTION_INTERFACE'.",
        "      lv_function_name = iv_object_name.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "         AND iv_object_name(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_INPUT_REQUIRED'.",
        "        ev_message = 'Function package and request are required'.",
        "        ev_version = '2.0'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "        WHERE funcname = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_NOT_FOUND'.",
        "        ev_message = 'Function module does not exist'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      lv_function_pool = ls_tfdir-pname+4.",
        "      IF lv_function_pool IS INITIAL",
        "         OR ( lv_function_pool(1) <> 'Z'",
        "         AND lv_function_pool(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_FUNCTION_REQUIRED'.",
        "        ev_message = 'Only customer function groups are valid'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = lv_function_pool",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_PACKAGE_MISMATCH'.",
        "        ev_message = 'Function group package does not match'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task was not found'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open user workbench task is required'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = lv_function_pool.",
        "      IF sy-subrc <> 0.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_request-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'FUGR'",
        "            AND obj_name = lv_function_pool.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_TRANSPORT_MISMATCH'.",
        "        ev_message = 'Function group is not in the request'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_fm_expected_payload,",
        "        lt_fm_desired_payload.",
        "      LOOP AT it_source INTO ls_source.",
        "        IF ls_source-line(1) CA 'miectxs'.",
        "          ls_fm_expected_line = ls_source.",
        "          TRANSLATE ls_fm_expected_line-line(1)",
        "            TO UPPER CASE.",
        "          APPEND ls_fm_expected_line",
        "            TO lt_fm_expected_payload.",
        "        ELSE.",
        "          APPEND ls_source TO lt_fm_desired_payload.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lt_fm_expected_payload[] IS INITIAL",
        "         OR lt_fm_desired_payload[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "        ev_message = 'Both function snapshots are required'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'ENQUEUE_ESFUNCTION'",
        "        EXPORTING funcname = lv_function_name",
        "          mode_tfdir = lv_fm_lock_mode",
        "        EXCEPTIONS foreign_lock = 1 OTHERS = 2.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_LOCKED'.",
        "        ev_message = 'Function module is locked'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_fm_current_import, lt_fm_current_export,",
        "        lt_fm_current_changing, lt_fm_current_tables,",
        "        lt_fm_current_exceptions,",
        "        lt_fm_current_documentation,",
        "        lt_fm_current_source.",
        "      CLEAR: lv_global_flag, lv_remote_call, lv_update_task,",
        "        lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_current_import",
        "          changing_parameter = lt_fm_current_changing",
        "          export_parameter = lt_fm_current_export",
        "          tables_parameter = lt_fm_current_tables",
        "          exception_list = lt_fm_current_exceptions",
        "          documentation = lt_fm_current_documentation",
        "          source = lt_fm_current_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_READ_FAILED'.",
        "        ev_message = 'Locked function could not be read'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      lt_fm_import[] = lt_fm_current_import[].",
        "      lt_fm_export[] = lt_fm_current_export[].",
        "      lt_fm_changing[] = lt_fm_current_changing[].",
        "      lt_fm_tables[] = lt_fm_current_tables[].",
        "      lt_fm_exceptions[] = lt_fm_current_exceptions[].",
        "      lt_fm_documentation[] = lt_fm_current_documentation[].",
        "      lt_fm_source[] = lt_fm_current_source[].",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables, lt_fm_exceptions,",
        "        lt_fm_documentation.",
        "      LOOP AT lt_fm_desired_payload INTO ls_source.",
        "        CLEAR: lv_fm_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_fm_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "          ev_message = 'Function payload index is invalid'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_property = 'PASSVALUE'",
        "           AND lv_fm_payload_kind <> 'T'.",
        "          lv_payload_property = 'REFERENCE'.",
        "          IF lv_payload_value = 'X'.",
        "            CLEAR lv_payload_value.",
        "          ELSE.",
        "            lv_payload_value = 'X'.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "          ev_message = 'Function payload is invalid'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        IF lv_payload_property = 'TEXT'",
        "           AND lv_fm_payload_kind CA 'IECT'.",
        "          CLEAR ls_fm_documentation.",
        "          CASE lv_fm_payload_kind.",
        "            WHEN 'I'.",
        "              READ TABLE lt_fm_import INTO ls_fm_import",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_import-parameter.",
        "            WHEN 'E'.",
        "              READ TABLE lt_fm_export INTO ls_fm_export",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_export-parameter.",
        "            WHEN 'C'.",
        "              READ TABLE lt_fm_changing INTO ls_fm_changing",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_changing-parameter.",
        "            WHEN 'T'.",
        "              READ TABLE lt_fm_tables INTO ls_fm_table",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_table-parameter.",
        "          ENDCASE.",
        "          IF sy-subrc <> 0",
        "             OR ls_fm_documentation-parameter IS INITIAL.",
        "            CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "              EXPORTING funcname = lv_function_name.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "            ev_message = 'Parameter text precedes its name'.",
        "            ev_version = '2.0'. RETURN.",
        "          ENDIF.",
        "          ls_fm_documentation-kind = 'P'.",
        "          ls_fm_documentation-stext = lv_payload_value.",
        "          ls_fm_documentation-index = lv_payload_index.",
        "          APPEND ls_fm_documentation TO lt_fm_documentation.",
        "          CONTINUE.",
        "        ENDIF.",
        "        CASE lv_fm_payload_kind.",
        "          WHEN 'I'.",
        "            WHILE lines( lt_fm_import ) < lv_payload_index.",
        "              CLEAR ls_fm_import.",
        "              APPEND ls_fm_import TO lt_fm_import.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_import ASSIGNING <ls_fm_import>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_import>",
        "              TO <lv_payload_component>.",
        "          WHEN 'E'.",
        "            WHILE lines( lt_fm_export ) < lv_payload_index.",
        "              CLEAR ls_fm_export.",
        "              APPEND ls_fm_export TO lt_fm_export.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_export ASSIGNING <ls_fm_export>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_export>",
        "              TO <lv_payload_component>.",
        "          WHEN 'C'.",
        "            WHILE lines( lt_fm_changing ) < lv_payload_index.",
        "              CLEAR ls_fm_changing.",
        "              APPEND ls_fm_changing TO lt_fm_changing.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_changing",
        "              ASSIGNING <ls_fm_changing>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_changing>",
        "              TO <lv_payload_component>.",
        "          WHEN 'T'.",
        "            WHILE lines( lt_fm_tables ) < lv_payload_index.",
        "              CLEAR ls_fm_table.",
        "              APPEND ls_fm_table TO lt_fm_tables.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_tables ASSIGNING <ls_fm_table>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_table>",
        "              TO <lv_payload_component>.",
        "          WHEN 'X'.",
        "            WHILE lines( lt_fm_exceptions )",
        "              < lv_payload_index.",
        "              CLEAR ls_fm_exception.",
        "              APPEND ls_fm_exception TO lt_fm_exceptions.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_exceptions",
        "              ASSIGNING <ls_fm_exception>",
        "              INDEX lv_payload_index.",
        "            IF lv_payload_property = 'TEXT'.",
        "              CLEAR ls_fm_documentation.",
        "              ls_fm_documentation-parameter =",
        "                <ls_fm_exception>-exception.",
        "              ls_fm_documentation-kind = 'X'.",
        "              ls_fm_documentation-stext = lv_payload_value.",
        "              ls_fm_documentation-index = lv_payload_index.",
        "              APPEND ls_fm_documentation",
        "                TO lt_fm_documentation.",
        "              CONTINUE.",
        "            ENDIF.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_exception>",
        "              TO <lv_payload_component>.",
        "          WHEN 'S'.",
        "            IF lv_payload_property <> 'LINE'.",
        "              CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "                EXPORTING funcname = lv_function_name.",
        "              ev_status = 'E'.",
        "              ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown source payload property'.",
        "              ev_version = '2.0'. RETURN.",
        "            ENDIF.",
        "* Source rows describe the pre-ADT snapshot. Preserve the",
        "* active post-ADT source and verify it after doc update.",
        "            CONTINUE.",
        "          WHEN OTHERS.",
        "            CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "              EXPORTING funcname = lv_function_name.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "            ev_message = 'Unknown function payload row type'.",
        "            ev_version = '2.0'. RETURN.",
        "        ENDCASE.",
        "        IF sy-subrc <> 0.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown function payload property'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      IF lt_fm_source[] <> lt_fm_current_source[].",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_CHANGE_REJECTED'.",
        "        ev_message = 'Interface patch cannot change source'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      IF lt_fm_current_import[] <> lt_fm_import[]",
        "         OR lt_fm_current_export[] <> lt_fm_export[]",
        "         OR lt_fm_current_changing[] <> lt_fm_changing[]",
        "         OR lt_fm_current_tables[] <> lt_fm_tables[]",
        "         OR lt_fm_current_exceptions[] <> lt_fm_exceptions[].",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_ADT_PATCH_NOT_OBSERVED'.",
        "        ev_message = 'ADT interface does not match the request'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "* Preserve native cross-direction indices and row order.",
        "      lt_fm_requested_documentation[] = lt_fm_documentation[].",
        "      lt_fm_documentation[] = lt_fm_current_documentation[].",
        "      LOOP AT lt_fm_documentation ASSIGNING <ls_fm_documentation>.",
        "        READ TABLE lt_fm_requested_documentation",
        "          INTO ls_fm_documentation",
        "          WITH KEY parameter = <ls_fm_documentation>-parameter",
        "            kind = <ls_fm_documentation>-kind.",
        "        IF sy-subrc <> 0.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PATCH_DOCUMENTATION_MISMATCH'.",
        "          ev_message = 'Native parameter text missing in request'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        DELETE lt_fm_requested_documentation INDEX sy-tabix.",
        "        <ls_fm_documentation>-stext = ls_fm_documentation-stext.",
        "      ENDLOOP.",
        "      IF lt_fm_requested_documentation IS NOT INITIAL.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_DOCUMENTATION_MISMATCH'.",
        "        ev_message = 'Duplicate or unknown parameter text'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      PERFORM fu_modification_globals_init(SAPMS38L)",
        "        USING 'X' sy-langu.",
        "      PERFORM do_read_docu_r3_new(SAPMS38L)",
        "        TABLES lt_fm_current_documentation",
        "        USING lv_function_name.",
        "      PERFORM do_update_docu_r3_new(SAPMS38L)",
        "        TABLES lt_fm_documentation",
        "        USING lv_function_name.",
        "      COMMIT WORK AND WAIT.",
        "      CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "        EXPORTING funcname = lv_function_name.",
        "      REFRESH: lt_fm_current_import, lt_fm_current_export,",
        "        lt_fm_current_changing, lt_fm_current_tables,",
        "        lt_fm_current_exceptions,",
        "        lt_fm_current_documentation, lt_fm_current_source.",
        "      CLEAR: lv_global_flag, lv_remote_call, lv_update_task,",
        "        lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_current_import",
        "          changing_parameter = lt_fm_current_changing",
        "          export_parameter = lt_fm_current_export",
        "          tables_parameter = lt_fm_current_tables",
        "          exception_list = lt_fm_current_exceptions",
        "          documentation = lt_fm_current_documentation",
        "          source = lt_fm_current_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_PATCH_PARTIAL'.",
        "        ev_message = 'Function patched but re-read failed'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      IF lt_fm_current_import[] <> lt_fm_import[]",
        "         OR lt_fm_current_export[] <> lt_fm_export[]",
        "         OR lt_fm_current_changing[] <> lt_fm_changing[]",
        "         OR lt_fm_current_tables[] <> lt_fm_tables[]",
        "         OR lt_fm_current_exceptions[] <> lt_fm_exceptions[]",
        "         OR lt_fm_current_documentation[]",
        "           <> lt_fm_documentation[]",
        "         OR lt_fm_current_source[] <> lt_fm_source[].",
        "        ev_status = 'E'.",
        "        REFRESH it_source.",
        "        CLEAR lv_fm_diff_id.",
        "        emit_fm_difference 'IMPORT' lt_fm_import",
        "          lt_fm_current_import.",
        "        emit_fm_difference 'EXPORT' lt_fm_export",
        "          lt_fm_current_export.",
        "        emit_fm_difference 'CHANGING' lt_fm_changing",
        "          lt_fm_current_changing.",
        "        emit_fm_difference 'TABLES' lt_fm_tables",
        "          lt_fm_current_tables.",
        "        emit_fm_difference 'EXCEPTIONS' lt_fm_exceptions",
        "          lt_fm_current_exceptions.",
        "        emit_fm_difference 'DOCUMENTATION' lt_fm_documentation",
        "          lt_fm_current_documentation.",
        "        emit_fm_difference 'SOURCE' lt_fm_source",
        "          lt_fm_current_source.",
        "        ev_code = 'FUNCTION_PATCH_SAVE_NOT_OBSERVED'.",
        "        ev_message = 'Active function does not match the save'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      lt_fm_import[] = lt_fm_current_import[].",
        "      lt_fm_export[] = lt_fm_current_export[].",
        "      lt_fm_changing[] = lt_fm_current_changing[].",
        "      lt_fm_tables[] = lt_fm_current_tables[].",
        "      lt_fm_exceptions[] = lt_fm_current_exceptions[].",
        "      lt_fm_documentation[] = lt_fm_current_documentation[].",
        "      lt_fm_source[] = lt_fm_current_source[].",
        "      emit_fm_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_INTERFACE_PATCHED'.",
        "      ev_message = 'Function interface patched and verified'.",
        "      ev_version = '2.0'. RETURN.",
        "    WHEN 'INSPECT_REPOSITORY_ASSIGNMENT'.",
        "      CLEAR: ls_tadir, ls_tfdir, ls_enlfdir,",
        "        lv_parent_object, lv_transport_task,",
        "        lv_transport_request, lv_transport_status,",
        "        lv_active, lv_generated.",
        "      CASE iv_object_type.",
        "        WHEN 'CLAS'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'CLAS'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "              AND obj_name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'INTF'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'INTF'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'INTF'",
        "              AND obj_name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'FGRP'.",
        "          lv_parent_object = iv_object_name.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'FUGR'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "              AND obj_name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'FUNC'.",
        "          SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "            WHERE funcname = iv_object_name.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'REPOSITORY_OBJECT_NOT_FOUND'.",
        "            ev_message = 'Function module does not exist'.",
        "            ev_version = '1.3'.",
        "            RETURN.",
        "          ENDIF.",
        "          lv_parent_object = ls_tfdir-pname+4.",
        "          lv_transport_pgmid = 'LIMU'.",
        "          lv_transport_object = 'FUNC'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "              AND obj_name = lv_parent_object.",
        "          SELECT SINGLE * FROM enlfdir INTO ls_enlfdir",
        "            WHERE funcname = iv_object_name.",
        "          IF sy-subrc = 0.",
        "            lv_active = ls_enlfdir-active.",
        "            lv_generated = ls_enlfdir-generated.",
        "          ENDIF.",
        "        WHEN 'PROG'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'PROG'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "              AND obj_name = iv_object_name.",
        "          SELECT SINGLE * FROM trdir INTO ls_trdir",
        "            WHERE name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'TRAN'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'TRAN'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "              AND obj_name = iv_object_name.",
        "          SELECT SINGLE tcode FROM tstc",
        "            INTO lv_existing_tcode",
        "            WHERE tcode = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN OTHERS.",
        "          ev_status = 'E'.",
        "          ev_code = 'REPOSITORY_TYPE_UNSUPPORTED'.",
        "          ev_message = 'Repository object type is unsupported'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "      ENDCASE.",
        "      IF ls_tadir-obj_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'REPOSITORY_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Repository object does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT e071~trkorr e070~strkorr e070~trstatus",
        "        INTO (lv_transport_task, lv_transport_request,",
        "          lv_transport_status)",
        "        FROM e071 INNER JOIN e070",
        "          ON e070~trkorr = e071~trkorr",
        "        UP TO 1 ROWS",
        "        WHERE e071~pgmid = lv_transport_pgmid",
        "          AND e071~object = lv_transport_object",
        "          AND e071~obj_name = lv_transport_name",
        "          AND e070~trstatus <> 'R'.",
        "      ENDSELECT.",
      "      IF lv_transport_task IS INITIAL",
        "         AND iv_object_type = 'FUNC'.",
        "        lv_transport_pgmid = 'R3TR'.",
        "        lv_transport_object = 'FUGR'.",
        "        lv_transport_name = lv_parent_object.",
        "        SELECT e071~trkorr e070~strkorr e070~trstatus",
        "          INTO (lv_transport_task, lv_transport_request,",
        "            lv_transport_status)",
        "          FROM e071 INNER JOIN e070",
        "            ON e070~trkorr = e071~trkorr",
        "          UP TO 1 ROWS",
        "          WHERE e071~pgmid = lv_transport_pgmid",
        "            AND e071~object = lv_transport_object",
        "            AND e071~obj_name = lv_transport_name",
        "            AND e070~trstatus <> 'R'.",
        "        ENDSELECT.",
        "      ENDIF.",
        "      IF lv_transport_request IS INITIAL.",
        "        lv_transport_request = lv_transport_task.",
        "        CLEAR lv_transport_task.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PARENT_OBJECT'",
        "        lv_parent_object.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_transport_request.",
        "      add_repo_payload 'M' '1' 'TASK' lv_transport_task.",
        "      add_repo_payload 'M' '1' 'TRANSPORT_STATUS'",
        "        lv_transport_status.",
        "      add_repo_payload 'M' '1' 'ACTIVE' lv_active.",
        "      add_repo_payload 'M' '1' 'GENERATED' lv_generated.",
        "      add_repo_payload 'M' '1' 'ORIGINAL_SYSTEM'",
        "        ls_tadir-srcsystem.",
        "      ev_status = 'S'.",
        "      ev_code = 'REPOSITORY_ASSIGNMENT_READ'.",
        "      ev_message = 'Repository assignment read successfully'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    WHEN 'READ_GUI_DEFINITION'.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR: ls_gui_adm, lv_gui_language, lv_gui_author,",
        "        lv_gui_cauthor, lv_gui_date, lv_gui_time,",
        "        lv_gui_cdate, lv_gui_ctime, lv_gui_gdate,",
        "        lv_gui_gtime, lv_gui_current_version.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          state = 'A'",
        "        IMPORTING adm = ls_gui_adm",
        "          langu = lv_gui_language author = lv_gui_author",
        "          date = lv_gui_date time = lv_gui_time",
        "          cauthor = lv_gui_cauthor cdate = lv_gui_cdate",
        "          ctime = lv_gui_ctime gdate = lv_gui_gdate",
        "          gtime = lv_gui_gtime",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS not_found = 1 unknown_version = 2",
        "          OTHERS = 3.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        IF ev_message IS INITIAL.",
        "          ev_message = 'Active GUI definition could not be read'.",
        "        ENDIF.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE lv_gui_cdate lv_gui_ctime",
        "        INTO lv_gui_current_version.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        CONCATENATE lv_gui_date lv_gui_time",
        "          INTO lv_gui_current_version.",
        "      ENDIF.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        lv_gui_current_version = '00000000000000'.",
        "      ENDIF.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      emit_gui_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'GUI_DEFINITION_READ'.",
        "      ev_message = 'Active GUI definition read successfully'.",
        "      ev_version = '1.5'.",
        "      RETURN.",
        "    WHEN 'PATCH_GUI_DEFINITION'.",
        "      IF iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_PATCH_INPUT_REQUIRED'.",
        "        ev_message = 'Transport and GUI payload are required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      lt_gui_payload[] = it_source[].",
        "      CLEAR lv_gui_expected_version.",
        "      LOOP AT lt_gui_payload INTO ls_source.",
        "        CLEAR: lv_gui_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_gui_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_gui_kind = 'M'",
        "           AND lv_payload_property = 'EXPECTED_VERSION'.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          lv_gui_expected_version = lv_payload_value.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lv_gui_expected_version IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_EXPECTED_VERSION_REQUIRED'.",
        "        ev_message = 'GUI version token is required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR: ls_gui_adm, lv_gui_language, lv_gui_author,",
        "        lv_gui_cauthor, lv_gui_date, lv_gui_time,",
        "        lv_gui_cdate, lv_gui_ctime, lv_gui_gdate,",
        "        lv_gui_gtime, lv_gui_current_version.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          state = 'A'",
        "        IMPORTING adm = ls_gui_adm",
        "          langu = lv_gui_language author = lv_gui_author",
        "          date = lv_gui_date time = lv_gui_time",
        "          cauthor = lv_gui_cauthor cdate = lv_gui_cdate",
        "          ctime = lv_gui_ctime gdate = lv_gui_gdate",
        "          gtime = lv_gui_gtime",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS not_found = 1 unknown_version = 2",
        "          OTHERS = 3.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_READ_FAILED'.",
        "        ev_message = 'Active GUI definition could not be read'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE lv_gui_cdate lv_gui_ctime",
        "        INTO lv_gui_current_version.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        CONCATENATE lv_gui_date lv_gui_time",
        "          INTO lv_gui_current_version.",
        "      ENDIF.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        lv_gui_current_version = '00000000000000'.",
        "      ENDIF.",
        "      IF lv_gui_expected_version <> lv_gui_current_version.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_VERSION_CONFLICT'.",
        "        ev_message = 'GUI definition changed since it was read'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR ls_gui_adm.",
        "      LOOP AT lt_gui_payload INTO ls_source.",
        "        CLEAR: lv_gui_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_gui_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_gui_kind = 'M'. CONTINUE. ENDIF.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'GUI_PAYLOAD_INVALID'.",
        "          ev_message = 'GUI payload index is invalid'.",
        "          ev_version = '1.5'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        IF lv_payload_index < 1 OR lv_payload_index > 2000.",
        "          ev_status = 'E'.",
        "          ev_code = 'GUI_PAYLOAD_LIMIT'.",
        "          ev_message = 'GUI payload row limit exceeded'.",
        "          ev_version = '1.5'.",
        "          RETURN.",
        "        ENDIF.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        CASE lv_gui_kind.",
        "          WHEN 'ADM'.",
        "            IF lv_payload_index <> 1.",
        "              ev_status = 'E'.",
        "              ev_code = 'GUI_PAYLOAD_INVALID'.",
        "              ev_message = 'GUI ADM row index must be one'.",
        "              ev_version = '1.5'.",
        "              RETURN.",
        "            ENDIF.",
        "            ASSIGN ls_gui_adm TO <ls_gui_row>.",
        "          WHEN 'STA'.",
        "            WHILE lines( lt_gui_sta ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_sta.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_sta ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'FUN'.",
        "            WHILE lines( lt_gui_fun ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_fun.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_fun ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'MEN'.",
        "            WHILE lines( lt_gui_men ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_men.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_men ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'MTX'.",
        "            WHILE lines( lt_gui_mtx ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_mtx.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_mtx ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'ACT'.",
        "            WHILE lines( lt_gui_act ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_act.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_act ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'BUT'.",
        "            WHILE lines( lt_gui_but ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_but.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_but ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'PFK'.",
        "            WHILE lines( lt_gui_pfk ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_pfk.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_pfk ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'SET'.",
        "            WHILE lines( lt_gui_set ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_set.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_set ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'DOC'.",
        "            WHILE lines( lt_gui_doc ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_doc.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_doc ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'TIT'.",
        "            WHILE lines( lt_gui_tit ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_tit.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_tit ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'BIV'.",
        "            WHILE lines( lt_gui_biv ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_biv.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_biv ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'GUI_SECTION_INVALID'.",
        "            ev_message = 'Unknown GUI payload section'.",
        "            ev_version = '1.5'.",
        "            RETURN.",
        "        ENDCASE.",
        "        ASSIGN COMPONENT lv_payload_property",
        "          OF STRUCTURE <ls_gui_row>",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'GUI_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown GUI payload property'.",
        "          ev_version = '1.5'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      CLEAR: ls_tadir, ls_request, ls_task.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      IF sy-subrc <> 0 OR ls_tadir-devclass = '`$TMP'.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_PROGRAM_NOT_TRANSPORTABLE'.",
        "        ev_message = 'Transportable customer program required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_gui_tr_key, lv_gui_corrnum.",
        "      CALL FUNCTION 'RS_CORR_INSERT'",
        "        EXPORTING object = iv_program",
        "          object_class = 'SCUA' mode = 'M'",
        "          devclass = ls_tadir-devclass",
        "          korrnum = ls_request-trkorr",
        "          use_korrnum_immediatedly = 'X'",
        "          master_language = sy-langu suppress_dialog = 'X'",
        "        IMPORTING korrnum = lv_gui_corrnum",
        "          transport_key = ls_gui_tr_key",
        "        EXCEPTIONS cancelled = 1 permission_failure = 2",
        "          unknown_objectclass = 3 OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_gui_tcode = sy-tcode.",
        "      sy-tcode = 'SE41'.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_WRITE'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          tr_key = ls_gui_tr_key adm = ls_gui_adm state = 'A'",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS not_found = 1 OTHERS = 2.",
        "      lv_gui_subrc = sy-subrc.",
        "      sy-tcode = lv_gui_tcode.",
        "      IF lv_gui_subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_WRITE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR: ls_gui_adm, lv_gui_language, lv_gui_author,",
        "        lv_gui_cauthor, lv_gui_date, lv_gui_time,",
        "        lv_gui_cdate, lv_gui_ctime, lv_gui_gdate,",
        "        lv_gui_gtime, lv_gui_current_version.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          state = 'A'",
        "        IMPORTING adm = ls_gui_adm",
        "          langu = lv_gui_language author = lv_gui_author",
        "          date = lv_gui_date time = lv_gui_time",
        "          cauthor = lv_gui_cauthor cdate = lv_gui_cdate",
        "          ctime = lv_gui_ctime gdate = lv_gui_gdate",
        "          gtime = lv_gui_gtime",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS OTHERS = 3.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_VERIFY_FAILED'.",
        "        ev_message = 'GUI definition saved but re-read failed'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE lv_gui_cdate lv_gui_ctime",
        "        INTO lv_gui_current_version.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        CONCATENATE lv_gui_date lv_gui_time",
        "          INTO lv_gui_current_version.",
        "      ENDIF.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        lv_gui_current_version = '00000000000000'.",
        "      ENDIF.",
        "      emit_gui_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'GUI_DEFINITION_PATCHED'.",
        "      ev_message = 'GUI definition saved and verified'.",
        "      ev_version = '1.5'.",
        "      RETURN.",
        "    WHEN 'READ_SCREEN'.",
        "      REFRESH: ct_fields, ct_flowlogic, ct_params.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ_NATIVE'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "        IMPORTING header = es_header",
        "          dynprotext = ev_dynprotext",
        "        TABLES fieldlist = ct_fields",
        "          flowlogic = ct_flowlogic params = ct_params",
        "          fieldtexts = lt_fieldtexts",
        "        EXCEPTIONS cancelled = 1 not_found = 2",
        "          permission_error = 3 OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'SCREEN_READ'.",
        "        ev_message = 'Screen read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'PATCH_SCREEN'.",
        "      IF iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUIRED'.",
        "        ev_message = 'An existing transport is required'.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_containers, lt_screen_fields,",
        "        lt_screen_flow, lt_screen_params.",
        "      CLEAR ls_rpy_header.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "          suppress_exist_checks = space",
        "          suppress_corr_checks = space",
        "        IMPORTING header = ls_rpy_header",
        "        TABLES containers = lt_containers",
        "          fields_to_containers = lt_screen_fields",
        "          flow_logic = lt_screen_flow",
        "          params = lt_screen_params",
        "        EXCEPTIONS cancelled = 1 not_found = 2",
        "          permission_error = 3 OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_patch_count, lv_patch_flow,",
        "        lv_patch_params, lv_patch_header,",
        "        lv_patch_description.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PATCH_INVALID'.",
        "          ev_message = 'Patch payload index is invalid'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'O'",
        "           AND lv_payload_index > lv_patch_count.",
        "          lv_patch_count = lv_payload_index.",
        "        ELSEIF lv_payload_kind = 'M'.",
        "          CASE lv_payload_property.",
        "            WHEN 'FLOW_REPLACE'. lv_patch_flow = 'X'.",
        "            WHEN 'PARAMS_REPLACE'. lv_patch_params = 'X'.",
        "            WHEN 'HEADER_PATCH'. lv_patch_header = 'X'.",
        "            WHEN 'DESCRIPTION_PATCH'.",
        "              lv_patch_description = 'X'.",
        "          ENDCASE.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lv_patch_description = 'X'.",
        "        ls_rpy_header-descript = iv_description.",
        "      ENDIF.",
        "      IF lv_patch_header = 'X'.",
        "        IF is_header-noli IS NOT INITIAL.",
        "          ls_rpy_header-lines = is_header-noli.",
        "        ENDIF.",
        "        IF is_header-noco IS NOT INITIAL.",
        "          ls_rpy_header-columns = is_header-noco.",
        "        ENDIF.",
        "      ENDIF.",
        "      IF lv_patch_flow = 'X'.",
        "        REFRESH lt_screen_flow.",
        "      ENDIF.",
        "      IF lv_patch_params = 'X'.",
        "        REFRESH lt_screen_params.",
        "      ENDIF.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'L'",
        "           AND lv_patch_flow = 'X'.",
        "          WHILE lines( lt_screen_flow ) < lv_payload_index.",
        "            CLEAR ls_screen_flow.",
        "            APPEND ls_screen_flow TO lt_screen_flow.",
        "          ENDWHILE.",
        "          READ TABLE lt_screen_flow",
        "            ASSIGNING <ls_screen_flow>",
        "            INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_screen_flow>",
        "            TO <lv_payload_component>.",
        "        ELSEIF lv_payload_kind = 'P'",
        "           AND lv_patch_params = 'X'.",
        "          WHILE lines( lt_screen_params ) < lv_payload_index.",
        "            CLEAR ls_screen_param.",
        "            APPEND ls_screen_param TO lt_screen_params.",
        "          ENDWHILE.",
        "          READ TABLE lt_screen_params",
        "            ASSIGNING <ls_screen_param>",
        "            INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_screen_param>",
        "            TO <lv_payload_component>.",
        "        ELSE.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown screen patch property'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      DO lv_patch_count TIMES.",
        "        lv_patch_index = sy-index.",
        "        CLEAR: lv_patch_operation, lv_patch_name,",
        "          lv_patch_row_index.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "            lv_payload_index_text lv_payload_property",
        "            lv_payload_value.",
        "          lv_payload_index = lv_payload_index_text.",
        "          IF lv_payload_kind <> 'O'",
        "             OR lv_payload_index <> lv_patch_index.",
        "            CONTINUE.",
        "          ENDIF.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          CASE lv_payload_property.",
        "            WHEN 'OP'. lv_patch_operation = lv_payload_value.",
        "            WHEN 'NAME'. lv_patch_name = lv_payload_value.",
        "          ENDCASE.",
        "        ENDLOOP.",
        "        IF lv_patch_operation IS INITIAL",
        "           OR lv_patch_name IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PATCH_INVALID'.",
        "          ev_message = 'Patch operation and name are required'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        LOOP AT lt_screen_fields ASSIGNING <ls_screen_field>.",
        "          ASSIGN COMPONENT 'NAME' OF STRUCTURE",
        "            <ls_screen_field> TO <lv_payload_component>.",
        "          IF sy-subrc = 0",
        "             AND <lv_payload_component> = lv_patch_name.",
        "            lv_patch_row_index = sy-tabix.",
        "            EXIT.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF lv_patch_operation = 'ADD'.",
        "          IF lv_patch_row_index > 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'SCREEN_COMPONENT_EXISTS'.",
        "            ev_message = 'Screen component already exists'.",
        "            ev_version = '1.4'.",
        "            RETURN.",
        "          ENDIF.",
        "          CLEAR ls_screen_field.",
        "          APPEND ls_screen_field TO lt_screen_fields.",
        "          lv_patch_row_index = lines( lt_screen_fields ).",
        "        ELSEIF lv_patch_row_index = 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_COMPONENT_NOT_FOUND'.",
        "          ev_message = 'Screen component does not exist'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ELSEIF lv_patch_operation = 'REMOVE'.",
        "          DELETE lt_screen_fields INDEX lv_patch_row_index.",
        "          CONTINUE.",
        "        ELSEIF lv_patch_operation <> 'UPDATE'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PATCH_OPERATION_INVALID'.",
        "          ev_message = 'Screen patch operation is invalid'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_screen_fields",
        "          ASSIGNING <ls_screen_field>",
        "          INDEX lv_patch_row_index.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "            lv_payload_index_text lv_payload_property",
        "            lv_payload_value.",
        "          lv_payload_index = lv_payload_index_text.",
        "          IF lv_payload_kind <> 'O'",
        "             OR lv_payload_index <> lv_patch_index",
        "             OR lv_payload_property NP 'FIELD_*'.",
        "            CONTINUE.",
        "          ENDIF.",
        "          lv_payload_property = lv_payload_property+6.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_screen_field>",
        "            TO <lv_payload_component>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'SCREEN_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown screen component property'.",
        "            ev_version = '1.4'.",
        "            RETURN.",
        "          ENDIF.",
        "          <lv_payload_component> = lv_payload_value.",
        "        ENDLOOP.",
        "      ENDDO.",
        "      IF lt_screen_fields[] IS INITIAL",
        "         OR lt_screen_flow[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_PAYLOAD_REQUIRED'.",
        "        ev_message = 'Fields and flow logic are required'.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      LOOP AT lt_screen_fields ASSIGNING <ls_screen_field>.",
        "        IF <ls_screen_field>-cont_type IS INITIAL.",
        "          <ls_screen_field>-cont_type = 'SCREEN'.",
        "        ENDIF.",
        "        IF <ls_screen_field>-cont_name IS INITIAL.",
        "          <ls_screen_field>-cont_name = 'SCREEN'.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CALL FUNCTION 'RPY_DYNPRO_INSERT'",
        "        EXPORTING corrnum = iv_request",
        "          header = ls_rpy_header",
        "          suppress_exist_checks = 'X'",
        "          use_corrnum_immediatedly = 'X'",
        "          suppress_commit_work = 'X'",
        "        TABLES containers = lt_containers",
        "          fields_to_containers = lt_screen_fields",
        "          flow_logic = lt_screen_flow",
        "          params = lt_screen_params",
        "        EXCEPTIONS cancelled = 1 already_exists = 2",
        "          program_not_exists = 3 not_executed = 4",
        "          missing_required_field = 5",
        "          illegal_field_value = 6 field_not_allowed = 7",
        "          not_generated = 8 illegal_field_position = 9",
        "          OTHERS = 10.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_PATCH_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: ct_fields, ct_flowlogic, ct_params.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ_NATIVE'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "        IMPORTING header = es_header",
        "          dynprotext = ev_dynprotext",
        "        TABLES fieldlist = ct_fields",
        "          flowlogic = ct_flowlogic params = ct_params",
        "          fieldtexts = lt_fieldtexts",
        "        EXCEPTIONS OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_VERIFY_FAILED'.",
        "        ev_message = 'Screen patched but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'SCREEN_PATCHED'.",
        "        ev_message = 'Screen patched and re-read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.4'.",
        "      RETURN.",
        "    WHEN 'UPSERT_SCREEN'.",
        "      IF iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUIRED'.",
        "        ev_message = 'An existing transport is required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_screen_fields, lt_screen_flow,",
        "        lt_screen_params.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PAYLOAD_INVALID'.",
        "          ev_message = 'Screen payload index is invalid'.",
        "          ev_version = '1.1'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PAYLOAD_INVALID'.",
        "          ev_message = 'Serialized screen payload is invalid'.",
        "          ev_version = '1.1'.",
        "          RETURN.",
        "        ENDIF.",
        "        CASE lv_payload_kind.",
        "          WHEN 'F'.",
        "            WHILE lines( lt_screen_fields )",
        "              < lv_payload_index.",
        "              CLEAR ls_screen_field.",
        "              APPEND ls_screen_field TO lt_screen_fields.",
        "            ENDWHILE.",
        "            READ TABLE lt_screen_fields",
        "              ASSIGNING <ls_screen_field>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_screen_field>",
        "              TO <lv_payload_component>.",
        "          WHEN 'L'.",
        "            WHILE lines( lt_screen_flow )",
        "              < lv_payload_index.",
        "              CLEAR ls_screen_flow.",
        "              APPEND ls_screen_flow TO lt_screen_flow.",
        "            ENDWHILE.",
        "            READ TABLE lt_screen_flow",
        "              ASSIGNING <ls_screen_flow>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_screen_flow>",
        "              TO <lv_payload_component>.",
        "          WHEN 'P'.",
        "            WHILE lines( lt_screen_params )",
        "              < lv_payload_index.",
        "              CLEAR ls_screen_param.",
        "              APPEND ls_screen_param TO lt_screen_params.",
        "            ENDWHILE.",
        "            READ TABLE lt_screen_params",
        "              ASSIGNING <ls_screen_param>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_screen_param>",
        "              TO <lv_payload_component>.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'SCREEN_PAYLOAD_INVALID'.",
        "            ev_message = 'Unknown screen payload row type'.",
        "            ev_version = '1.1'.",
        "            RETURN.",
        "        ENDCASE.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown screen payload property'.",
        "          ev_version = '1.1'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      IF lt_screen_fields[] IS INITIAL",
        "         OR lt_screen_flow[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_PAYLOAD_REQUIRED'.",
        "        ev_message = 'Fields and flow logic are required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PROGRAM_NOT_FOUND'.",
        "        ev_message = 'Target program does not exist'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_rpy_header, ls_container.",
        "      REFRESH lt_containers.",
        "      ls_rpy_header-program = iv_program.",
        "      ls_rpy_header-screen = iv_screen.",
        "      ls_rpy_header-language = sy-langu.",
        "      ls_rpy_header-descript = iv_description.",
        "      ls_rpy_header-type = 'N'.",
        "      ls_rpy_header-nextscreen = iv_screen.",
        "      ls_rpy_header-lines = is_header-noli.",
        "      ls_rpy_header-columns = is_header-noco.",
        "      IF ls_rpy_header-lines IS INITIAL.",
        "        ls_rpy_header-lines = 20.",
        "      ENDIF.",
        "      IF ls_rpy_header-columns IS INITIAL.",
        "        ls_rpy_header-columns = 100.",
        "      ENDIF.",
        "      ls_container-type = 'SCREEN'.",
        "      ls_container-name = 'SCREEN'.",
        "      APPEND ls_container TO lt_containers.",
        "      LOOP AT lt_screen_fields ASSIGNING <ls_screen_field>.",
        "        IF <ls_screen_field>-cont_type IS INITIAL.",
        "          <ls_screen_field>-cont_type = 'SCREEN'.",
        "        ENDIF.",
        "        IF <ls_screen_field>-cont_name IS INITIAL.",
        "          <ls_screen_field>-cont_name = 'SCREEN'.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CALL FUNCTION 'RPY_DYNPRO_INSERT'",
        "        EXPORTING corrnum = iv_request",
        "          header = ls_rpy_header",
        "          suppress_exist_checks = 'X'",
        "          use_corrnum_immediatedly = 'X'",
        "          suppress_commit_work = 'X'",
        "        TABLES containers = lt_containers",
        "          fields_to_containers = lt_screen_fields",
        "          flow_logic = lt_screen_flow",
        "          params = lt_screen_params",
        "        EXCEPTIONS cancelled = 1 already_exists = 2",
        "          program_not_exists = 3 not_executed = 4",
        "          missing_required_field = 5",
        "          illegal_field_value = 6 field_not_allowed = 7",
        "          not_generated = 8 illegal_field_position = 9",
        "          OTHERS = 10.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_SAVE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: ct_fields, ct_flowlogic, ct_params.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ_NATIVE'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "        IMPORTING header = es_header",
        "          dynprotext = ev_dynprotext",
        "        TABLES fieldlist = ct_fields",
        "          flowlogic = ct_flowlogic params = ct_params",
        "          fieldtexts = lt_fieldtexts",
        "        EXCEPTIONS OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_VERIFY_FAILED'.",
        "        ev_message = 'Screen saved but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'SCREEN_SAVED'.",
        "        ev_message = 'Screen saved and re-read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'DELETE_TRANSACTION'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR iv_program IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'DELETE_TRANSACTION_INPUT_REQUIRED'.",
        "        ev_message = 'Program package and request are required'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "          AND obj_name = iv_transaction",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_ASSIGNMENT_MISMATCH'.",
        "        ev_message = 'Transaction package does not match'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_group_program.",
        "      SELECT SINGLE pgmna FROM tstc INTO lv_group_program",
        "        WHERE tcode = iv_transaction.",
        "      IF sy-subrc <> 0 OR lv_group_program <> iv_program.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_PROGRAM_MISMATCH'.",
        "        ev_message = 'Transaction program does not match'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'RPY_TRANSACTION_DELETE'",
        "        EXPORTING transaction = iv_transaction",
        "          transport_number = iv_request",
        "          suppress_authority_check = space",
        "          suppress_corr_insert = space",
        "        EXCEPTIONS not_executed = 1 OTHERS = 2.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_DELETE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE tcode FROM tstc INTO lv_existing_tcode",
        "        WHERE tcode = iv_transaction.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'Transaction still exists after delete'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'TRANSACTION_DELETED'.",
        "      ev_message = 'Transaction deleted and absence verified'.",
        "      ev_version = '1.6'.",
        "      RETURN.",
        "    WHEN 'DELETE_MODULE_POOL'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'DELETE_PROGRAM_INPUT_REQUIRED'.",
        "        ev_message = 'Package and request are required'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR: ls_tadir, ls_trdir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program.",
        "      IF ls_tadir-obj_name IS INITIAL",
        "         OR ( ls_trdir-name IS NOT INITIAL",
        "              AND ls_trdir-subc <> 'M' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_ASSIGNMENT_MISMATCH'.",
        "        ev_message = 'Module pool package or type mismatch'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_existing_tcode.",
        "      SELECT SINGLE tcode FROM tstc INTO lv_existing_tcode",
        "        WHERE pgmna = iv_program.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_TRANSACTION_EXISTS'.",
        "        ev_message = 'Delete dialog transactions first'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task, lv_delete_corrnum.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request does not exist'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trkorr IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_TASK_NOT_FOUND'.",
        "        ev_message = 'Modifiable user task is required'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_trdir-name IS INITIAL.",
        "        CLEAR ls_e071.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_task-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'PROG'",
        "            AND obj_name = iv_program.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'S'.",
        "          ev_code = 'MODULE_POOL_DELETED'.",
        "          ev_message = 'Task record and repository absence verified'.",
        "        ELSE.",
        "          ev_status = 'E'.",
        "          ev_code = 'MODULE_POOL_DELETE_STATE_INVALID'.",
        "          ev_message = 'Repository absent without a task record'.",
        "        ENDIF.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_trdir-name IS NOT INITIAL.",
        "        lv_delete_program = iv_program.",
        "        lv_delete_corrnum = ls_task-trkorr.",
        "        DELETE REPORT iv_program STATE 'I'.",
        "        CALL FUNCTION 'RS_DELETE_PROGRAM'",
        "          EXPORTING corrnumber = lv_delete_corrnum",
        "            program = lv_delete_program",
        "            suppress_checks = space",
        "            suppress_commit = space suppress_popup = 'X'",
        "            mass_delete_call = space with_cua = 'X'",
        "            with_documentation = 'X' with_dynpro = 'X'",
        "            with_includes = 'X' with_textpool = 'X'",
        "            with_variants = 'X' tadir_devclass = iv_package",
        "            skip_progress_ind = 'X'",
        "          IMPORTING corrnumber = lv_delete_corrnum",
        "            program = lv_delete_program",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MODULE_POOL_DELETE_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          ev_version = '1.6'.",
        "          RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR: ls_tadir, ls_trdir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      IF ls_trdir-name IS NOT INITIAL",
        "         OR ls_e071-obj_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_DELETE_VERIFY_FAILED'.",
        "        CONCATENATE 'Residual TRDIR=' ls_trdir-name",
        "          'TASK=' ls_e071-trkorr INTO ev_message",
        "          SEPARATED BY space.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'MODULE_POOL_DELETED'.",
        "      ev_message = 'Task record and repository absence verified'.",
        "      ev_version = '1.6'.",
        "      RETURN.",
        "    WHEN 'CREATE_MODULE_POOL'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Package request and source are required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_title = iv_description.",
        "      CALL FUNCTION 'RPY_PROGRAM_INSERT'",
        "        EXPORTING development_class = iv_package",
        "          program_name = iv_program program_type = 'M'",
        "          title_string = lv_title",
        "          transport_number = iv_request",
        "          suppress_dialog = 'X'",
        "        TABLES source_extended = it_source",
        "        EXCEPTIONS already_exists = 1 cancelled = 2",
        "          name_not_allowed = 3 permission_error = 4",
        "          OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_CREATE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program AND subc = 'M'.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0 OR ls_trdir-name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_VERIFY_FAILED'.",
        "        ev_message = 'Created program metadata is inconsistent'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      GENERATE REPORT iv_program",
        "        MESSAGE lv_message LINE lv_line WORD lv_word.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_GENERATE_FAILED'.",
        "        ev_message = lv_message.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'MODULE_POOL_CREATED'.",
        "        ev_message = 'Module pool created and generated'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'READ_TRANSPORT_DETAILS'.",
        "      IF iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUIRED'.",
        "        ev_message = 'Transport number is required'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_transport_text.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM e07t INTO ls_transport_text",
        "        WHERE trkorr = ls_request-trkorr",
        "          AND langu = sy-langu.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NUMBER' ls_request-trkorr.",
        "      add_repo_payload 'M' '1' 'OWNER' ls_request-as4user.",
        "      add_repo_payload 'M' '1' 'DESC'",
        "        ls_transport_text-as4text.",
        "      add_repo_payload 'M' '1' 'STATUS' ls_request-trstatus.",
        "      REFRESH lt_transport_objects.",
        "      SELECT * FROM e071 INTO TABLE lt_transport_objects",
        "        WHERE trkorr = ls_request-trkorr.",
        "      CLEAR lv_payload_index.",
        "      LOOP AT lt_transport_objects INTO ls_transport_object.",
        "        ADD 1 TO lv_payload_index.",
        "        add_repo_payload 'T' lv_payload_index 'TASK'",
        "          ls_transport_object-trkorr.",
        "        add_repo_payload 'T' lv_payload_index 'PGMID'",
        "          ls_transport_object-pgmid.",
        "        add_repo_payload 'T' lv_payload_index 'TYPE'",
        "          ls_transport_object-object.",
        "        add_repo_payload 'T' lv_payload_index 'NAME'",
        "          ls_transport_object-obj_name.",
        "        add_repo_payload 'T' lv_payload_index 'POSITION'",
        "          ls_transport_object-as4pos.",
        "        add_repo_payload 'T' lv_payload_index 'OBJ_INFO' ''.",
        "      ENDLOOP.",
        "      REFRESH lt_transport_tasks.",
      "      SELECT * FROM e070 INTO TABLE lt_transport_tasks",
      "        WHERE strkorr = ls_request-trkorr.",
      "      CLEAR lv_transport_task_index.",
      "      LOOP AT lt_transport_tasks INTO ls_transport_task.",
      "        ADD 1 TO lv_transport_task_index.",
      "        CLEAR ls_transport_text.",
        "        SELECT SINGLE * FROM e07t INTO ls_transport_text",
        "          WHERE trkorr = ls_transport_task-trkorr",
        "            AND langu = sy-langu.",
      "        add_repo_payload 'F' lv_transport_task_index 'NUMBER'",
      "          ls_transport_task-trkorr.",
      "        add_repo_payload 'F' lv_transport_task_index 'OWNER'",
      "          ls_transport_task-as4user.",
      "        add_repo_payload 'F' lv_transport_task_index 'DESC'",
      "          ls_transport_text-as4text.",
      "        add_repo_payload 'F' lv_transport_task_index 'STATUS'",
      "          ls_transport_task-trstatus.",
        "        REFRESH lt_transport_objects.",
        "        SELECT * FROM e071 INTO TABLE lt_transport_objects",
        "          WHERE trkorr = ls_transport_task-trkorr.",
        "        LOOP AT lt_transport_objects INTO ls_transport_object.",
        "          ADD 1 TO lv_payload_index.",
        "          add_repo_payload 'T' lv_payload_index 'TASK'",
        "            ls_transport_object-trkorr.",
        "          add_repo_payload 'T' lv_payload_index 'PGMID'",
        "            ls_transport_object-pgmid.",
        "          add_repo_payload 'T' lv_payload_index 'TYPE'",
        "            ls_transport_object-object.",
        "          add_repo_payload 'T' lv_payload_index 'NAME'",
        "            ls_transport_object-obj_name.",
        "          add_repo_payload 'T' lv_payload_index 'POSITION'",
        "            ls_transport_object-as4pos.",
        "          add_repo_payload 'T' lv_payload_index 'OBJ_INFO' ''.",
        "        ENDLOOP.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'TRANSPORT_DETAILS_READ'.",
        "      ev_message = 'Transport details read successfully'.",
        "      ev_version = '1.7'.",
        "      RETURN.",
        "    WHEN 'READ_TEXT_ELEMENTS' OR 'MERGE_TEXT_ELEMENTS'.",
        "      lv_textpool_program = iv_program.",
        "      lv_tadir_name = iv_program.",
        "      CASE iv_object_type.",
        "        WHEN 'PROG' OR space.",
        "          lv_tadir_type = 'PROG'.",
        "        WHEN 'CLAS'.",
        "          lv_tadir_type = 'CLAS'.",
        "          WHILE strlen( lv_textpool_program ) < 30.",
        "            CONCATENATE lv_textpool_program '='",
        "              INTO lv_textpool_program.",
        "          ENDWHILE.",
        "          CONCATENATE lv_textpool_program 'CP'",
        "            INTO lv_textpool_program.",
        "        WHEN 'FUGR'.",
        "          lv_tadir_type = 'FUGR'.",
        "          CONCATENATE 'SAPL' iv_program",
        "            INTO lv_textpool_program.",
        "        WHEN OTHERS.",
        "          ev_status = 'E'.",
        "          ev_code = 'TEXT_OBJECT_TYPE_INVALID'.",
        "          ev_message = 'Unsupported text element object type'.",
        "          ev_version = '1.7'.",
        "          RETURN.",
        "      ENDCASE.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = lv_textpool_program.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PROGRAM_NOT_FOUND'.",
        "        ev_message = 'Target program does not exist'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH lt_textpool.",
        "      READ TEXTPOOL lv_textpool_program INTO lt_textpool",
        "        LANGUAGE sy-langu STATE 'A'.",
        "      IF iv_operation = 'MERGE_TEXT_ELEMENTS'.",
        "        REFRESH lt_text_changes.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|'",
        "            INTO lv_payload_kind lv_payload_index_text",
        "              lv_payload_property lv_payload_value.",
        "          IF lv_payload_kind <> 'T'",
        "             OR lv_payload_index_text IS INITIAL",
        "             OR lv_payload_index_text CN '0123456789'.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_PAYLOAD_INVALID'.",
        "            ev_message = 'Text payload row is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          lv_payload_index = lv_payload_index_text.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          WHILE lines( lt_text_changes )",
        "            < lv_payload_index.",
        "            CLEAR ls_text_change.",
        "            APPEND ls_text_change TO lt_text_changes.",
        "          ENDWHILE.",
        "          READ TABLE lt_text_changes",
        "            ASSIGNING <ls_text_change>",
        "            INDEX lv_payload_index.",
        "          CASE lv_payload_property.",
        "            WHEN 'ID'.",
        "              <ls_text_change>-id = lv_payload_value.",
        "            WHEN 'TEXT'.",
        "              <ls_text_change>-entry = lv_payload_value.",
        "            WHEN 'MAXLENGTH'.",
        "              <ls_text_change>-length = lv_payload_value.",
        "            WHEN 'ACTION'.",
        "              <ls_text_change>-action = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'.",
        "              ev_code = 'TEXT_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown text payload property'.",
        "              ev_version = '1.2'.",
        "              RETURN.",
        "          ENDCASE.",
        "        ENDLOOP.",
        "        IF lt_text_changes[] IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'TEXT_PAYLOAD_REQUIRED'.",
        "          ev_message = 'Text element rows are required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        LOOP AT lt_text_changes ASSIGNING <ls_text_change>.",
        "          IF <ls_text_change>-id(3) CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'",
        "             OR <ls_text_change>-id+3 IS NOT INITIAL.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ID_INVALID'.",
        "            ev_message = 'Text symbol ID must be 3 characters'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          IF <ls_text_change>-entry IS INITIAL",
        "             OR <ls_text_change>-length",
        "               < strlen( <ls_text_change>-entry ).",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_VALUE_INVALID'.",
        "            ev_message = 'Text value or length is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          READ TABLE lt_textpool INTO ls_textpool",
        "            WITH KEY id = 'I' key = <ls_text_change>-id.",
        "          IF <ls_text_change>-action = 'CREATE'",
        "             AND sy-subrc = 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ELEMENT_EXISTS'.",
        "            ev_message = 'Text element already exists'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          IF <ls_text_change>-action = 'UPDATE'",
        "             AND sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ELEMENT_NOT_FOUND'.",
        "            ev_message = 'Text element does not exist'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          IF <ls_text_change>-action <> 'CREATE'",
        "             AND <ls_text_change>-action <> 'UPDATE'.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ACTION_INVALID'.",
        "            ev_message = 'Text action is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          CLEAR ls_textpool.",
        "          ls_textpool-id = 'I'.",
        "          ls_textpool-key = <ls_text_change>-id.",
        "          ls_textpool-entry = <ls_text_change>-entry.",
        "          ls_textpool-length = <ls_text_change>-length.",
        "          MODIFY lt_textpool FROM ls_textpool",
        "            TRANSPORTING entry length",
        "            WHERE id = 'I' AND key = <ls_text_change>-id.",
        "          IF sy-subrc <> 0.",
        "            APPEND ls_textpool TO lt_textpool.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "            AND obj_name = lv_tadir_name.",
        "        IF sy-subrc <> 0 OR ls_tadir-devclass = '`$TMP'.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORTABLE_TEXT_OBJECT_REQUIRED'.",
        "          ev_message = 'A transportable text object is required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR lv_recorded_request.",
        "        SELECT e071~trkorr FROM e071 INNER JOIN e070",
        "          ON e070~trkorr = e071~trkorr",
        "          INTO lv_recorded_request",
        "          WHERE ( e071~obj_name = lv_tadir_name",
        "              OR e071~obj_name = lv_textpool_program )",
        "            AND e070~trstatus <> 'R'.",
        "          EXIT.",
        "        ENDSELECT.",
        "        IF lv_recorded_request IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_ASSIGNMENT_NOT_FOUND'.",
        "          ev_message = 'No open text transport assignment found'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        INSERT TEXTPOOL lv_textpool_program FROM lt_textpool",
        "          LANGUAGE sy-langu STATE 'A'.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'TEXT_SAVE_FAILED'.",
        "          ev_message = 'Text pool save failed'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        COMMIT WORK AND WAIT.",
        "        REFRESH lt_textpool.",
        "        READ TEXTPOOL lv_textpool_program INTO lt_textpool",
        "          LANGUAGE sy-langu STATE 'A'.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "          AND obj_name = lv_tadir_name.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = lv_textpool_program.",
        "      CONCATENATE ls_trdir-udat '000000'",
        "        INTO lv_version.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      add_repo_payload 'M' '1' 'VERSION' lv_version.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_recorded_request.",
        "      CLEAR lv_payload_index.",
        "      LOOP AT lt_textpool INTO ls_textpool WHERE id = 'I'.",
        "        ADD 1 TO lv_payload_index.",
        "        add_repo_payload 'T' lv_payload_index 'ID'",
        "          ls_textpool-key.",
        "        add_repo_payload 'T' lv_payload_index 'TEXT'",
        "          ls_textpool-entry.",
        "        add_repo_payload 'T' lv_payload_index 'MAXLENGTH'",
        "          ls_textpool-length.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'MERGE_TEXT_ELEMENTS'.",
        "        ev_code = 'TEXT_ELEMENTS_SAVED'.",
        "        ev_message = 'Text elements saved and verified'.",
        "      ELSE.",
        "        ev_code = 'TEXT_ELEMENTS_READ'.",
        "        ev_message = 'Text elements read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'DELETE_MESSAGE_CLASS'.",
        "      IF iv_object_name IS INITIAL OR iv_package IS INITIAL",
        "         OR iv_package = '`$TMP' OR iv_request IS INITIAL",
        "         OR iv_expected_version IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'DELETE_INPUT_REQUIRED'.",
        "        ev_message = 'Version package and request are required'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_message_info, ls_message_tadir.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_NOT_FOUND'.",
        "        ev_message = 'Message class does not exist'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_message_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0 OR ls_message_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Message class package does not match'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE ls_message_info-ldate ls_message_info-ltime",
        "        INTO lv_version.",
        "      IF lv_version <> iv_expected_version.",
        "        ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "        ev_message = 'Message class changed since it was read'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_message_objects, lt_message_recorded_tadir.",
        "      CLEAR ls_message_object.",
        "      MOVE-CORRESPONDING ls_message_tadir TO ls_message_object.",
        "      ASSIGN COMPONENT 'OBJFUNC' OF STRUCTURE ls_message_object",
        "        TO <lv_payload_component>.",
        "      IF sy-subrc = 0. <lv_payload_component> = 'D'. ENDIF.",
        "      APPEND ls_message_object TO lt_message_objects.",
        "      CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "        EXPORTING iv_request = ls_request-trkorr",
        "          it_objects = lt_message_objects",
        "        IMPORTING et_tadir = lt_message_recorded_tadir",
        "        EXCEPTIONS cancel = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      DELETE FROM t100 WHERE arbgb = iv_object_name.",
        "      DELETE t100a FROM ls_message_info.",
        "      IF sy-subrc = 0.",
        "        DELETE tadir FROM ls_message_tadir.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_DELETE_FAILED'.",
        "        ev_message = 'Message repository rows could not be deleted'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'Message class still exists after delete'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_message_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_TADIR_DELETE_FAILED'.",
        "        ev_message = 'Message class directory entry still exists'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'REQUEST' ls_task-trkorr.",
        "      ev_status = 'S'. ev_code = 'MESSAGE_CLASS_DELETED'.",
        "      ev_message = 'Message class deleted and absence verified'.",
        "      ev_version = '1.9'. RETURN.",
        "    WHEN 'UPDATE_MESSAGE_CLASS'.",
        "      IF iv_object_name IS INITIAL OR iv_package IS INITIAL",
        "         OR iv_package = '`$TMP' OR iv_request IS INITIAL",
        "         OR iv_expected_version IS INITIAL",
        "         OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'UPDATE_INPUT_REQUIRED'.",
        "        ev_message = 'Version package request and messages required'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      REFRESH lt_messages.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|'",
        "          INTO lv_payload_kind lv_payload_index_text",
        "            lv_payload_property lv_payload_value.",
        "        IF lv_payload_kind <> 'F'",
        "           OR lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'MESSAGE_PAYLOAD_INVALID'.",
        "          ev_message = 'Message payload row is invalid'.",
        "          ev_version = '1.8'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        WHILE lines( lt_messages ) < lv_payload_index.",
        "          CLEAR ls_message_row.",
        "          APPEND ls_message_row TO lt_messages.",
        "        ENDWHILE.",
        "        READ TABLE lt_messages ASSIGNING <ls_message_row>",
        "          INDEX lv_payload_index.",
        "        CASE lv_payload_property.",
        "          WHEN 'MSGNR'.",
        "            <ls_message_row>-msgnr = lv_payload_value.",
        "          WHEN 'TEXT'.",
        "            <ls_message_row>-text = lv_payload_value.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'MESSAGE_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown message payload property'.",
        "            ev_version = '1.8'. RETURN.",
        "        ENDCASE.",
        "      ENDLOOP.",
        "      LOOP AT lt_messages ASSIGNING <ls_message_row>.",
        "        IF <ls_message_row>-msgnr CN '0123456789'",
        "           OR strlen( <ls_message_row>-msgnr ) <> 3",
        "           OR <ls_message_row>-text IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'MESSAGE_VALUE_INVALID'.",
        "          ev_message = 'Message number or text is invalid'.",
        "          ev_version = '1.8'. RETURN.",
        "        ENDIF.",
        "        <ls_message_row>-sprsl = sy-langu.",
        "        <ls_message_row>-arbgb = iv_object_name.",
        "      ENDLOOP.",
        "      CLEAR: ls_message_info, ls_message_tadir.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_NOT_FOUND'.",
        "        ev_message = 'Message class does not exist'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_message_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0 OR ls_message_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Message class package does not match'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE ls_message_info-ldate ls_message_info-ltime",
        "        INTO lv_version.",
        "      IF lv_version <> iv_expected_version.",
        "        ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "        ev_message = 'Message class changed since it was read'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_message_objects, lt_message_recorded_tadir.",
        "      CLEAR ls_message_object.",
        "      MOVE-CORRESPONDING ls_message_tadir TO ls_message_object.",
        "      APPEND ls_message_object TO lt_message_objects.",
        "      CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "        EXPORTING iv_request = ls_request-trkorr",
        "          it_objects = lt_message_objects",
        "        IMPORTING et_tadir = lt_message_recorded_tadir",
        "        EXCEPTIONS cancel = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      ls_message_info-lastuser = sy-uname.",
        "      ls_message_info-ldate = sy-datum.",
        "      ls_message_info-ltime = sy-uzeit.",
        "      UPDATE t100a FROM ls_message_info.",
        "      IF sy-subrc = 0.",
        "        DELETE FROM t100 WHERE sprsl = sy-langu",
        "          AND arbgb = iv_object_name.",
        "        INSERT t100 FROM TABLE lt_messages.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_UPDATE_FAILED'.",
        "        ev_message = 'Message repository rows could not be saved'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      lv_recorded_request = ls_task-trkorr.",
        "      REFRESH lt_messages.",
        "      CLEAR ls_message_info.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      SELECT * FROM t100 INTO TABLE lt_messages",
        "        WHERE sprsl = sy-langu AND arbgb = iv_object_name.",
        "      SORT lt_messages BY msgnr.",
        "      CONCATENATE ls_message_info-ldate",
        "        ls_message_info-ltime INTO lv_version.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'VERSION' lv_version.",
        "      add_repo_payload 'M' '1' 'DESCRIPTION'",
        "        ls_message_info-stext.",
        "      add_repo_payload 'M' '1' 'MASTERLANG'",
        "        ls_message_info-masterlang.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_recorded_request.",
        "      LOOP AT lt_messages INTO ls_message_row.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'F' lv_payload_index 'MSGNR'",
        "          ls_message_row-msgnr.",
        "        add_repo_payload 'F' lv_payload_index 'TEXT'",
        "          ls_message_row-text.",
        "      ENDLOOP.",
        "      ev_status = 'S'. ev_code = 'MESSAGE_CLASS_UPDATED'.",
        "      ev_message = 'Message class updated and verified'.",
        "      ev_version = '1.8'. RETURN.",
        "    WHEN 'READ_MESSAGE_CLASS' OR 'CREATE_MESSAGE_CLASS'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_REQUIRED'.",
        "        ev_message = 'Message class is required'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF iv_operation = 'CREATE_MESSAGE_CLASS'.",
        "        IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "           OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'CREATE_INPUT_REQUIRED'.",
        "          ev_message = 'Package request and messages required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "            AND obj_name = iv_object_name.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_CLASS_EXISTS'.",
        "          ev_message = 'Message class already exists'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        REFRESH lt_messages.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|'",
        "            INTO lv_payload_kind lv_payload_index_text",
        "              lv_payload_property lv_payload_value.",
        "          IF lv_payload_kind <> 'F'",
        "             OR lv_payload_index_text IS INITIAL",
        "             OR lv_payload_index_text CN '0123456789'.",
        "            ev_status = 'E'.",
        "            ev_code = 'MESSAGE_PAYLOAD_INVALID'.",
        "            ev_message = 'Message payload row is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          lv_payload_index = lv_payload_index_text.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          WHILE lines( lt_messages ) < lv_payload_index.",
        "            CLEAR ls_message_row.",
        "            APPEND ls_message_row TO lt_messages.",
        "          ENDWHILE.",
        "          READ TABLE lt_messages ASSIGNING <ls_message_row>",
        "            INDEX lv_payload_index.",
        "          CASE lv_payload_property.",
        "            WHEN 'MSGNR'.",
        "              <ls_message_row>-msgnr = lv_payload_value.",
        "            WHEN 'TEXT'.",
        "              <ls_message_row>-text = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'.",
        "              ev_code = 'MESSAGE_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown message payload property'.",
        "              ev_version = '1.2'.",
        "              RETURN.",
        "          ENDCASE.",
        "        ENDLOOP.",
        "        LOOP AT lt_messages ASSIGNING <ls_message_row>.",
        "          IF <ls_message_row>-msgnr CN '0123456789'",
        "             OR strlen( <ls_message_row>-msgnr ) <> 3",
        "             OR <ls_message_row>-text IS INITIAL.",
        "            ev_status = 'E'.",
        "            ev_code = 'MESSAGE_VALUE_INVALID'.",
        "            ev_message = 'Message number or text is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          <ls_message_row>-sprsl = sy-langu.",
        "          <ls_message_row>-arbgb = iv_object_name.",
        "        ENDLOOP.",
        "        SELECT SINGLE * FROM tdevc INTO ls_package",
        "          WHERE devclass = iv_package.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'PACKAGE_NOT_FOUND'.",
        "          ev_message = 'Transportable package does not exist'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_request, ls_task.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = iv_request.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_NOT_FOUND'.",
        "          ev_message = 'Transport request or task does not exist'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        IF ls_request-strkorr IS NOT INITIAL.",
        "          ls_task = ls_request.",
        "          SELECT SINGLE * FROM e070 INTO ls_request",
        "            WHERE trkorr = ls_task-strkorr.",
        "        ELSE.",
        "          SELECT SINGLE * FROM e070 INTO ls_task",
        "            WHERE strkorr = ls_request-trkorr",
        "              AND as4user = sy-uname AND trstatus = 'D'.",
        "        ENDIF.",
        "        IF ls_request-trfunction <> 'K'",
        "           OR ls_request-trstatus <> 'D'",
        "           OR ls_task-trstatus <> 'D'",
        "           OR ls_task-as4user <> sy-uname.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "          ev_message = 'Open workbench task for user is required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_message_tadir_input, ls_message_tadir.",
        "        ls_message_tadir_input-pgmid = 'R3TR'.",
        "        ls_message_tadir_input-object = 'MSAG'.",
        "        ls_message_tadir_input-obj_name = iv_object_name.",
        "        ls_message_tadir_input-srcsystem = sy-sysid.",
        "        ls_message_tadir_input-author = sy-uname.",
        "        ls_message_tadir_input-devclass = iv_package.",
        "        ls_message_tadir_input-masterlang = sy-langu.",
        "        CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "          EXPORTING wi_test_modus = space",
        "            wi_tadir_pgmid = ls_message_tadir_input-pgmid",
        "            wi_tadir_object = ls_message_tadir_input-object",
        "            wi_tadir_obj_name = ls_message_tadir_input-obj_name",
        "            wi_tadir_srcsystem = ls_message_tadir_input-srcsystem",
        "            wi_tadir_author = ls_message_tadir_input-author",
        "            wi_tadir_devclass = ls_message_tadir_input-devclass",
        "            wi_tadir_masterlang = ls_message_tadir_input-masterlang",
        "          IMPORTING new_tadir_entry = ls_message_tadir",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0",
        "           OR ls_message_tadir-devclass <> iv_package.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_TADIR_CREATE_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        REFRESH: lt_message_objects, lt_message_recorded_tadir.",
        "        CLEAR ls_message_object.",
        "        MOVE-CORRESPONDING ls_message_tadir TO ls_message_object.",
        "        APPEND ls_message_object TO lt_message_objects.",
        "        CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "          EXPORTING iv_request = ls_request-trkorr",
        "            it_objects = lt_message_objects",
        "          IMPORTING et_tadir = lt_message_recorded_tadir",
        "          EXCEPTIONS cancel = 1.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_TRANSPORT_RECORD_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR ls_message_info.",
        "        ls_message_info-arbgb = iv_object_name.",
        "        ls_message_info-masterlang = sy-langu.",
        "        ls_message_info-respuser = sy-uname.",
        "        ls_message_info-lastuser = sy-uname.",
        "        ls_message_info-ldate = sy-datum.",
        "        ls_message_info-ltime = sy-uzeit.",
        "        ls_message_info-stext = iv_description.",
        "        INSERT t100a FROM ls_message_info.",
        "        IF sy-subrc = 0.",
        "          INSERT t100 FROM TABLE lt_messages.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_CLASS_CREATE_FAILED'.",
        "          ev_message = 'Message repository rows could not be created'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        COMMIT WORK AND WAIT.",
        "        CLEAR ls_e071.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_task-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'MSAG'",
        "            AND obj_name = iv_object_name.",
        "        IF sy-subrc <> 0.",
        "          SELECT SINGLE * FROM e071 INTO ls_e071",
        "            WHERE trkorr = ls_request-trkorr",
        "              AND pgmid = 'R3TR' AND object = 'MSAG'",
        "              AND obj_name = iv_object_name.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_TRANSPORT_VERIFY_FAILED'.",
        "          ev_message = 'Message created but transport entry is missing'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_recorded_request = ls_e071-trkorr.",
        "      ENDIF.",
        "      REFRESH lt_messages.",
        "      CLEAR ls_message_info.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_NOT_FOUND'.",
        "        ev_message = 'Message class does not exist'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT * FROM t100 INTO TABLE lt_messages",
        "        WHERE sprsl = sy-langu AND arbgb = iv_object_name.",
        "      SORT lt_messages BY msgnr.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      CONCATENATE ls_message_info-ldate",
        "        ls_message_info-ltime INTO lv_version.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      add_repo_payload 'M' '1' 'VERSION' lv_version.",
        "      add_repo_payload 'M' '1' 'DESCRIPTION'",
        "        ls_message_info-stext.",
        "      add_repo_payload 'M' '1' 'MASTERLANG'",
        "        ls_message_info-masterlang.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_recorded_request.",
        "      LOOP AT lt_messages INTO ls_message_row.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'F' lv_payload_index 'MSGNR'",
        "          ls_message_row-msgnr.",
        "        add_repo_payload 'F' lv_payload_index 'TEXT'",
        "          ls_message_row-text.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'CREATE_MESSAGE_CLASS'.",
        "        ev_code = 'MESSAGE_CLASS_CREATED'.",
        "        ev_message = 'Message class created and verified'.",
        "      ELSE.",
        "        ev_code = 'MESSAGE_CLASS_READ'.",
        "        ev_message = 'Message class read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'READ_TRANSACTION'.",
        "      REFRESH: et_tcodes, et_gui_attributes.",
        "      CALL FUNCTION 'RPY_TRANSACTION_READ'",
        "        EXPORTING transaction = iv_transaction",
        "        TABLES tcodes = et_tcodes",
        "          gui_attributes = et_gui_attributes",
        "        EXCEPTIONS permission_error = 1 cancelled = 2",
        "          not_found = 3 object_not_found = 4",
        "          OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        IF sy-subrc = 3 OR sy-subrc = 4.",
        "          ev_code = 'TRANSACTION_NOT_FOUND'.",
        "          ev_message = 'Transaction does not exist'.",
        "        ELSE.",
        "          ev_code = 'TRANSACTION_READ_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "        ENDIF.",
        "      ELSE.",
        "        CLEAR ls_tadir.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "            AND obj_name = iv_transaction.",
        "        REFRESH it_source.",
        "        add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "        ev_status = 'S'.",
        "        ev_code = 'TRANSACTION_READ'.",
        "        ev_message = 'Transaction read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'CREATE_REPORT_TRANSACTION'.",
        "      IF iv_program IS INITIAL",
        "         OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Report package and request are required'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program AND subc = '1'.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'EXECUTABLE_REPORT_NOT_FOUND'.",
        "        ev_message = 'Executable report does not exist'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'REPORT_PACKAGE_MISMATCH'.",
        "        ev_message = 'Report package does not match'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_existing_tcode.",
        "      SELECT SINGLE tcode FROM tstc INTO lv_existing_tcode",
        "        WHERE tcode = iv_transaction.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_EXISTS'.",
        "        ev_message = 'Transaction already exists'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_report_variant = iv_object_name.",
        "      IF lv_report_variant IS NOT INITIAL.",
        "        SELECT SINGLE variant FROM varid",
        "          INTO lv_report_variant",
        "          WHERE report = iv_program",
        "            AND variant = lv_report_variant.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'REPORT_VARIANT_NOT_FOUND'.",
        "          ev_message = 'Report variant does not exist'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      CALL FUNCTION 'RPY_TRANSACTION_INSERT'",
        "        EXPORTING transaction = iv_transaction",
        "          program = iv_program language = sy-langu",
        "          development_class = iv_package",
        "          transport_number = iv_request",
        "          transaction_type = 'R' shorttext = iv_description",
        "          variant = lv_report_variant",
        "          html_enabled = 'X' wingui_enabled = 'X'",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'REPORT_TRANSACTION_CREATE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: et_tcodes, et_gui_attributes.",
        "      CALL FUNCTION 'RPY_TRANSACTION_READ'",
        "        EXPORTING transaction = iv_transaction",
        "        TABLES tcodes = et_tcodes",
        "          gui_attributes = et_gui_attributes",
        "        EXCEPTIONS OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_VERIFY_FAILED'.",
        "        ev_message = 'Transaction created but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'REPORT_TRANSACTION_CREATED'.",
        "        ev_message = 'Report transaction created and re-read'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'CREATE_TRANSACTION'.",
        "      IF iv_program IS INITIAL",
        "         OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Program package and request are required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM d020s INTO es_header",
        "        WHERE prog = iv_program AND dnum = iv_screen.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_NOT_FOUND'.",
        "        ev_message = 'Target screen does not exist'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'RPY_TRANSACTION_INSERT'",
        "        EXPORTING transaction = iv_transaction",
        "          program = iv_program dynpro = iv_screen",
        "          development_class = iv_package",
        "          transport_number = iv_request",
        "          transaction_type = 'D' shorttext = iv_description",
        "          html_enabled = 'X' wingui_enabled = 'X'",
        "        EXCEPTIONS cancelled = 1 already_exist = 2",
        "          permission_error = 3 name_not_allowed = 4",
        "          name_conflict = 5 illegal_type = 6",
        "          object_inconsistent = 7 db_access_error = 8",
        "          OTHERS = 9.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_CREATE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: et_tcodes, et_gui_attributes.",
        "      CALL FUNCTION 'RPY_TRANSACTION_READ'",
        "        EXPORTING transaction = iv_transaction",
        "        TABLES tcodes = et_tcodes",
        "          gui_attributes = et_gui_attributes",
        "        EXCEPTIONS OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_VERIFY_FAILED'.",
        "        ev_message = 'Transaction created but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'TRANSACTION_CREATED'.",
        "        ev_message = 'Transaction created and re-read'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "  ENDCASE.",
        "  zcl_orvanta_mcp_core=>execute(",
        "    EXPORTING",
        "      iv_operation = iv_operation",
        "      iv_object_type = iv_object_type",
        "      iv_object_name = iv_object_name",
        "    IMPORTING",
        "      ev_status = ev_status",
        "      ev_code = ev_code",
        "      ev_message = ev_message",
        "      ev_version = ev_version )."
    )
    $functionSource = if ($FunctionName -eq "Z_ORVANTA_MCP_DDIC_API") {
        New-DdicFunctionSource
    }
    else {
        $repositoryFunctionSource
    }
    # SOURCE|HASH is the SHA-256 (lowercase hex) of the exact ABAP text about to be
    # uploaded -- ($functionSource -join "`n") -- while its own four 16-character
    # placeholders are still in place. The hash is then written into those slots in
    # order (no length change), so re-running the generator on the same source
    # reproduces the same hash. Recompute it the same way to verify a deployment.
    if (($functionSource -join "`n").Contains($capabilityHashSlots[0])) {
        $capabilityHashInput = $functionSource -join "`n"
        $capabilitySha256 = [Security.Cryptography.SHA256]::Create()
        try {
            $capabilityHashBytes = $capabilitySha256.ComputeHash(
                [Text.Encoding]::UTF8.GetBytes($capabilityHashInput)
            )
        }
        finally {
            $capabilitySha256.Dispose()
        }
        $capabilitySourceHash = (
            $capabilityHashBytes | ForEach-Object { $_.ToString("x2") }
        ) -join ""
        $functionSource = @(
            foreach ($capabilitySourceLine in $functionSource) {
                $capabilityHashedLine = $capabilitySourceLine
                for ($capabilityHashIndex = 0; $capabilityHashIndex -lt 4; $capabilityHashIndex++) {
                    $capabilityHashedLine = $capabilityHashedLine.Replace(
                        $capabilityHashSlots[$capabilityHashIndex],
                        $capabilitySourceHash.Substring($capabilityHashIndex * 16, 16)
                    )
                }
                $capabilityHashedLine
            }
        )
    }
    $operationDbField = if ($FunctionName -eq "Z_ORVANTA_MCP_DDIC_API") {
        "BAPIRET2-PARAMETER"
    }
    else {
        "RS38L-NAME"
    }
    $ddicImportLines = if (
        $FunctionName -eq "Z_ORVANTA_MCP_DDIC_API" -or
        $FunctionName -eq "Z_ORVANTA_MCP_DYNPRO_API"
    ) {
        @(
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_EXPECTED_VERSION'.",
            "ls_import-dbfield = 'SY-MSGV1'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import."
        )
    }
    else {
        @()
    }

    $sourceProgramLines = foreach ($line in $functionSource) {
        if ($line.Length -gt 72) {
            throw "Generated function source exceeds 72 characters: $line"
        }
        $chunks = @()
        $offset = 0
        while ($offset -lt $line.Length) {
            $length = [Math]::Min(20, $line.Length - $offset)
            while (
                $length -gt 1 -and
                [char]::IsWhiteSpace($line[$offset + $length - 1])
            ) {
                $length--
            }
            $chunks += $line.Substring($offset, $length)
            $offset += $length
        }
        if (
            ($chunks[0] -match '^\s+$') -or
            $chunks.Where({ $_ -match '\s$' }).Count -gt 0 -or
            ($chunks -join '') -ne $line
        ) {
            throw "Generated source chunks cannot preserve whitespace: $line"
        }
        $chunks = @($chunks | ForEach-Object { $_.Replace("'", "''") })
        "lv_source_line = '$($chunks[0])'."
        foreach ($chunk in $chunks | Select-Object -Skip 1) {
            "CONCATENATE lv_source_line '$chunk'"
            "  INTO lv_source_line RESPECTING BLANKS."
        }
        "ls_source-line = lv_source_line."
        "APPEND ls_source TO lt_source."
    }

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_exceptions TYPE TABLE OF rsexc.",
        "DATA lt_parameter_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA ls_tables TYPE rstbl.",
        "DATA ls_source TYPE rssource.",
        "DATA lv_source_line TYPE string.",
        "DATA lt_function_code TYPE rsfb_source.",
        "DATA lv_function_line TYPE string.",
        "DATA lv_function_include TYPE rs38l-include.",
        "DATA lv_insert_index TYPE i.",
        "DATA lv_generate_message TYPE string.",
        "DATA lv_generate_line TYPE i.",
        "DATA lv_generate_word TYPE string.",
        "CALL FUNCTION 'FUNCTION_EXISTS'",
        "  EXPORTING funcname = '$FunctionName'",
        "  EXCEPTIONS function_not_exist = 1 others = 2."
    ) + $existingObjectLines + @(
        "ls_import-parameter = 'IV_OPERATION'.",
        "ls_import-dbfield = '$operationDbField'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_OBJECT_TYPE'.",
        "ls_import-dbfield = 'TADIR-OBJECT'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_PROGRAM'.",
        "ls_import-dbfield = 'TRDIR-NAME'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_SCREEN'.",
        "ls_import-dbfield = 'D020S-DNUM'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_TRANSACTION'.",
        "ls_import-dbfield = 'TSTC-TCODE'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_DESCRIPTION'.",
        "ls_import-dbfield = 'TSTCT-TTEXT'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_PACKAGE'.",
        "ls_import-dbfield = 'TADIR-DEVCLASS'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_REQUEST'.",
        "ls_import-dbfield = 'E070-TRKORR'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IS_HEADER'.",
        "ls_import-dbfield = 'D020S'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_OBJECT_NAME'.",
        "ls_import-dbfield = 'TADIR-OBJ_NAME'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import."
    ) + $ddicImportLines + @(
        "ls_export-parameter = 'EV_STATUS'.",
        "ls_export-dbfield = 'SY-MSGTY'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_CODE'.",
        "ls_export-dbfield = 'SY-MSGV1'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_MESSAGE'.",
        "ls_export-dbfield = 'BAPIRET2-MESSAGE'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_VERSION'.",
        "ls_export-dbfield = 'SY-MSGV1'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'ES_HEADER'.",
        "ls_export-dbfield = 'D020S'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_DYNPROTEXT'.",
        "ls_export-dbfield = 'D020T-DTXT'.",
        "APPEND ls_export TO lt_export.",
        "ls_tables-parameter = 'CT_FIELDS'.",
        "ls_tables-dbstruct = 'D021S'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'CT_FLOWLOGIC'.",
        "ls_tables-dbstruct = 'D022S'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'CT_PARAMS'.",
        "ls_tables-dbstruct = 'D023S'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'ET_TCODES'.",
        "ls_tables-dbstruct = 'TSTC'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'ET_GUI_ATTRIBUTES'.",
        "ls_tables-dbstruct = 'TSTCC'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'IT_SOURCE'.",
        "ls_tables-dbstruct = 'ABAPTXT255'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables."
    ) + $sourceProgramLines + @(
        "CALL FUNCTION 'FUNCTION_CREATE'",
        "  EXPORTING",
        "    funcname = '$FunctionName'",
        "    function_pool = 'ZORVANTA_MCP_CORE'",
        "    remote_call = 'R'",
        "    short_text = 'ORVANTA MCP controlled entry point'",
        "    suppress_corr_check = 'X'",
        "    save_active = 'X'",
        "  IMPORTING",
        "    function_include = lv_function_include",
        "  TABLES",
        "    import_parameter = lt_import",
        "    export_parameter = lt_export",
        "    tables_parameter = lt_tables",
        "    exception_list = lt_exceptions",
        "    parameter_docu = lt_parameter_docu",
        "  EXCEPTIONS",
        "    double_task = 1",
        "    error_message = 2",
        "    function_already_exists = 3",
        "    invalid_function_pool = 4",
        "    invalid_name = 5",
        "    too_many_functions = 6",
        "    no_modify_permission = 7",
        "    no_show_permission = 8",
        "    enqueue_system_failure = 9",
        "    canceled_in_corr = 10",
        "    others = 11.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'CREATE_ERROR', sy-subrc, sy-msgid, sy-msgno,",
        "    sy-msgv1, sy-msgv2, sy-msgv3, sy-msgv4.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "UPDATE enlfdir SET generated = space",
        "  WHERE funcname = '$FunctionName'.",
        "READ REPORT lv_function_include INTO lt_function_code.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'SOURCE_READ_ERROR', sy-subrc,",
        "    lv_function_include.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR lv_insert_index.",
        "LOOP AT lt_function_code INTO lv_function_line.",
        "  IF lv_function_line CS '""-----------------------------------------'",
        "     AND sy-tabix <> 2.",
        "    lv_insert_index = sy-tabix + 1.",
        "    EXIT.",
        "  ENDIF.",
        "ENDLOOP.",
        "IF lv_insert_index IS INITIAL.",
        "  WRITE / 'SOURCE_MARKER_ERROR'.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "LOOP AT lt_source INTO ls_source.",
        "  INSERT ls_source-line INTO lt_function_code",
        "    INDEX lv_insert_index.",
        "  lv_insert_index = lv_insert_index + 1.",
        "ENDLOOP.",
        "INSERT REPORT lv_function_include FROM lt_function_code.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'SOURCE_INSERT_ERROR', sy-subrc,",
        "    lv_function_include.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "GENERATE REPORT 'SAPLZORVANTA_MCP_CORE'",
        "  MESSAGE lv_generate_message LINE lv_generate_line",
        "  WORD lv_generate_word.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'GENERATE_ERROR', sy-subrc, lv_generate_line,",
        "    lv_generate_word, / lv_generate_message.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "UPDATE enlfdir SET generated = 'X'",
        "  WHERE funcname = '$FunctionName'.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'FUNCTION_ACTIVATION_FLAG_ERROR', sy-subrc.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "COMMIT WORK AND WAIT.",
        "WRITE / 'CREATED $FunctionName'."
    )
}

function New-FunctionGroupDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lv_message TYPE string.",
        "DATA lv_line TYPE i.",
        "DATA lv_word TYPE string.",
        "GENERATE REPORT 'SAPLZORVANTA_MCP_CORE'",
        "  MESSAGE lv_message LINE lv_line WORD lv_word.",
        "WRITE: / 'SUBRC', sy-subrc.",
        "WRITE: / 'LINE', lv_line.",
        "WRITE: / 'WORD', lv_word.",
        "WRITE: / 'MESSAGE', lv_message."
    )
}

function New-HelperApiDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_names TYPE TABLE OF rs38l-name.",
        "DATA lv_name TYPE rs38l-name.",
        "DATA lv_subrc TYPE sy-subrc.",
        "DATA ls_enlfdir TYPE enlfdir.",
        "APPEND 'Z_ORVANTA_MCP_EXECUTE' TO lt_names.",
        "APPEND 'Z_ORVANTA_MCP_DYNPRO_API' TO lt_names.",
        "APPEND 'Z_ORVANTA_MCP_DDIC_API' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  CALL FUNCTION 'FUNCTION_EXISTS'",
        "    EXPORTING funcname = lv_name",
        "    EXCEPTIONS function_not_exist = 1 others = 2.",
        "  lv_subrc = sy-subrc.",
        "  WRITE: / 'HELPER', lv_name, 'EXISTS', lv_subrc.",
        "  IF lv_subrc = 0.",
        "    CLEAR ls_enlfdir.",
        "    SELECT SINGLE * FROM enlfdir INTO ls_enlfdir",
        "      WHERE funcname = lv_name.",
        "    WRITE: / 'STATE', lv_name, ls_enlfdir-generated,",
        "      ls_enlfdir-active.",
        "  ENDIF.",
        "ENDLOOP."
    )
}

function New-RepositoryFunctionDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA ls_tfdir TYPE tfdir.",
        "DATA ls_enlfdir TYPE enlfdir.",
        "DATA lt_code TYPE TABLE OF rssource.",
        "DATA ls_code TYPE rssource.",
        "DATA lv_include TYPE sy-repid.",
        "DATA lv_group TYPE sy-repid.",
        "DATA lv_lines TYPE i.",
        "FIELD-SYMBOLS <lv_any> TYPE any.",
        "DEFINE write_component.",
        "  ASSIGN COMPONENT &1 OF STRUCTURE &2 TO <lv_any>.",
        "  IF sy-subrc = 0.",
        "    WRITE: / &1, <lv_any>.",
        "  ENDIF.",
        "END-OF-DEFINITION.",
        "CALL FUNCTION 'FUNCTION_EXISTS'",
        "  EXPORTING funcname = 'Z_ORVANTA_MCP_DYNPRO_API'",
        "  EXCEPTIONS function_not_exist = 1 OTHERS = 2.",
        "WRITE: / 'FUNCTION_EXISTS', sy-subrc.",
        "SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "  WHERE funcname = 'Z_ORVANTA_MCP_DYNPRO_API'.",
        "WRITE: / 'TFDIR_SUBRC', sy-subrc.",
        "write_component 'FUNCNAME' ls_tfdir.",
        "write_component 'PNAME' ls_tfdir.",
        "write_component 'INCLUDE' ls_tfdir.",
        "write_component 'FMODE' ls_tfdir.",
        "lv_group = ls_tfdir-pname+4.",
        "CONCATENATE 'L' lv_group 'U' ls_tfdir-include",
        "  INTO lv_include.",
        "SELECT SINGLE * FROM enlfdir INTO ls_enlfdir",
        "  WHERE funcname = 'Z_ORVANTA_MCP_DYNPRO_API'.",
        "WRITE: / 'ENLFDIR_SUBRC', sy-subrc.",
        "write_component 'FUNCNAME' ls_enlfdir.",
        "write_component 'GENERATED' ls_enlfdir.",
        "write_component 'ACTIVE' ls_enlfdir.",
        "WRITE: / 'SOURCE_INCLUDE', lv_include.",
        "READ REPORT lv_include INTO lt_code.",
        "WRITE: / 'SOURCE_SUBRC', sy-subrc.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'SOURCE_LINES', lv_lines.",
        "LOOP AT lt_code INTO ls_code.",
        "  IF sy-tabix <= 12 OR sy-tabix > lv_lines - 5.",
        "    WRITE: / 'SOURCE', sy-tabix, ls_code-line.",
        "  ENDIF.",
        "ENDLOOP."
    )
}

function New-AssignmentInspectionProgram {
    param([string]$RequestNumber)

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA ls_package TYPE tdevc.",
        "DATA ls_request TYPE e070.",
        "DATA ls_task TYPE e070.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_tfdir TYPE tfdir.",
        "DATA ls_t100 TYPE t100.",
        "DATA ls_e071 TYPE e071.",
        "DATA lv_task TYPE trkorr.",
        "DATA lv_prog_transport TYPE c LENGTH 1.",
        "SELECT SINGLE * FROM tdevc INTO ls_package",
        "  WHERE devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR PACKAGE_NOT_FOUND ZABAP'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e070 INTO ls_request",
        "  WHERE trkorr = '$RequestNumber'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR REQUEST_NOT_FOUND $RequestNumber'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_request-strkorr IS NOT INITIAL.",
        "  ls_task = ls_request.",
        "  SELECT SINGLE * FROM e070 INTO ls_request",
        "    WHERE trkorr = ls_task-strkorr.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR PARENT_REQUEST_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ELSE.",
        "  SELECT SINGLE * FROM e070 INTO ls_task",
        "    WHERE strkorr = ls_request-trkorr",
        "      AND as4user = sy-uname",
        "      AND trstatus = 'D'.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR MODIFIABLE_USER_TASK_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ENDIF.",
        "IF ls_request-trfunction <> 'K'",
        "   OR ls_request-trstatus <> 'D'.",
        "  WRITE: / 'ERROR REQUEST_NOT_MODIFIABLE_WORKBENCH',",
        "    ls_request-trfunction, ls_request-trstatus.",
        "  STOP.",
        "ENDIF.",
        "lv_task = ls_task-trkorr.",
        "WRITE: / 'PACKAGE', ls_package-devclass.",
        "WRITE: / 'REQUEST', ls_request-trkorr,",
        "  ls_request-as4user, ls_request-trstatus,",
        "  ls_request-trfunction.",
        "WRITE: / 'TASK', lv_task, ls_task-as4user,",
        "  ls_task-trstatus, ls_task-trfunction.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'BEFORE FUGR', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'BEFORE CLAS', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "    AND obj_name = 'ZCODEX_MCP_DYNPRO'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR PROG_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'DYNPRO PROG PACKAGE', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "    AND obj_name = 'ZCODEX_MCP_UI'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR TRAN_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'DYNPRO TRAN PACKAGE', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "  WHERE funcname = 'Z_ORVANTA_MCP_EXECUTE'",
        "    AND pname = 'SAPLZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUNCTION_OWNER_MISMATCH'.",
        "  STOP.",
        "ENDIF.",
        "WRITE / 'FUNCTION_OWNER ZORVANTA_MCP_CORE'.",
        "SELECT SINGLE * FROM t100 INTO ls_t100",
        "  WHERE sprsl = sy-langu AND arbgb = 'TK'",
        "    AND msgnr = '127'.",
        "IF sy-subrc = 0.",
        "  WRITE: / 'TK127', ls_t100-text.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR FUGR ZORVANTA_MCP_CORE'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR CLAS ZCL_ORVANTA_MCP_CORE'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'PROG'",
        "    AND obj_name = 'ZCODEX_MCP_DYNPRO'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = lv_task",
        "      AND pgmid = 'R3TR' AND object = 'PROG'",
        "      AND obj_name = 'ZCODEX_MCP_DYNPRO'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR PROG ZCODEX_MCP_DYNPRO'.",
        "  lv_prog_transport = 'X'.",
        "ELSE.",
        "  WRITE / 'INFO DYNPRO_PROG_NOT_IN_REQUEST'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'LIMU' AND object = 'DYNP'",
        "    AND obj_name = 'ZCODEX_MCP_DYNPRO0100'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = lv_task",
        "      AND pgmid = 'LIMU' AND object = 'DYNP'",
        "      AND obj_name = 'ZCODEX_MCP_DYNPRO0100'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT LIMU DYNP ZCODEX_MCP_DYNPRO0100'.",
        "ELSEIF lv_prog_transport = 'X'.",
        "  WRITE / 'TRANSPORT SCREEN VIA R3TR PROG'.",
        "ELSE.",
        "  WRITE / 'INFO DYNPRO_SCREEN_NOT_IN_REQUEST'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'TRAN'",
        "    AND obj_name = 'ZCODEX_MCP_UI'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = lv_task",
        "      AND pgmid = 'R3TR' AND object = 'TRAN'",
        "      AND obj_name = 'ZCODEX_MCP_UI'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR TRAN ZCODEX_MCP_UI'.",
        "ELSE.",
        "  WRITE / 'INFO DYNPRO_TRANSACTION_NOT_IN_REQUEST'.",
        "ENDIF.",
        "WRITE / 'READY'."
    )
}

function New-AssignmentProgram {
    param([string]$RequestNumber)

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA ls_package TYPE tdevc.",
        "DATA ls_request TYPE e070.",
        "DATA ls_task TYPE e070.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_new_tadir TYPE tadir.",
        "DATA ls_e071 TYPE e071.",
        "DATA lt_objects TYPE tredt_objects.",
        "DATA ls_object TYPE ko200.",
        "DATA lt_record_tadir TYPE scts_tadir.",
        "DATA lv_task TYPE trkorr.",
        "SELECT SINGLE * FROM tdevc INTO ls_package",
        "  WHERE devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR PACKAGE_NOT_FOUND ZABAP'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e070 INTO ls_request",
        "  WHERE trkorr = '$RequestNumber'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR REQUEST_NOT_FOUND $RequestNumber'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_request-strkorr IS NOT INITIAL.",
        "  ls_task = ls_request.",
        "  SELECT SINGLE * FROM e070 INTO ls_request",
        "    WHERE trkorr = ls_task-strkorr.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR PARENT_REQUEST_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ELSE.",
        "  SELECT SINGLE * FROM e070 INTO ls_task",
        "    WHERE strkorr = ls_request-trkorr",
        "      AND as4user = sy-uname",
        "      AND trstatus = 'D'.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR MODIFIABLE_USER_TASK_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ENDIF.",
        "IF ls_request-trfunction <> 'K'",
        "   OR ls_request-trstatus <> 'D'.",
        "  WRITE / 'ERROR REQUEST_NOT_MODIFIABLE_WORKBENCH'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_task-as4user <> sy-uname",
        "   OR ls_task-trstatus <> 'D'.",
        "  WRITE / 'ERROR TASK_NOT_MODIFIABLE_BY_USER'.",
        "  STOP.",
        "ENDIF.",
        "lv_task = ls_task-trkorr.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "  EXPORTING",
        "    wi_test_modus = space",
        "    wi_tadir_pgmid = ls_tadir-pgmid",
        "    wi_tadir_object = ls_tadir-object",
        "    wi_tadir_obj_name = ls_tadir-obj_name",
        "    wi_tadir_srcsystem = ls_tadir-srcsystem",
        "    wi_tadir_author = ls_tadir-author",
        "    wi_tadir_devclass = 'ZABAP'",
        "    wi_tadir_masterlang = ls_tadir-masterlang",
        "  IMPORTING new_tadir_entry = ls_new_tadir",
        "  EXCEPTIONS others = 1.",
        "IF sy-subrc <> 0 OR ls_new_tadir-devclass <> 'ZABAP'.",
        "  WRITE: / 'ERROR FUGR_PACKAGE_CHANGE', sy-subrc,",
        "    sy-msgid, sy-msgno.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR ls_object.",
        "MOVE-CORRESPONDING ls_new_tadir TO ls_object.",
        "APPEND ls_object TO lt_objects.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_TADIR_NOT_FOUND'.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "  EXPORTING",
        "    wi_test_modus = space",
        "    wi_tadir_pgmid = ls_tadir-pgmid",
        "    wi_tadir_object = ls_tadir-object",
        "    wi_tadir_obj_name = ls_tadir-obj_name",
        "    wi_tadir_srcsystem = ls_tadir-srcsystem",
        "    wi_tadir_author = ls_tadir-author",
        "    wi_tadir_devclass = 'ZABAP'",
        "    wi_tadir_masterlang = ls_tadir-masterlang",
        "  IMPORTING new_tadir_entry = ls_new_tadir",
        "  EXCEPTIONS others = 1.",
        "IF sy-subrc <> 0 OR ls_new_tadir-devclass <> 'ZABAP'.",
        "  WRITE: / 'ERROR CLAS_PACKAGE_CHANGE', sy-subrc,",
        "    sy-msgid, sy-msgno.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR ls_object.",
        "MOVE-CORRESPONDING ls_new_tadir TO ls_object.",
        "APPEND ls_object TO lt_objects.",
        "CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "  EXPORTING iv_request = ls_request-trkorr",
        "    it_objects = lt_objects",
        "  IMPORTING et_tadir = lt_record_tadir",
        "  EXCEPTIONS cancel = 1.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'ERROR TRANSPORT_RECORD', sy-subrc,",
        "    sy-msgid, sy-msgno.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "COMMIT WORK AND WAIT.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'",
        "    AND devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_PACKAGE_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'",
        "    AND devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_PACKAGE_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR'",
        "    AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TRANSPORT_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR'",
        "    AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_TRANSPORT_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'ASSIGNMENT_OK PACKAGE ZABAP'.",
        "WRITE: / 'REQUEST', ls_request-trkorr.",
        "WRITE: / 'TASK', lv_task.",
        "LOOP AT lt_objects INTO ls_object.",
        "  WRITE: / 'OBJECT', ls_object-pgmid,",
        "    ls_object-object, ls_object-obj_name.",
        "ENDLOOP."
    )
}

function New-SoapEnvelope {
    param([string[]]$ProgramLines)

    foreach ($line in $ProgramLines) {
        if ($line.Length -gt 72) {
            throw "Bootstrap ABAP line exceeds 72 characters: $line"
        }
    }

    $settings = [Xml.XmlWriterSettings]::new()
    $settings.OmitXmlDeclaration = $false
    $settings.Encoding = [Text.UTF8Encoding]::new($false)
    $builder = [Text.StringBuilder]::new()
    $writer = [Xml.XmlWriter]::Create($builder, $settings)
    try {
        $writer.WriteStartDocument()
        $writer.WriteStartElement(
            "soapenv",
            "Envelope",
            "http://schemas.xmlsoap.org/soap/envelope/"
        )
        $writer.WriteStartElement(
            "soapenv",
            "Body",
            "http://schemas.xmlsoap.org/soap/envelope/"
        )
        $writer.WriteStartElement(
            "n1",
            "Z_AW_RFC_ABAP_INSTALL_AND_RUN",
            "urn:sap-com:document:sap:rfc:functions"
        )
        $writer.WriteElementString("MODE", "F")
        $writer.WriteElementString("PROGRAMNAME", 'Z$$$XRFC')
        $writer.WriteStartElement("PROGRAM")
        foreach ($line in $ProgramLines) {
            $writer.WriteStartElement("item")
            $writer.WriteElementString("LINE", $line)
            $writer.WriteEndElement()
        }
        $writer.WriteEndElement()
        $writer.WriteStartElement("WRITES")
        $writer.WriteEndElement()
        $writer.WriteEndElement()
        $writer.WriteEndElement()
        $writer.WriteEndElement()
        $writer.WriteEndDocument()
    }
    finally {
        $writer.Dispose()
    }
    return $builder.ToString()
}

function Get-LocalNameText {
    param(
        [xml]$Document,
        [string]$LocalName
    )

    $node = $Document.SelectSingleNode("//*[local-name()='$LocalName']")
    if ($node) {
        return $node.InnerText
    }
    return ""
}

function ConvertFrom-SapSoapResponse {
    param(
        [string]$ResponseBody,
        [int]$StatusCode,
        [string]$ContentType
    )

    $responseBytes = [Text.Encoding]::UTF8.GetByteCount($ResponseBody)
    $trimmedBody = $ResponseBody.TrimStart()
    $isHtml = $ContentType -match "(?i)(?:text/html|application/xhtml)" -or
        $trimmedBody -match "(?is)(?:<!DOCTYPE\s+html\b|<html\b|<head\b.{0,4096}<meta\b)"
    if ($isHtml) {
        $summary = [regex]::Replace(
            $ResponseBody,
            "(?is)<(?:script|style)\b[^>]*>.*?</(?:script|style)>",
            " "
        )
        $summary = [regex]::Replace($summary, "(?s)<[^>]*>", " ")
        $summary = [Net.WebUtility]::HtmlDecode($summary)
        $summary = [regex]::Replace($summary, "\s+", " ").Trim()
        if (-not $summary) {
            $summary = "无可读正文"
        }
        elseif ($summary.Length -gt 600) {
            $summary = $summary.Substring(0, 600) + "..."
        }
        throw "SAP SOAP端点返回了HTML登录或错误页面（HTTP $StatusCode，Content-Type: $ContentType，响应字节: $responseBytes）。摘要: $summary。请检查用户名、密码、SAP客户端以及/sap/bc/soap/rfc服务状态。"
    }

    # The legacy bootstrap RFC injects bare HTML paragraph markers into
    # long WRITE output instead of XML-escaping them.
    $sanitizedResponseBody = $ResponseBody -replace "(?i)<P(?:\s[^>]*)?>", ""
    try {
        return [xml]$sanitizedResponseBody
    }
    catch {
        $message = $_.Exception.GetBaseException().Message
        throw "SAP SOAP端点返回了无法解析的XML（HTTP $StatusCode，Content-Type: $ContentType，响应字节: $responseBytes）：$message"
    }
}

if ($Action -in @("InspectAssignment", "AssignPackageTransport") -and -not $TransportNumber) {
    throw "TransportNumber is required for $Action."
}

$program = switch ($Action) {
    "DiagnoseHelperApis" { New-HelperApiDiagnosticProgram }
    "InspectStructures" { New-InspectionProgram }
    "InspectInterface" { New-InterfaceInspectionProgram }
    "InspectRepositoryApis" { New-RepositoryApiInspectionProgram }
    "InspectGuiApis" { New-GuiApiInspectionProgram }
    "InspectGuiObject" { New-GuiObjectInspectionProgram }
    "InspectDdicApis" { New-DdicApiInspectionProgram }
    "DiagnoseDdicObject" { New-DdicObjectDiagnosticProgram }
    "Install" { New-InstallProgram }
    "RepairInterface" { New-InstallProgram -ReplaceExisting }
    "InstallRepositoryApi" {
        New-InstallProgram -FunctionName "Z_ORVANTA_MCP_DYNPRO_API"
    }
    "RepairRepositoryApi" {
        New-InstallProgram -ReplaceExisting -FunctionName "Z_ORVANTA_MCP_DYNPRO_API"
    }
    "InstallDdicApi" {
        New-InstallProgram -FunctionName "Z_ORVANTA_MCP_DDIC_API"
    }
    "RepairDdicApi" {
        New-InstallProgram -ReplaceExisting -FunctionName "Z_ORVANTA_MCP_DDIC_API"
    }
    "DiagnoseFunctionGroup" { New-FunctionGroupDiagnosticProgram }
    "DiagnoseRepositoryApi" { New-RepositoryFunctionDiagnosticProgram }
    "InspectAssignment" { New-AssignmentInspectionProgram -RequestNumber $TransportNumber }
    "AssignPackageTransport" { New-AssignmentProgram -RequestNumber $TransportNumber }
}

$effectiveSecurePassword = if ($SecurePassword) {
    $SecurePassword
} else {
    Read-Host "Password for $Username" -AsSecureString
}
if ($effectiveSecurePassword.Length -eq 0) {
    throw "Password cannot be empty."
}
$passwordPointer = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($effectiveSecurePassword)
$httpClient = $null
$plainPassword = $null
$result = $null
$exitCode = 0
$statusCode = $null
$contentType = $null
$responseBytes = $null
$rawPath = $null

try {
    $plainPassword = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($passwordPointer)
    $credential = [Convert]::ToBase64String(
        [Text.Encoding]::UTF8.GetBytes("${Username}:$plainPassword")
    )
    if ($AllowUnauthorized) {
        $handler = [Net.Http.HttpClientHandler]::new()
        $handler.ServerCertificateCustomValidationCallback = { $true }
        $httpClient = [Net.Http.HttpClient]::new($handler)
    } else {
        $httpClient = [Net.Http.HttpClient]::new()
    }
    $httpClient.Timeout = [TimeSpan]::FromSeconds(180)
    $httpClient.DefaultRequestHeaders.Authorization =
        [Net.Http.Headers.AuthenticationHeaderValue]::new("Basic", $credential)

    $envelope = New-SoapEnvelope -ProgramLines $program
    $content = [Net.Http.StringContent]::new(
        $envelope,
        [Text.Encoding]::UTF8,
        "text/xml"
    )
    $content.Headers.Add(
        "SOAPAction",
        "http://www.sap.com/Z_AW_RFC_ABAP_INSTALL_AND_RUN"
    )
    $normalizedBaseUrl = $BaseUrl.TrimEnd("/")
    $uri = "$normalizedBaseUrl/sap/bc/soap/rfc?sap-client=$Client&sap-language=$Language"
    $response = $httpClient.PostAsync($uri, $content).GetAwaiter().GetResult()
    $responseBody = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
    $statusCode = [int]$response.StatusCode
    $contentType = [string]$response.Content.Headers.ContentType
    $responseBytes = [Text.Encoding]::UTF8.GetByteCount($responseBody)
    if ($ResultPath) {
        $rawPath = "$([IO.Path]::GetFullPath($ResultPath)).raw.xml"
        [IO.File]::WriteAllText(
            $rawPath,
            $responseBody,
            [Text.UTF8Encoding]::new($false)
        )
    }
    $responseXml = ConvertFrom-SapSoapResponse `
        -ResponseBody $responseBody `
        -StatusCode $statusCode `
        -ContentType $contentType
    $fault = Get-LocalNameText -Document $responseXml -LocalName "faultstring"
    $errorMessage = Get-LocalNameText -Document $responseXml -LocalName "ERRORMESSAGE"
    $writeNodes = $responseXml.SelectNodes("//*[local-name()='WRITES']/*[local-name()='item']/*[local-name()='ZEILE']")
    $writes = @($writeNodes | ForEach-Object { $_.InnerText.TrimEnd() })
    $writeError = $writes |
        Where-Object {
            $_ -match "^(?:CREATE|DELETE|EXISTENCE_CHECK|SOURCE_(?:READ|MARKER|INSERT)|GENERATE)_ERROR\b"
        } |
        Select-Object -First 1
    if (-not $errorMessage -and $writeError) {
        $errorMessage = $writeError
    }

    $result = [pscustomobject]@{
        Action       = $Action
        Status       = $statusCode
        ContentType  = $contentType
        ResponseBytes = $responseBytes
        RawResponsePath = $rawPath
        SoapFault    = $fault
        ErrorMessage = $errorMessage
        Writes       = $writes
    }
    if (-not $response.IsSuccessStatusCode -or $fault -or $errorMessage) {
        $exitCode = 2
    }
}
catch {
    $result = [pscustomobject]@{
        Action          = $Action
        Status          = $statusCode
        ContentType     = $contentType
        ResponseBytes   = $responseBytes
        RawResponsePath = $rawPath
        Error           = $_.Exception.GetBaseException().Message
    }
    $exitCode = 1
}
finally {
    if ($httpClient) {
        $httpClient.Dispose()
    }
    $plainPassword = $null
    [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($passwordPointer)
    Remove-Variable effectiveSecurePassword -ErrorAction SilentlyContinue
}

$result | Add-Member -NotePropertyName BootstrapExitCode -NotePropertyValue $exitCode -Force
if ($PassThru) {
    Write-Output $result
    return
}

$json = $result | ConvertTo-Json -Depth 5
if ($ResultPath) {
    $resolvedResultPath = [IO.Path]::GetFullPath($ResultPath)
    [IO.File]::WriteAllText($resolvedResultPath, $json, [Text.UTF8Encoding]::new($false))
}
Write-Output $json
exit $exitCode
